  if (!normalizedProgramType) return;
  const platformStatus = await runtimeGetPlatformStatus();
  const currentOptions = Array.isArray(platformStatus?.courseProgramTypeOptions) ? platformStatus.courseProgramTypeOptions.map(item => String(item || "").trim()).filter(Boolean) : [];
  const alreadyIncluded = currentOptions.some(item => item.toLowerCase() === normalizedProgramType.toLowerCase());
