function mergeCourseCategoryOptions(options = [], courses = []) {
  const merged = [];
  const seen = new Set();
  for (const item of options) {
    const normalized = String(item || "").trim();
    if (!normalized) continue;
    const key = normalized.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(normalized);
  }
  for (const course of courses) {
    const normalized = String(course?.category || "").trim();
    if (!normalized) continue;
    const key = normalized.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(normalized);
  }
  return merged;
}
function mergeCourseProgramTypeOptions(options = [], courses = []) {
  const merged = [];
  const seen = new Set();
  for (const item of options) {
    const normalized = isGovernmentProgramTypeValue(item) ? "정부지원금" : String(item || "").trim();
    if (!normalized) continue;
    const key = normalized.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(normalized);
  }
  for (const course of courses) {
    const normalized = isGovernmentProgramTypeValue(course?.programType) ? "정부지원금" : String(course?.programType || "").trim();
    if (!normalized) continue;
    const key = normalized.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(normalized);
  }
  return merged;
}
async function ensureArenaAccess(req, res) {
  const platformStatus = await runtimeGetPlatformStatus();
  if (!platformStatus.arenaEnabled && req.user?.role !== "admin") {
    res.status(503).json({
      message: "서비스 준비중 입니다"
    });
    return false;
  }
  if (!ARENA_ACCESS_ADMIN_ONLY) return true;
  if (req.user?.role === "admin") return true;
  res.status(403).json({
    message: "준비중 입니다"
  });
  return false;
}
function addSeconds(baseIso, seconds) {
  return new Date(new Date(baseIso).getTime() + Math.max(1, Number(seconds || 0)) * 1000).toISOString();
}
function buildArenaLeaderboard(nodes = []) {
  const counts = new Map();
  for (const node of nodes) {
    const handle = String(node.currentOwnerHandle || "").trim();
    if (!handle) continue;
    counts.set(handle, (counts.get(handle) || 0) + 1);
  }
  return [...counts.entries()].map(([handle, captures]) => ({
    handle,
    captures,
    label: `hack: ${handle}`
  })).sort((left, right) => right.captures - left.captures || left.handle.localeCompare(right.handle)).slice(0, 10);
}
