async function buildArenaOverview(user) {
  const season = await getArenaActiveSeason();
  if (!season) {
    return {
      season: null,
      nodes: [],
      leaderboard: [],
      events: [],
      activeSession: null,
      stats: {
        totalNodes: 0,
        capturedNodes: 0,
        activePlayers: 0,
        bossOpen: false
      },
      accessMode: ARENA_ACCESS_ADMIN_ONLY ? "admin_only" : "open",
      myStatus: null
    };
  }
  const [nodes, events, activeSession] = await Promise.all([runtimeListArenaNodesBySeasonId(season.id), runtimeListArenaEventsBySeasonId(season.id, 20), user ? runtimeFindActiveArenaSessionByUserId(user.id) : Promise.resolve(null)]);
  const capturedNodes = nodes.filter(item => item.currentOwnerUserId != null).length;
  const bossOpen = nodes.some(item => item.tier === "boss" && item.status !== "locked");
  return {
    season: {
      id: season.id,
      code: season.code,
      title: season.title,
      status: season.status,
      resetPolicy: season.resetPolicy,
      startedAt: season.startedAt,
      endsAt: season.endsAt
    },
    nodes: nodes.map(serializeArenaNode),
    leaderboard: buildArenaLeaderboard(nodes),
    events: events.map(item => ({
      id: item.id,
      type: item.eventType,
      message: item.message,
      createdAt: item.createdAt,
      payload: item.payload
    })),
    activeSession: serializeArenaSession(activeSession),
    stats: {
      totalNodes: nodes.length,
      capturedNodes,
      activePlayers: buildArenaLeaderboard(nodes).length,
      activeUsers: buildArenaLeaderboard(nodes).length,
      bossOpen,
      bossOpened: bossOpen
    },
    accessMode: ARENA_ACCESS_ADMIN_ONLY ? "admin_only" : "open",
    myStatus: user ? {
      username: user.username,
      role: user.role,
      activeSessionId: activeSession?.id || null,
      captures: nodes.filter(item => String(item.currentOwnerHandle || "") === String(user.username || "")).length
    } : null
  };
}
