async function terminateArenaSessionRecord({
  sessionRecord,
  actorUser,
  terminatedReason = "user_terminated",
  eventType = "terminate",
  eventMessage,
  createAttempt = true,
  attemptResult = "abandoned",
  attemptUserId
}) {
  if (!sessionRecord) return null;
  const terminatedAt = new Date().toISOString();
  const platformStatus = await runtimeGetPlatformStatus();
  await terminateArenaSession({
    sessionRecord,
    platformStatus,
    serviceProjectName: getServiceProjectName(platformStatus),
    zunProjectName: getZunProjectName(platformStatus)
  });
  const {
    remainingSeconds,
    durationSeconds
  } = computeArenaSessionDurations(sessionRecord, terminatedAt);
  const updated = await runtimeUpdateArenaSession(sessionRecord.id, {
    state: "terminated",
    endedAt: terminatedAt,
    terminatedReason,
    metadata: {
      ...sessionRecord.metadata,
      terminatedAt,
      terminatedBy: actorUser?.username || ""
    }
  });
  if (createAttempt) {
    await runtimeCreateArenaAttempt({
      sessionId: sessionRecord.id,
      seasonId: sessionRecord.seasonId,
      nodeId: sessionRecord.nodeId,
      userId: attemptUserId ?? actorUser?.id ?? sessionRecord.userId,
      result: attemptResult,
      score: 0,
      mmrDelta: 0,
      rankDelta: 0,
      durationSeconds,
      firstTryBonus: 0,
      remainingSeconds,
      createdAt: terminatedAt
    });
  }
  await publishArenaEvent({
    seasonId: sessionRecord.seasonId,
    nodeId: sessionRecord.nodeId,
    userId: actorUser?.id || null,
    eventType,
    message: eventMessage || `hack: ${actorUser?.username || "system"} left ${sessionRecord.nodeCode}`,
    payload: {
      sessionId: sessionRecord.id,
      terminatedReason
    }
  });
  return updated;
}
function computeArenaSessionDurations(sessionRecord, finishedAtIso) {
  const finishedAt = String(finishedAtIso || new Date().toISOString());
  const remainingSeconds = sessionRecord?.expiresAt ? Math.max(0, Math.floor((new Date(sessionRecord.expiresAt).getTime() - new Date(finishedAt).getTime()) / 1000)) : 0;
  const durationSeconds = sessionRecord?.startedAt ? Math.max(0, Math.floor((new Date(finishedAt).getTime() - new Date(sessionRecord.startedAt).getTime()) / 1000)) : 0;
  return {
    remainingSeconds,
    durationSeconds,
    finishedAt
  };
}
async function createArenaTerminalSession({
  userId,
  sessionRecord,
  platformStatus,
  cols = 120,
  rows = 32
}) {
  const consoleType = String(sessionRecord?.consoleType || "").trim().toLowerCase();
  const backendType = String(sessionRecord?.backendType || "").trim().toLowerCase();
  const sessionId = randomUUID();
  const common = {
    id: sessionId,
    userId,
    resourceType: "arena-assessment",
    labId: null,
    courseId: null,
    nodeId: String(sessionRecord?.nodeCode || sessionRecord?.nodeId || "").trim(),
    nodeName: String(sessionRecord?.nodeLabel || sessionRecord?.resourceName || "역량 진단").trim(),
    targetLabel: `${sessionRecord?.nodeCode || "진단"} / ${sessionRecord?.resourceName || "terminal"}`,
    replayMetadata: {
      purpose: "skill-assessment",
      arenaSessionId: sessionRecord.id
    },
    createdAt: Date.now(),
    lastActivityAt: Date.now()
  };
  if (backendType === "container") {
    if (!platformStatus?.zunApiUrl || !sessionRecord?.resourceId) throw new Error("컨테이너 터미널 연결 정보가 준비되지 않았습니다.");
    const projectName = getZunProjectName(platformStatus);
    await ensureZunContainerRunning({
      apiUrl: platformStatus.zunApiUrl,
      containerUuid: sessionRecord.resourceId,
      projectName
    });
    const connection = await prepareZunInteractiveConnection({
      apiUrl: platformStatus.zunApiUrl,
      containerUuid: sessionRecord.resourceId,
      projectName,
      shellCommand: "/bin/sh -i"
    });
    terminalSessions.set(sessionId, {
      ...common,
      mode: connection.mode,
      containerUuid: sessionRecord.resourceId,
      apiUrl: platformStatus.zunApiUrl,
      projectName,
      execId: connection.execId,
      wsUrl: connection.wsUrl,
      shellCommand: connection.shellCommand,
      terminalCols: cols,
      terminalRows: rows
    });
  } else if (consoleType === "serial") {
    const serverId = String(sessionRecord?.metadata?.serverId || sessionRecord?.resourceId || "").trim();
    if (!serverId) throw new Error("Serial console 대상 VM을 확인하지 못했습니다.");
    const consoleEntry = await createOpenstackRemoteConsole({
      serverId,
      protocol: "serial",
      type: "serial",
      projectName: getServiceProjectName(platformStatus)
    });
    const wsUrl = String(consoleEntry?.url || "").trim();
    if (!/^wss?:\/\//i.test(wsUrl)) throw new Error("OpenStack serial WebSocket URL을 받지 못했습니다.");
    terminalSessions.set(sessionId, {
      ...common,
      mode: "openstack-serial",
      wsUrl
    });
  } else if (consoleType === "ssh") {
    const host = String(sessionRecord?.metadata?.instanceIp || "").trim();
    if (!host) throw new Error("SSH 대상 VM IP를 확인하지 못했습니다.");
    terminalSessions.set(sessionId, {
      ...common,
      mode: "ssh",
      host,
      hostType: "fixed",
      username: ARENA_VM_SSH_USER,
      password: ARENA_VM_SSH_PASSWORD,
      port: 22,
      jumpHost: "",
      jumpUser: ""
    });
  } else {
    throw new Error("실무 역량 진단은 serial, SSH 또는 컨테이너 exec 콘솔만 지원합니다.");
  }
  return buildTerminalSessionResponse(terminalSessions.get(sessionId), "실무 역량 진단 xterm 연결을 준비했습니다.");
}
function parseArenaValidationRulesInput(value, fallback = []) {
  if (Array.isArray(value)) return value;
  const raw = String(value || "").trim();
  if (!raw) return fallback;
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : fallback;
  } catch {
    return fallback;
  }
}
function normalizeArenaConsoleType(value, backendType) {
  const normalizedBackend = String(backendType || "container").trim().toLowerCase();
  const normalized = String(value || (normalizedBackend === "vm" ? "serial" : "xterm")).trim().toLowerCase();
  const allowed = normalizedBackend === "vm" ? ["serial", "ssh"] : ["xterm"];
  if (!allowed.includes(normalized)) {
    const error = new Error(normalizedBackend === "vm" ? "VM 진단 콘솔은 serial 또는 SSH만 사용할 수 있습니다. VNC/noVNC는 허용되지 않습니다." : "컨테이너 진단 콘솔은 xterm exec만 사용할 수 있습니다.");
    error.status = 400;
    throw error;
  }
  return normalized;
}
function parseEnvFlag(value, fallback = true) {
  const raw = String(value ?? "").trim().toLowerCase();
  if (!raw) return fallback;
  if (["0", "false", "no", "off", "disabled"].includes(raw)) return false;
  if (["1", "true", "yes", "on", "enabled"].includes(raw)) return true;
  return fallback;
}
function resolveOpenstackStatusCacheTtlMs(settings = null) {
  const minutes = Number(settings?.openstackStatusCacheTtlMinutes || 0);
  if (Number.isFinite(minutes) && minutes > 0) {
    return Math.max(60_000, Math.min(24 * 60 * 60_000, Math.round(minutes * 60_000)));
  }
  return Math.max(60_000, Math.min(24 * 60 * 60_000, Number(API_STATUS_CACHE_TTL_MS || 600000) || 600000));
}
