async function withCourseLabCreationLock(key, task) {
  const previous = courseLabCreationLocks.get(key);
  let release;
  const current = new Promise(resolve => {
    release = resolve;
  });
  courseLabCreationLocks.set(key, current);
  if (previous) {
    await previous.catch(() => {});
  }
  try {
    return await task();
  } finally {
    release();
    if (courseLabCreationLocks.get(key) === current) {
      courseLabCreationLocks.delete(key);
    }
  }
}
