async function startTerminalReplayRecording(terminalSession, metadata = {}) {
  if (!TERMINAL_REPLAY_ENABLED || terminalSession?.replaySessionId) return;
  try {
    const [platformStatus, course] = await Promise.all([runtimeGetPlatformStatus(), terminalSession.courseId ? runtimeFindCourseById(terminalSession.courseId) : Promise.resolve(null)]);
    const courseMode = String(course?.terminalReplayMode || "inherit").trim();
    const enabled = courseMode === "enabled" ? true : courseMode === "disabled" ? false : platformStatus?.terminalReplayEnabled !== false;
    if (!enabled) {
      terminalSession.replayDisabled = true;
      return;
    }
  } catch (error) {
    terminalSession.replayDisabled = true;
    console.warn("[terminal-replay] failed to resolve recording policy", error?.message || error);
    return;
  }
  const replaySessionId = randomUUID();
  const startedAt = Date.now();
  terminalSession.replaySessionId = replaySessionId;
  terminalSession.replayStartedAt = startedAt;
  terminalSession.replayFinished = false;
  try {
    const replayMetadata = {
      ...sanitizeTerminalReplayMetadata(terminalSession.replayMetadata),
      ...(metadata && typeof metadata === "object" ? metadata : {})
    };
    await runtimeCreateTerminalReplaySession({
      id: replaySessionId,
      userId: terminalSession.userId,
      labRequestId: terminalSession.labId,
      courseId: terminalSession.courseId,
      nodeId: terminalSession.nodeId,
      nodeName: terminalSession.nodeName,
      mode: terminalSession.mode || "ssh",
      targetLabel: terminalSession.nodeName || terminalSession.host || "",
      startedAt: new Date(startedAt).toISOString(),
      metadata: replayMetadata
    });
  } catch (error) {
    terminalSession.replayDisabled = true;
    console.warn("[terminal-replay] failed to start recording", error?.message || error);
  }
}
function recordTerminalReplayEvent(terminalSession, eventType, payload = {}) {
  if (!TERMINAL_REPLAY_ENABLED || terminalSession?.replayDisabled || !terminalSession?.replaySessionId && !terminalSession?.replayStartPromise) return;
  const pendingCount = Number(terminalSession.replayPendingEventCount || 0);
  if (pendingCount >= TERMINAL_REPLAY_PENDING_EVENT_LIMIT) {
    terminalSession.replayDisabled = true;
    console.warn("[terminal-replay] disabled recording because pending event queue is full", {
      sessionId: terminalSession.id,
      replaySessionId: terminalSession.replaySessionId,
      pendingCount
    });
    return;
  }
  const offsetMs = Math.max(0, Date.now() - Number(terminalSession.replayStartedAt || Date.now()));
  terminalSession.replayPendingEventCount = pendingCount + 1;
  const replayStartPromise = terminalSession.replayStartPromise || Promise.resolve();
  const appendEvent = async () => {
    await replayStartPromise;
    if (terminalSession.replayDisabled || !terminalSession.replaySessionId) return null;
    return runtimeAppendTerminalReplayEvent({
      replaySessionId: terminalSession.replaySessionId,
      offsetMs,
      eventType,
      payload
    });
  };
  terminalSession.replayEventChain = (terminalSession.replayEventChain || Promise.resolve()).then(appendEvent, appendEvent).catch(error => {
    terminalSession.replayDisabled = true;
    console.warn("[terminal-replay] failed to append event", error?.message || error);
  }).finally(() => {
    terminalSession.replayPendingEventCount = Math.max(0, Number(terminalSession.replayPendingEventCount || 0) - 1);
  });
}
function finishTerminalReplayRecording(terminalSession, status = "finished") {
  if (!TERMINAL_REPLAY_ENABLED || terminalSession?.replayFinishScheduled || terminalSession?.replayFinished) return;
  terminalSession.replayFinishScheduled = true;
  const finalize = async () => {
    await (terminalSession.replayStartPromise || Promise.resolve());
    await (terminalSession.replayEventChain || Promise.resolve());
    if (terminalSession.replayDisabled || !terminalSession.replaySessionId || terminalSession.replayFinished) return;
    terminalSession.replayFinished = true;
    const durationMs = Math.max(0, Date.now() - Number(terminalSession.replayStartedAt || Date.now()));
    await runtimeFinishTerminalReplaySession(terminalSession.replaySessionId, {
      durationMs,
      status
    });
  };
  void finalize().catch(error => {
    console.warn("[terminal-replay] failed to finish recording", error?.message || error);
  });
}
function probeTcpPort(host, port, timeoutMs = 1500) {
  return new Promise(resolve => {
    const normalizedHost = String(host || "").trim();
    const normalizedPort = Number(port || 0);
    if (!normalizedHost || !Number.isFinite(normalizedPort) || normalizedPort <= 0) {
      resolve(false);
      return;
    }
    const socket = new net.Socket();
    let settled = false;
    const finish = result => {
      if (settled) return;
      settled = true;
      try {
        socket.destroy();
      } catch {}
      resolve(result);
    };
    socket.setTimeout(timeoutMs);
    socket.once("connect", () => finish(true));
    socket.once("timeout", () => finish(false));
    socket.once("error", () => finish(false));
    try {
      socket.connect(normalizedPort, normalizedHost);
    } catch {
      finish(false);
    }
  });
}
function getLabBootReadinessKey(labId, nodeId = "") {
  const normalizedLabId = Number(labId || 0);
  if (!normalizedLabId) return "";
  const normalizedNodeId = String(nodeId || "").trim();
  return normalizedNodeId ? `${normalizedLabId}:${normalizedNodeId}` : normalizedLabId;
}
function markLabBootReadinessPending(labId, startedAtMs = Date.now(), nodeId = "") {
  const normalizedLabId = Number(labId || 0);
  const normalizedStartedAtMs = Number(startedAtMs || 0);
  if (!normalizedLabId || !Number.isFinite(normalizedStartedAtMs) || normalizedStartedAtMs <= 0) return;
  labBootReadinessStartedAt.set(getLabBootReadinessKey(normalizedLabId, nodeId), normalizedStartedAtMs);
}
function clearLabBootReadinessPending(labId, nodeId = "") {
  const normalizedLabId = Number(labId || 0);
  if (!normalizedLabId) return;
  const nodeKey = getLabBootReadinessKey(normalizedLabId, nodeId);
  if (nodeId && labBootReadinessStartedAt.has(nodeKey)) {
    labBootReadinessStartedAt.delete(nodeKey);
    return;
  }
  labBootReadinessStartedAt.delete(normalizedLabId);
  if (!nodeId) {
    const nodeKeyPrefix = `${normalizedLabId}:`;
    for (const key of labBootReadinessStartedAt.keys()) {
      if (String(key).startsWith(nodeKeyPrefix)) labBootReadinessStartedAt.delete(key);
    }
  }
}
function resolveLabBootReferenceMs(lab, nodeId = "") {
  const labId = Number(lab?.id || 0);
  const nodeStartedAt = labId && nodeId ? Number(labBootReadinessStartedAt.get(getLabBootReadinessKey(labId, nodeId)) || 0) : 0;
  const inMemoryStartedAt = nodeStartedAt || (labId ? Number(labBootReadinessStartedAt.get(labId) || 0) : 0);
  if (Number.isFinite(inMemoryStartedAt) && inMemoryStartedAt > 0) return inMemoryStartedAt;
  return [lab?.startedAt, lab?.approvedAt, lab?.createdAt].map(value => toTimeMs(value)).find(value => value > 0) || 0;
}
function resolveTerminalSshHostKeyOptions({
  resourceType = "lab",
  labId = "",
  customLabRequestId = "",
  nodeId = "",
  host = ""
} = {}) {
  return buildSshHostKeyOptions({
    resourceType,
    resourceId: customLabRequestId || labId,
    nodeId,
    host
  }, {
    baseFile: SSH_KNOWN_HOSTS_FILE,
    scope: SSH_KNOWN_HOSTS_SCOPE
  });
}
async function removeGlobalSshKnownHostAlias(hostKeyAlias) {
  try {
    await fs.access(SSH_KNOWN_HOSTS_FILE);
  } catch (error) {
    if (error?.code === "ENOENT") return false;
    throw error;
  }
  return new Promise((resolve, reject) => {
    const child = spawn(SSH_KEYGEN_COMMAND, ["-f", SSH_KNOWN_HOSTS_FILE, "-R", hostKeyAlias], {
      cwd: process.cwd(),
      env: process.env,
      windowsHide: true,
      stdio: ["ignore", "pipe", "pipe"]
    });
    let stderr = "";
    child.stderr.on("data", chunk => {
      stderr += String(chunk || "");
      if (stderr.length > 4000) stderr = stderr.slice(-4000);
    });
    child.once("error", reject);
    child.once("exit", code => {
      if (Number(code) === 0) {
        resolve(true);
        return;
      }
      reject(new Error(stderr.trim() || `ssh-keygen exited with code ${code}`));
    });
  });
}
async function clearTerminalSshHostKeyTrust(target, reason = "resource-lifecycle", {
  throwOnError = false
} = {}) {
  const options = resolveTerminalSshHostKeyOptions(target);
  if (SSH_KNOWN_HOSTS_SCOPE === "none" || isSshKnownHostsSink(options.knownHostsFile)) {
    return {
      removed: false,
      skipped: true
    };
  }
  try {
    let removed = true;
    if (SSH_KNOWN_HOSTS_SCOPE === "resource") {
      await fs.unlink(options.knownHostsFile).catch(error => {
        if (error?.code === "ENOENT") {
          removed = false;
          return;
        }
        throw error;
      });
    } else {
      removed = await removeGlobalSshKnownHostAlias(options.hostKeyAlias);
    }
    if (removed) {
      console.info("[terminal] cleared SSH host key trust", {
        reason,
        resourceType: target.resourceType || "lab",
        labId: target.customLabRequestId || target.labId || null,
        nodeId: target.nodeId || "",
        hostKeyAlias: options.hostKeyAlias
      });
    }
    return {
      removed,
      skipped: false
    };
  } catch (error) {
    console.warn("[terminal] failed to clear SSH host key trust", {
      reason,
      resourceType: target.resourceType || "lab",
      labId: target.customLabRequestId || target.labId || null,
      nodeId: target.nodeId || "",
      hostKeyAlias: options.hostKeyAlias,
      message: error?.message || String(error)
    });
    if (throwOnError) throw error;
    return {
      removed: false,
      skipped: false,
      error
    };
  }
}
async function clearLabSshHostKeyTrust(lab, {
  nodeId = "",
  reason = "lab-lifecycle",
  resourceType = "lab",
  throwOnError = false
} = {}) {
  if (!lab?.id) return [];
  const normalizedNodeId = String(nodeId || "").trim();
  let nodes = deriveTerminalNodes(lab);
  if (normalizedNodeId) {
    nodes = nodes.filter(node => String(node?.id || "").trim() === normalizedNodeId);
  }
  if (!nodes.length) {
    nodes = [{
      id: normalizedNodeId || "node-1",
      fixedIp: String(lab?.instanceIp || "").trim(),
      floatingIp: ""
    }];
  }
  const targets = nodes.map(node => ({
    resourceType,
    labId: resourceType === "custom-lab" ? "" : lab.id,
    customLabRequestId: resourceType === "custom-lab" ? lab.id : "",
    nodeId: String(node?.id || normalizedNodeId || "").trim(),
    host: String(node?.fixedIp || node?.floatingIp || lab?.instanceIp || "").trim()
  }));
  const seenAliases = new Set();
  const results = [];
  for (const target of targets) {
    const {
      hostKeyAlias
    } = resolveTerminalSshHostKeyOptions(target);
    if (seenAliases.has(hostKeyAlias)) continue;
    seenAliases.add(hostKeyAlias);
    results.push(await clearTerminalSshHostKeyTrust(target, reason, {
      throwOnError
    }));
  }
  return results;
}
function probeSshServiceReady({
  host,
  port,
  username = "",
  jumpHost = "",
  jumpUser = "",
  resourceType = "lab",
  labId = "",
  nodeId = "",
  timeoutMs = VM_BOOT_READY_PROBE_TIMEOUT_MS
}) {
  return new Promise(resolve => {
    const normalizedHost = String(host || "").trim();
    const normalizedPort = Math.max(1, Number(port || 22) || 22);
    if (!normalizedHost) {
      resolve({
        ready: false,
        reason: "missing-host",
        output: ""
      });
      return;
    }
    const hostKeyOptions = resolveTerminalSshHostKeyOptions({
      resourceType,
      labId,
      nodeId,
      host: normalizedHost
    });
    const args = ["-o", `StrictHostKeyChecking=${SSH_STRICT_HOST_KEY_CHECKING}`, "-o", `UserKnownHostsFile=${hostKeyOptions.knownHostsFile}`, "-o", `HostKeyAlias=${hostKeyOptions.hostKeyAlias}`, "-o", "CheckHostIP=no", "-o", "BatchMode=yes", "-o", "PubkeyAuthentication=no", "-o", "PreferredAuthentications=none", "-o", "NumberOfPasswordPrompts=0", "-o", `ConnectTimeout=${Math.max(1, Math.ceil(Number(timeoutMs || 2500) / 1000))}`, "-p", String(normalizedPort)];
    if (jumpHost) {
      args.push("-J", jumpUser ? `${jumpUser}@${jumpHost}` : jumpHost);
    }
    args.push(`${String(username || "student").trim() || "student"}@${normalizedHost}`, "true");
    let output = "";
    let settled = false;
    const child = spawn(SSH_COMMAND, args, {
      cwd: process.cwd(),
      env: process.env,
      windowsHide: true,
      stdio: ["ignore", "ignore", "pipe"]
    });
    const timer = setTimeout(() => {
      finish({
        ready: false,
        reason: "timeout",
        output
      });
      try {
        child.kill();
      } catch {}
    }, Math.max(1000, Number(timeoutMs || 2500)));
    function finish(result) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(result);
    }
    child.stderr.on("data", chunk => {
      output += String(chunk || "");
      if (output.length > 4000) output = output.slice(-4000);
    });
    child.on("error", () => finish({
      ready: false,
      reason: "ssh-spawn-error",
      output
    }));
    child.on("exit", code => {
      const text = output.trim();
      const authenticationReached = /Permission denied|Authentication failed|Too many authentication failures|No supported authentication methods/i.test(text);
      const hostKeyMismatch = isSshHostKeyMismatch(text);
      const connectionFailed = /Connection refused|Connection timed out|Operation timed out|No route to host|Network is unreachable|Could not resolve hostname|Name or service not known|Connection reset|kex_exchange_identification|Connection closed/i.test(text);
      finish({
        ready: Number(code) === 0 || !hostKeyMismatch && authenticationReached || !hostKeyMismatch && !connectionFailed && /authenticated|authentication/i.test(text),
        reason: Number(code) === 0 ? "ok" : hostKeyMismatch ? "host-key-mismatch" : authenticationReached ? "auth-reached" : connectionFailed ? "connect-failed" : "ssh-unready",
        output: text
      });
    });
  });
}
async function checkVmSshBootReady({
  lab,
  host,
  port,
  username = "",
  jumpHost = "",
  jumpUser = "",
  nodeId = ""
}) {
  const startedAtMs = resolveLabBootReferenceMs(lab, nodeId);
  const requestStartedAtMs = Date.now();
  const bootAgeMs = startedAtMs ? Math.max(0, requestStartedAtMs - startedAtMs) : 0;
  const minimumWaitMs = startedAtMs ? Math.max(0, VM_BOOT_MIN_WAIT_MS - bootAgeMs) : 0;
  if (minimumWaitMs > 0) {
    return {
      ready: false,
      phase: "waiting",
      attempts: 0,
      waitedMs: 0,
      retryAfterMs: Math.max(1000, Math.min(VM_BOOT_READY_INTERVAL_MS, minimumWaitMs)),
      remainingWaitMs: minimumWaitMs
    };
  }
  const probeResult = await probeSshServiceReady({
    host,
    port,
    username,
    jumpHost,
    jumpUser,
    labId: lab?.id,
    nodeId
  });
  if (probeResult.ready) {
    clearLabBootReadinessPending(lab?.id, nodeId);
  }
  return {
    ready: probeResult.ready,
    phase: probeResult.ready ? "ready" : "probing",
    attempts: 1,
    waitedMs: Date.now() - requestStartedAtMs,
    retryAfterMs: VM_BOOT_READY_INTERVAL_MS,
    reason: probeResult.reason
  };
}
async function waitForVmSshBootReady({
  lab,
  host,
  port,
  username = "",
  jumpHost = "",
  jumpUser = "",
  nodeId = ""
}) {
  const requestStartedAtMs = Date.now();
  const deadlineMs = requestStartedAtMs + VM_BOOT_READY_TIMEOUT_MS;
  let attempts = 0;
  while (Date.now() <= deadlineMs) {
    attempts += 1;
    const readiness = await checkVmSshBootReady({
      lab,
      host,
      port,
      username,
      jumpHost,
      jumpUser,
      nodeId
    });
    if (readiness.ready) {
      return {
        ready: true,
        attempts,
        waitedMs: Date.now() - requestStartedAtMs
      };
    }
    const remainingMs = deadlineMs - Date.now();
    if (remainingMs <= 0) break;
    await sleep(Math.min(readiness.retryAfterMs || VM_BOOT_READY_INTERVAL_MS, remainingMs));
  }
  return {
    ready: false,
    attempts,
    waitedMs: Date.now() - requestStartedAtMs,
    retryAfterMs: VM_BOOT_READY_INTERVAL_MS
  };
}
async function createZunAttachTerminalSession({
  userId,
  lab,
  course,
  platformStatus,
  replayMetadata = {},
  message = "컨테이너 콘솔 연결을 준비했습니다."
}) {
  const containerUuid = String(lab?.containerUuid || "").trim();
  if (!containerUuid) {
    throw new Error("컨테이너 콘솔이 아직 준비되지 않았습니다.");
  }
  const projectName = getZunProjectName(platformStatus);
  const latestContainer = await ensureZunContainerRunning({
    apiUrl: platformStatus.zunApiUrl,
    containerUuid,
    projectName
  });
  await runtimeUpdateLabRequest(lab.id, {
    status: normalizeZunStatus(latestContainer?.status, lab.status || "running"),
    instanceIp: String(latestContainer?.addresses?.[0]?.address || lab.instanceIp || "").trim(),
    instanceIps: Array.isArray(latestContainer?.addresses) ? latestContainer.addresses : lab.instanceIps
  }).catch(() => null);
  const attachEntry = await attachZunRemoteContainer({
    apiUrl: platformStatus.zunApiUrl,
    containerUuid,
    projectName
  });
  if (!attachEntry.websocketUrl) {
    throw new Error("Zun 콘솔 websocket URL을 받지 못했습니다.");
  }
  const sessionId = randomUUID();
  const terminalSession = {
    id: sessionId,
    mode: "zun-attach",
    userId,
    labId: lab.id,
    courseId: course.id,
    nodeId: "container-1",
    nodeName: String(lab.containerName || lab.stackName || course.title || "컨테이너").trim(),
    containerUuid,
    apiUrl: platformStatus.zunApiUrl,
    projectName,
    wsUrl: attachEntry.websocketUrl,
    examSessionId: String(lab.examSessionId || "").trim(),
    replayMetadata: sanitizeTerminalReplayMetadata(replayMetadata),
    createdAt: Date.now()
  };
  terminalSessions.set(sessionId, terminalSession);
  return {
    message,
    wsPath: `/ws/terminal/${sessionId}`,
    targetLabel: `${terminalSession.nodeName} / console`,
    labId: terminalSession.labId,
    courseId: terminalSession.courseId,
    host: lab.instanceIp || "",
    hostType: "container-console",
    nodeId: terminalSession.nodeId,
    nodeName: terminalSession.nodeName,
    port: 0
  };
}
async function prepareZunInteractiveConnection({
  apiUrl,
  containerUuid,
  projectName,
  shellCommand = "/bin/bash -i"
}) {
  const candidateShells = Array.from(new Set([String(shellCommand || "").trim(), "/bin/bash -i", "/bin/bash", "/bin/sh -i", "/bin/sh"].filter(Boolean)));
  let execError = null;
  for (const candidateShell of candidateShells) {
    try {
      const execEntry = await executeZunRemoteContainer({
        apiUrl,
        containerUuid,
        projectName,
        command: candidateShell,
        interactive: true,
        run: false
      });
      const execId = String(execEntry?.execId || "").trim();
      const wsUrl = String(execEntry?.websocketUrl || "").trim();
      if (execId && /^wss?:\/\//i.test(wsUrl)) {
        return {
          mode: "zun-exec",
          execId,
          wsUrl,
          shellCommand: candidateShell
        };
      }
      execError = new Error(execId ? "Zun execute 응답에서 WebSocket 프록시 URL을 받지 못했습니다." : "Zun exec 세션 ID를 받지 못했습니다.");
    } catch (error) {
      execError = error;
    }
  }
  try {
    const attachEntry = await attachZunRemoteContainer({
      apiUrl,
      containerUuid,
      projectName
    });
    const wsUrl = String(attachEntry?.websocketUrl || "").trim();
    if (/^wss?:\/\//i.test(wsUrl)) {
      return {
        mode: "zun-attach",
        execId: "",
        wsUrl,
        shellCommand: ""
      };
    }
  } catch (attachError) {
    if (!execError) execError = attachError;
  }
  throw execError || new Error("Zun 컨테이너 WebSocket 콘솔을 준비하지 못했습니다.");
}
