const SSH_COMMAND = process.env.SSH_COMMAND || "ssh";
const SCP_COMMAND = process.env.SCP_COMMAND || "scp";
const SSH_KEYGEN_COMMAND = process.env.SSH_KEYGEN_COMMAND || "ssh-keygen";
const SSH_STRICT_HOST_KEY_CHECKING = process.env.SSH_STRICT_HOST_KEY_CHECKING || "accept-new";
