const SSH_KNOWN_HOSTS_SCOPE = normalizeSshKnownHostsScope(process.env.SSH_KNOWN_HOSTS_SCOPE || "resource");
const SSH_PUBLIC_HOST = process.env.SSH_PUBLIC_HOST || "ssh.example.com";
const SSH_EXTERNAL_PORT_START = Number(process.env.SSH_EXTERNAL_PORT_START || 41000);
const SSH_EXTERNAL_PORT_END = Number(process.env.SSH_EXTERNAL_PORT_END || 42999);
const RDP_EXTERNAL_PORT_START = Number(process.env.RDP_EXTERNAL_PORT_START || 43000);
const RDP_EXTERNAL_PORT_END = Number(process.env.RDP_EXTERNAL_PORT_END || 43099);
const TCP_EXTERNAL_PORT_START = Number(process.env.TCP_EXTERNAL_PORT_START || 45000);
const TCP_EXTERNAL_PORT_END = Number(process.env.TCP_EXTERNAL_PORT_END || 45999);
const LOGIN_RATE_LIMIT_WINDOW_MS = Number(process.env.LOGIN_RATE_LIMIT_WINDOW_MS || 15 * 60 * 1000);
const LOGIN_RATE_LIMIT_MAX = Number(process.env.LOGIN_RATE_LIMIT_MAX || 10);
const USERNAME_RATE_LIMIT_WINDOW_MS = Number(process.env.USERNAME_RATE_LIMIT_WINDOW_MS || 5 * 60 * 1000);
const USERNAME_RATE_LIMIT_MAX = Number(process.env.USERNAME_RATE_LIMIT_MAX || 30);
const SIGNUP_RATE_LIMIT_WINDOW_MS = Number(process.env.SIGNUP_RATE_LIMIT_WINDOW_MS || 60 * 60 * 1000);
const SIGNUP_RATE_LIMIT_MAX = Number(process.env.SIGNUP_RATE_LIMIT_MAX || 20);
