function heatTemplateUsesYamlMergeKeys(content) {
  return /(^|\r?\n)\s*<<\s*:/.test(String(content || ""));
}
async function pathExists(targetPath) {
  try {
    await fs.access(targetPath);
    return true;
  } catch {
    return false;
  }
}
async function directoryHasEntries(targetPath) {
  try {
    const entries = await fs.readdir(targetPath);
    return entries.length > 0;
  } catch {
    return false;
  }
}
async function bootstrapLegacyDirectory(sourcePath, targetPath) {
  if (path.resolve(sourcePath) === path.resolve(targetPath)) return false;
  if (!(await pathExists(sourcePath))) return false;
  if (await directoryHasEntries(targetPath)) return false;
  await fs.mkdir(path.dirname(targetPath), {
    recursive: true
  });
  await fs.cp(sourcePath, targetPath, {
    recursive: true,
    force: false,
    errorOnExist: false
  });
  return true;
}
