async function deliverInstanceUsageWarning(req, item, {
  action = "instance_monitor.warn",
  automated = false
} = {}) {
  const targetUser = Number(item.userId || 0) ? await runtimeFindUserById(item.userId) : await runtimeFindUserByUsername(item.username || "");
  if (!targetUser?.id) {
    const error = new Error("경고를 받을 사용자를 찾지 못했습니다.");
    error.statusCode = 404;
    throw error;
  }
  const warning = buildInstanceUsageWarningContent(item, targetUser);
  const messageEntry = await runtimeCreateUserMessage({
    senderId: req.user.id,
    recipientId: targetUser.id,
    subject: warning.subject,
    body: warning.text
  });
  await createUserNotification({
    userId: targetUser.id,
    type: automated ? "instance_usage_auto_warning" : "instance_usage_warning",
    title: warning.subject,
    body: automated ? "자동 경고 기준에 따라 인스턴스 사용량 확인을 요청했습니다." : "관리자가 인스턴스 사용량 확인을 요청했습니다.",
    linkSection: "messages",
    metadata: {
      messageId: messageEntry?.id || null,
      instanceType: item.type,
      instanceId: item.id,
      automated: Boolean(automated)
    }
  });
  let mailResult = {
    sent: false,
    skipped: true,
    reason: "no-email"
  };
  let mailErrorMessage = "";
  if (String(targetUser.email || "").trim()) {
    try {
      mailResult = await sendMailNotification({
        type: automated ? "instance_usage_auto_warning" : "instance_usage_warning",
        to: targetUser.email,
        subject: warning.subject,
        text: warning.text,
        metadata: {
          sentBy: req.user?.username || "admin",
          recipientUsername: targetUser.username,
          instanceType: item.type,
          instanceId: item.id,
          instanceKey: item.key || "",
          riskLevel: item.risk?.level || "",
          riskScore: item.risk?.score || 0,
          automated: Boolean(automated),
          at: new Date().toISOString()
        }
      });
    } catch (error) {
      mailErrorMessage = error?.message || "메일 발송에 실패했습니다.";
    }
  }
  await recordAdminAudit(req, {
    action,
    targetType: item.type,
    targetId: item.id,
    summary: `${automated ? "자동 " : ""}인스턴스 사용량 경고 발송: ${targetUser.username || targetUser.id}`,
    metadata: {
      userId: targetUser.id,
      username: targetUser.username || "",
      email: targetUser.email || "",
      messageId: messageEntry?.id || null,
      mailSent: Boolean(mailResult?.sent),
      mailSkipped: Boolean(mailResult?.skipped),
      mailReason: mailResult?.reason || "",
      mailErrorMessage,
      automated: Boolean(automated),
      autoWarning: item.autoWarning || null,
      risk: item.risk || null,
      metrics: item.metrics || null
    }
  });
  const mailMessage = mailErrorMessage ? ` 메일 발송은 실패했습니다: ${mailErrorMessage}` : mailResult?.sent ? " 이메일도 발송했습니다." : String(targetUser.email || "").trim() ? " 메일 설정 또는 제공자 상태로 이메일은 건너뛰었습니다." : " 사용자 이메일이 없어 쪽지만 보냈습니다.";
  return {
    message: `${targetUser.name || targetUser.username}님에게 사용량 경고 쪽지를 보냈습니다.${mailMessage}`,
    item,
    targetUser,
    messageEntry,
    mail: mailResult,
    mailErrorMessage
  };
}
app.post("/api/admin/instance-monitor/warn", requireAdmin, async (req, res) => {
  const type = String(req.body?.type || "").trim();
  const id = Number(req.body?.id || 0) || 0;
  if (!type || !id) {
    res.status(400).json({
      message: "경고를 보낼 인스턴스를 선택해 주세요."
    });
    return;
  }
  try {
    const snapshot = await getAdminInstanceMonitorSnapshot({
      force: false
    });
    const item = (snapshot.items || []).find(candidate => String(candidate.type || "") === type && Number(candidate.id || 0) === id);
    if (!item) {
      res.status(404).json({
        message: "모니터링 대상 인스턴스를 찾지 못했습니다."
      });
      return;
    }
    res.json(await deliverInstanceUsageWarning(req, item));
  } catch (error) {
    console.error("[instance-monitor] warning failed", {
      type,
      id,
      message: error?.message
    });
    res.status(error.statusCode || 500).json({
      message: error.message || "사용량 경고 발송에 실패했습니다."
    });
  }
});
app.post("/api/admin/instance-monitor/auto-warn", requireAdmin, async (req, res) => {
  try {
    const snapshot = await getAdminInstanceMonitorSnapshot({
      force: false
    });
    const candidates = (snapshot.items || []).filter(item => item.autoWarning?.eligible).slice(0, INSTANCE_MONITOR_AUTO_WARNING_MAX_BATCH);
    if (!candidates.length) {
      res.json({
        message: "자동 경고 발송 대상이 없습니다.",
        sent: 0,
        failed: 0,
        results: []
      });
      return;
    }
    const results = [];
    for (const item of candidates) {
      try {
        const result = await deliverInstanceUsageWarning(req, item, {
          action: "instance_monitor.auto_warn",
          automated: true
        });
        results.push({
          ok: true,
          id: item.id,
          type: item.type,
          username: item.username || "",
          message: result.message
        });
      } catch (error) {
        results.push({
          ok: false,
          id: item.id,
          type: item.type,
          username: item.username || "",
          message: error?.message || "발송 실패"
        });
      }
    }
    const sent = results.filter(item => item.ok).length;
    const failed = results.length - sent;
    res.json({
      message: `자동 경고 ${sent}건을 발송했습니다.${failed ? ` 실패 ${failed}건을 확인해 주세요.` : ""}`,
      sent,
      failed,
      results
    });
  } catch (error) {
    console.error("[instance-monitor] auto warning failed", {
      message: error?.message
    });
    res.status(500).json({
      message: error.message || "자동 경고 발송에 실패했습니다."
    });
  }
});
