function normalizeMarketingSurveyOptionsInput(value) {
  return Array.from(new Set((Array.isArray(value) ? value : String(value || "").split(/\r?\n/)).map(item => String(item || "").trim()).filter(Boolean))).slice(0, 20);
}
function normalizeMarketingSurveyDateInput(value, label) {
  const raw = String(value || "").trim();
  if (!raw) return {
    error: `${label}을 입력해 주세요.`
  };
  const date = new Date(raw);
  if (!Number.isFinite(date.getTime())) return {
    error: `${label} 형식이 올바르지 않습니다.`
  };
  return {
    value: date.toISOString()
  };
}
function validateMarketingSurveyInput(body, {
  partial = false
} = {}) {
  const title = String(body?.title || "").trim();
  const question = String(body?.question || "").trim();
  let startAt = String(body?.startAt || "").trim();
  let endAt = String(body?.endAt || "").trim();
  const options = Object.prototype.hasOwnProperty.call(body || {}, "options") ? normalizeMarketingSurveyOptionsInput(body.options) : null;
  const startProvided = Object.prototype.hasOwnProperty.call(body || {}, "startAt");
  const endProvided = Object.prototype.hasOwnProperty.call(body || {}, "endAt");
  if (!partial || Object.prototype.hasOwnProperty.call(body || {}, "title")) {
    if (!title) return {
      error: "설문 제목을 입력해 주세요."
    };
  }
  if (!partial || Object.prototype.hasOwnProperty.call(body || {}, "question")) {
    if (!question) return {
      error: "투표 질문을 입력해 주세요."
    };
  }
  if (!partial || options) {
    if (!options || options.length < 2) return {
      error: "선택지는 2개 이상 입력해 주세요."
    };
  }
  if (!partial || startProvided) {
    const normalized = normalizeMarketingSurveyDateInput(startAt, "시작일");
    if (normalized.error) return {
      error: normalized.error
    };
    startAt = normalized.value;
  }
  if (!partial || endProvided) {
    const normalized = normalizeMarketingSurveyDateInput(endAt, "종료일");
    if (normalized.error) return {
      error: normalized.error
    };
    endAt = normalized.value;
  }
  if (startAt && endAt && new Date(startAt).getTime() >= new Date(endAt).getTime()) {
    return {
      error: "종료일은 시작일보다 뒤여야 합니다."
    };
  }
  return {
    value: {
      title,
      description: String(body?.description || "").trim(),
      question,
      status: String(body?.status || "draft").trim() || "draft",
      multiChoice: body?.multiChoice === true,
      showResults: body?.showResults !== false,
      startAt,
      endAt,
      options
    }
  };
}
