    sshExternalPortMin: SSH_EXTERNAL_PORT_START,
    sshExternalPortMax: SSH_EXTERNAL_PORT_END,
    rdpExternalPortStart: rdpExternalPortStart <= rdpExternalPortEnd ? rdpExternalPortStart : RDP_EXTERNAL_PORT_START,
    rdpExternalPortEnd: rdpExternalPortStart <= rdpExternalPortEnd ? rdpExternalPortEnd : RDP_EXTERNAL_PORT_END,
    rdpExternalPortMin: RDP_EXTERNAL_PORT_START,
    rdpExternalPortMax: RDP_EXTERNAL_PORT_END,
    tcpExternalPortStart: tcpExternalPortStart <= tcpExternalPortEnd ? tcpExternalPortStart : TCP_EXTERNAL_PORT_START,
    tcpExternalPortEnd: tcpExternalPortStart <= tcpExternalPortEnd ? tcpExternalPortEnd : TCP_EXTERNAL_PORT_END,
    tcpExternalPortMin: TCP_EXTERNAL_PORT_START,
    tcpExternalPortMax: TCP_EXTERNAL_PORT_END,
    publicDomainRoutesEnabled: status.publicDomainRoutesEnabled !== false,
    externalSshRoutesEnabled: status.externalSshRoutesEnabled !== false,
    externalRdpRoutesEnabled: status.externalRdpRoutesEnabled !== false,
    publicTcpRoutesEnabled: Boolean(status.publicTcpRoutesEnabled),
    allowedPublicRoutePorts: formatAllowedPublicRoutePorts(status, ALLOWED_PUBLIC_ROUTE_PORTS),
    containerRegistrySearchUrl: isAdminViewer ? containerRegistrySettings.searchUrl : "",
    containerRegistryPublicHost: containerRegistrySettings.publicHost,
    containerRegistryDefaultNamespace: containerRegistrySettings.defaultNamespace,
    containerRegistrySearchTimeoutMs: containerRegistrySettings.searchTimeoutMs,
    containerRegistrySearchLimit: containerRegistrySettings.searchLimit,
    containerRegistryImageDownloadCommand: isAdminViewer ? containerRegistrySettings.imageDownloadCommand : "",
    containerRegistryImageDownloadConfigured: Boolean(containerRegistrySettings.imageDownloadCommand),
    containerRegistryImageMirrorCommand: isAdminViewer ? containerRegistrySettings.imageMirrorCommand : "",
    containerRegistryImageMirrorConfigured: Boolean(containerRegistrySettings.imageMirrorCommand),
