function normalizePublicQuoteText(value, maxLength = 500) {
  return String(value || "").replace(/\s+/g, " ").trim().slice(0, maxLength);
}
function normalizePublicQuoteMultiline(value, maxLength = 2000) {
  return String(value || "").replace(/\r\n?/g, "\n").trim().slice(0, maxLength);
}
function normalizePublicQuoteParticipantCount(value) {
  return Math.max(1, Math.min(999, Math.round(Number(value || 1) || 1)));
}
function isValidPublicContactEmail(value) {
  const email = String(value || "").trim();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && email.length <= 254;
}
function isAdminAccount(user = {}) {
  return ["admin", "administrator", "관리자"].includes(String(user.role || "").trim().toLowerCase());
}
async function notifyAdminsAboutPublicQuoteInquiry(inquiry) {
  try {
    const admins = (await runtimeListUsers()).filter(user => String(user.status || "").trim() === "approved" && isAdminAccount(user));
    await Promise.all(admins.map(admin => createUserNotification({
      userId: admin.id,
      type: "public_quote_inquiry",
      title: "비회원 견적 문의가 접수되었습니다.",
      body: `${inquiry.companyName || "회사명 미입력"} / ${inquiry.contactName || "담당자 미입력"} / ${inquiry.interestType || "교육 견적"}`,
      linkSection: "admin",
      metadata: {
        publicQuoteInquiryId: inquiry.id,
        contactEmail: inquiry.contactEmail || ""
      }
    })));
  } catch (error) {
    console.warn("[public-quote] admin notification failed", {
      inquiryId: inquiry?.id,
      message: error.message
    });
  }
}
app.post("/api/public/quote-inquiries", publicQuoteInquiryRateLimiter, async (req, res) => {
  if (normalizePublicQuoteText(req.body?.website, 200)) {
    res.status(202).json({
      message: "견적 문의를 접수했습니다."
    });
    return;
  }
  const companyName = normalizePublicQuoteText(req.body?.companyName, 160);
  const contactName = normalizePublicQuoteText(req.body?.contactName, 80);
  const contactEmail = normalizePublicQuoteText(req.body?.contactEmail, 254).toLowerCase();
  const contactPhone = normalizePublicQuoteText(req.body?.contactPhone, 60);
  const interestType = normalizePublicQuoteText(req.body?.interestType, 80);
  const courseTitles = normalizePublicQuoteText(req.body?.courseTitles, 300);
  const participantCount = normalizePublicQuoteParticipantCount(req.body?.participantCount);
  const desiredTimeline = normalizePublicQuoteText(req.body?.desiredTimeline, 120);
  const requirements = normalizePublicQuoteMultiline(req.body?.requirements, 2000);
  const privacyAgreed = req.body?.privacyAgreed === true;
  if (!contactName || !isValidPublicContactEmail(contactEmail) || !requirements || !privacyAgreed) {
    res.status(400).json({
      message: "담당자명, 이메일, 요청 내용, 개인정보 수집 동의를 확인해 주세요."
    });
    return;
  }
  const inquiry = await runtimeCreatePublicQuoteInquiry({
    companyName,
    contactName,
    contactEmail,
    contactPhone,
    interestType,
    courseTitles,
    participantCount,
    desiredTimeline,
    requirements,
    privacyAgreed,
    ipAddress: String(req.ip || "").trim().slice(0, 120),
    userAgent: String(req.headers["user-agent"] || "").trim().slice(0, 500)
  });
  await notifyAdminsAboutPublicQuoteInquiry(inquiry);
  res.status(201).json({
    message: "견적 문의를 접수했습니다. 담당자가 내용을 확인한 뒤 안내드리겠습니다.",
    inquiryId: inquiry.id
  });
});
app.post("/api/terms/agree", requireAuth, async (req, res) => {
  try {
    const settings = await runtimeGetPlatformStatus();
    if (settings?.termsEnabled === false) {
      res.json({
        message: "약관 기능이 비활성화되어 동의 절차를 건너뜁니다.",
        user: await runtimeFindUserById(req.user.id)
      });
      return;
    }
    const activeTerms = await runtimeListActiveTermsVersions();
    const requiredTerms = REQUIRED_TERMS_KEYS.map(key => activeTerms.find(term => term.termsKey === key)).filter(Boolean);
    if (requiredTerms.length < REQUIRED_TERMS_KEYS.length) {
      res.status(503).json({
        message: "활성 약관이 아직 준비되지 않았습니다. 관리자에게 문의해 주세요."
      });
      return;
    }
    const agreedTermIds = new Set((Array.isArray(req.body?.termsAgreementIds) ? req.body.termsAgreementIds : []).map(item => Number(item)));
    if (!requiredTerms.every(term => agreedTermIds.has(Number(term.id)))) {
      res.status(400).json({
        message: "활성화된 표준약관과 서비스 추가 약관에 모두 동의해 주세요."
      });
      return;
    }
    const currentAgreementHashes = new Set((req.user?.termsAgreements || []).map(item => `${item.termsKey || item.terms_key}:${item.contentHash || item.content_hash}`));
    const missingTerms = requiredTerms.filter(term => !currentAgreementHashes.has(`${term.termsKey}:${term.contentHash}`));
    if (missingTerms.length) {
      await runtimeCreateUserTermsAgreements({
        userId: req.user.id,
        termsVersions: missingTerms,
        ipAddress: req.ip || "",
        userAgent: req.get("user-agent") || ""
      });
    }
    res.json({
      message: "약관 동의가 완료되었습니다.",
      user: await runtimeFindUserById(req.user.id)
    });
  } catch (error) {
    res.status(500).json({
      message: error.message
    });
  }
});
