app.post("/api/messages", requireAuth, async (req, res) => {
  try {
    const platformStatus = await runtimeGetPlatformStatus();
    const supportGroupName = getSupportMessageGroupName(platformStatus);
    const rawRecipientId = String(req.body?.recipientId || "").trim();
    const subject = String(req.body?.subject || "").trim();
    const body = String(req.body?.body || "").trim();
    if (!rawRecipientId) {
      res.status(400).json({
        message: "받는 사람을 선택해 주세요."
      });
      return;
    }
    if (!subject) {
      res.status(400).json({
        message: "쪽지 제목을 입력해 주세요."
      });
      return;
    }
    if (!body) {
      res.status(400).json({
        message: "쪽지 내용을 입력해 주세요."
      });
      return;
    }
    const recipient = await findAllowedMessageRecipientForUser(req.user, rawRecipientId, platformStatus);
    if (!recipient) {
      res.status(403).json({
        message: "선택한 사용자에게 쪽지를 보낼 수 없습니다."
      });
      return;
    }
    const sendingToSupportGroup = String(recipient.recipientType || "user") === "group" && String(recipient.groupKey || "") === "support";
    const senderCanBypassSupportAway = isAdminUserRole(req.user?.role) || Boolean(req.user?.supportMessageEnabled);
    if (sendingToSupportGroup && !senderCanBypassSupportAway && normalizeSupportAvailabilityMode(platformStatus?.supportAvailabilityMode) === "away") {
      res.status(503).json({
        message: String(platformStatus?.supportUnavailableMessage || `현재 ${supportGroupName} 담당자가 부재중입니다.`).trim() || `현재 ${supportGroupName} 담당자가 부재중입니다.`
      });
      return;
    }
    let messageEntry = null;
    if (sendingToSupportGroup) {
      const allUsers = await runtimeListUsers();
      const supportMembers = resolveSupportRecipients(allUsers);
      const targetMembers = supportMembers.filter(item => Number(item.id) !== Number(req.user.id || 0));
      if (!targetMembers.length) {
        res.status(400).json({
          message: `현재 ${supportGroupName} 그룹에 메시지를 받을 사용자가 없습니다.`
        });
        return;
      }
      const deliveryGroupId = randomUUID();
      const createdEntries = [];
      for (const member of targetMembers) {
        const createdEntry = await runtimeCreateUserMessage({
          senderId: req.user.id,
          recipientId: member.id,
          subject,
          body,
          recipientType: "group",
          recipientGroupKey: "support",
          recipientGroupName: recipient.groupName || supportGroupName,
          deliveryGroupId
        });
        createdEntries.push(createdEntry);
        await createUserNotification({
          userId: member.id,
          type: "message",
          title: `새 그룹 쪽지: ${subject}`,
          body: `${req.user.name || req.user.username}님이 ${supportGroupName} 그룹에 쪽지를 보냈습니다.`,
          linkSection: "messages",
          metadata: {
            messageId: createdEntry?.id || null,
            senderId: req.user.id,
            recipientType: "group",
            recipientGroupKey: "support"
          }
        });
      }
      messageEntry = createdEntries[0] || null;
    } else {
      const recipientId = Number(recipient.id || 0);
      messageEntry = await runtimeCreateUserMessage({
        senderId: req.user.id,
        recipientId,
        subject,
        body
      });
      await createUserNotification({
        userId: recipientId,
        type: "message",
        title: `새 쪽지: ${subject}`,
        body: `${req.user.name || req.user.username}님이 쪽지를 보냈습니다.`,
        linkSection: "messages",
        metadata: {
          messageId: messageEntry?.id || null,
          senderId: req.user.id
        }
      });
    }
    const messages = await runtimeListUserMessages(req.user.id);
    res.status(201).json({
      message: "쪽지를 보냈습니다.",
      entry: messageEntry,
      messages
    });
  } catch (error) {
    res.status(500).json({
      message: error.message
    });
  }
});
