const CLEANUP_STATUS_NOTIFICATION_LABELS = {
  requested: "접수됨",
  working: "처리 중",
  done: "완료",
  blocked: "확인 필요"
};
function getCleanupStatusNotificationLabel(status) {
  return CLEANUP_STATUS_NOTIFICATION_LABELS[String(status || "").trim().toLowerCase()] || "업데이트됨";
}
function buildCleanupStatusNotificationBody(message, status, note) {
  const label = getCleanupStatusNotificationLabel(status);
  const subject = String(message?.subject || "터미널 클라우드 정리 요청").trim();
  const safeNote = String(note || "").trim();
  return [`운영지원에서 "${subject}" 처리 상태를 업데이트했습니다.`, `현재 상태: ${label}`, safeNote ? `처리 메모: ${safeNote}` : ""].filter(Boolean).join("\n\n");
}
app.post("/api/admin/messages/:id/cleanup-status", requireAdmin, async (req, res) => {
  try {
    const cleanupStatus = String(req.body?.cleanupStatus || "").trim().toLowerCase();
    const allowedStatuses = new Set(["", "requested", "working", "done", "blocked"]);
    if (!allowedStatuses.has(cleanupStatus)) {
      return res.status(400).json({
        message: "정리 요청 상태 값이 올바르지 않습니다."
      });
    }
    const cleanupStatusNote = String(req.body?.cleanupStatusNote || "").trim().slice(0, 500);
    const previousMessages = await runtimeListAllUserMessages();
    const previousMessage = previousMessages.find(item => Number(item.id) === Number(req.params.id)) || null;
    const previousStatus = String(previousMessage?.cleanupStatus || "").trim().toLowerCase();
    const messages = await runtimeUpdateUserMessageCleanupStatus(req.params.id, {
      cleanupStatus,
      cleanupStatusNote,
      cleanupStatusUpdatedBy: req.user?.id
    });
    const targetMessage = messages.find(item => Number(item.id) === Number(req.params.id)) || previousMessage;
    const requesterId = Number(targetMessage?.senderId || 0);
    if (cleanupStatus && cleanupStatus !== previousStatus && requesterId && requesterId !== Number(req.user?.id || 0)) {
      const label = getCleanupStatusNotificationLabel(cleanupStatus);
      await createUserNotification({
        userId: requesterId,
        type: "terminal_cloud_cleanup",
        title: `정리 요청 ${label}`,
        body: buildCleanupStatusNotificationBody(targetMessage, cleanupStatus, cleanupStatusNote),
        linkSection: "messages",
        metadata: {
          messageId: targetMessage?.id || String(req.params.id),
          cleanupStatus,
          cleanupStatusNote,
          updatedBy: req.user?.id || null
        }
      });
    }
    res.json({
      message: cleanupStatus ? "정리 요청 상태를 저장했습니다." : "정리 요청 상태를 초기화했습니다.",
      messages
    });
  } catch (error) {
    res.status(500).json({
      message: error.message
    });
  }
});
