function summarizeCourseSurveys(responses = [], accessCounts = []) {
  const summaryByCourse = new Map();
  const accessCountMap = new Map((accessCounts || []).map(item => [Number(item.courseId), Number(item.accessCount || 0)]));
  const byUserCourse = new Map();
  for (const response of responses) {
    const key = `${response.userId}:${response.courseId}`;
    const current = byUserCourse.get(key) || {
      userId: response.userId,
      courseId: response.courseId,
      courseTitle: response.courseTitle,
      pre: null,
      post: null
    };
    current[response.phase] = response;
    byUserCourse.set(key, current);
  }
  for (const pair of byUserCourse.values()) {
    const courseSummary = summaryByCourse.get(pair.courseId) || {
      courseId: pair.courseId,
      courseTitle: pair.courseTitle,
      preCount: 0,
      postCount: 0,
      promoterCount: 0,
      passiveCount: 0,
      detractorCount: 0,
      nps: null,
      avgGrowth: null,
      avgContentSatisfaction: null,
      avgInstructorSatisfaction: null,
      avgOperationSatisfaction: null,
      growthValues: [],
      contentValues: [],
      instructorValues: [],
      operationValues: []
    };
    if (pair.pre) courseSummary.preCount += 1;
    if (pair.post) {
      courseSummary.postCount += 1;
      const group = pair.post.metrics?.npsGroup || "";
      if (group === "promoter") courseSummary.promoterCount += 1;
      if (group === "passive") courseSummary.passiveCount += 1;
      if (group === "detractor") courseSummary.detractorCount += 1;
      ["content", "instructor", "operation"].forEach(kind => {
        const key = `${kind}Satisfaction`;
        const value = numberOrNull(pair.post.metrics?.[key]);
        if (value != null) courseSummary[`${kind}Values`].push(value);
      });
    }
    const preConfidence = numberOrNull(pair.pre?.metrics?.preConfidence);
    const postConfidence = numberOrNull(pair.post?.metrics?.postConfidence);
    if (preConfidence != null && postConfidence != null) courseSummary.growthValues.push(postConfidence - preConfidence);
    summaryByCourse.set(pair.courseId, courseSummary);
  }
  return Array.from(summaryByCourse.values()).map(item => {
    const average = values => values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
    const npsBase = item.postCount || 0;
    return {
      ...item,
      accessCount: accessCountMap.get(Number(item.courseId)) || 0,
      preCompletionRate: (accessCountMap.get(Number(item.courseId)) || 0) > 0 ? item.preCount / (accessCountMap.get(Number(item.courseId)) || 1) * 100 : null,
      nps: npsBase ? (item.promoterCount - item.detractorCount) / npsBase * 100 : null,
      avgGrowth: average(item.growthValues),
      avgContentSatisfaction: average(item.contentValues),
      avgInstructorSatisfaction: average(item.instructorValues),
      avgOperationSatisfaction: average(item.operationValues),
      growthValues: undefined,
      contentValues: undefined,
      instructorValues: undefined,
      operationValues: undefined
    };
  }).sort((left, right) => String(left.courseTitle || "").localeCompare(String(right.courseTitle || ""), "ko"));
}
