  if (!targetUserId || !feedback) return null;
  const phaseLabel = phase === "post" ? "사후 설문" : "사전 설문";
  const subject = `[AI 해설] ${course?.title || "과정"} ${phaseLabel}`;
  const body = [`${targetUser.name || targetUser.userName || targetUser.username || "사용자"}님,`, "", `${course?.title || "선택한 과정"} ${phaseLabel} 응답을 바탕으로 AI 해설을 생성했습니다.`, "", feedback].join("\n");
  const deliveredMessage = await runtimeCreateUserMessage({
    senderId: senderId ? Number(senderId) : null,
    recipientId: targetUserId,
    subject,
    body
  });
  await createUserNotification({
    userId: targetUserId,
    type: "survey_feedback",
    title: subject,
    body: notificationBody,
    linkSection: "messages",
    metadata: {
      ...metadata,
      messageId: deliveredMessage?.id || null,
      courseId: course?.id || course?.courseId || null,
      phase,
      generatedBy: senderId ? Number(senderId) : null
    }
  });
