async function generateAndStoreCourseSurveyFeedback({
  targetUser,
  course,
  phase,
  responses,
  response,
  settings,
  deliver = false,
  generatedBy = null,
  notificationBody = "설문 AI 해설이 생성되었습니다.",
  metadata = {}
}) {
  const pairedPhase = phase === "pre" ? "post" : "pre";
  const pairedResponse = responses.find(item => Number(item.courseId) === Number(course.id) && item.phase === pairedPhase) || null;
  const summary = summarizeCourseSurveys(responses).find(item => Number(item.courseId) === Number(course.id)) || null;
  const result = await generateCourseSurveyFeedbackText({
    settings,
    course,
    phase,
    response,
    pairedResponse,
    summary
  });
  let deliveredMessage = null;
  if (deliver) {
    deliveredMessage = await deliverCourseSurveyFeedbackMessage({
      senderId: generatedBy,
      targetUser,
      course,
      phase,
      feedback: result.feedback,
      notificationBody,
      metadata
    });
  }
  const feedbackRecord = await runtimeUpdateCourseSurveyFeedback({
    userId: targetUser.id,
    courseId: course.id,
    phase,
    text: result.feedback,
    provider: result.provider,
    model: result.model,
    delivered: Boolean(deliveredMessage),
    messageId: deliveredMessage?.id || null,
    generatedBy
  });
  return {
    ...result,
    delivered: Boolean(deliveredMessage),
    messageId: deliveredMessage?.id || null,
    surveyResponse: feedbackRecord
  };
}
function limitCourseVideoAccess(course, mode = "public") {
  const canSeeAll = mode === "full";
  const canSeeFirst = canSeeAll || mode === "member";
  const courseVideos = (Array.isArray(course?.courseVideos) ? course.courseVideos : []).map((video, index) => ({
    ...video,
    title: String(video?.title || `영상 ${index + 1}`).trim(),
    description: String(video?.description || "").trim(),
    url: canSeeAll || canSeeFirst && index === 0 ? String(video?.url || "").trim() : ""
  }));
  const firstVideoUrl = String(courseVideos[0]?.url || "").trim();
  const fallbackYoutubeUrl = String(course?.youtubeUrl || "").trim();
  return {
    ...course,
    youtubeUrl: canSeeAll ? fallbackYoutubeUrl : canSeeFirst ? firstVideoUrl || (courseVideos.length ? "" : fallbackYoutubeUrl) : "",
    courseVideos
  };
}
async function listVisibleCoursesForUserResponse(userId) {
  const courses = await runtimeListVisibleCoursesByUser(userId);
  return courses.map(course => limitCourseVideoAccess(course, course.hasAccess ? "full" : "member"));
}
