  if (Object.prototype.hasOwnProperty.call(body, "provider")) patch.provider = String(body.provider || "manual").trim() || "manual";
  if (Object.prototype.hasOwnProperty.call(body, "repositoryUrl")) patch.repositoryUrl = String(body.repositoryUrl || "").trim();
  if (Object.prototype.hasOwnProperty.call(body, "branch")) patch.branch = String(body.branch || "main").trim() || "main";
  if (Object.prototype.hasOwnProperty.call(body, "pipelineEngine")) patch.pipelineEngine = normalizeCicdPipelineEngine(body.pipelineEngine);
  if (Object.prototype.hasOwnProperty.call(body, "jenkinsJobName")) patch.jenkinsJobName = normalizeJenkinsJobName(body.jenkinsJobName);
  if (Object.prototype.hasOwnProperty.call(body, "jenkinsfilePath")) patch.jenkinsfilePath = normalizeJenkinsfilePath(body.jenkinsfilePath);
  if (Object.prototype.hasOwnProperty.call(body, "buildServerUrl")) patch.buildServerUrl = "";
