  if (Object.prototype.hasOwnProperty.call(body, "labRequestId")) patch.labRequestId = body.labRequestId == null || body.labRequestId === "" ? null : Number(body.labRequestId);
  if (Object.prototype.hasOwnProperty.call(body, "variables")) patch.variables = body.variables && typeof body.variables === "object" && !Array.isArray(body.variables) ? body.variables : {};
