app.post("/api/cicd/credentials", requireAuth, async (req, res) => {
  let input;
  try {
    input = normalizeCicdCredentialInput(req.body || {}, req.user.id);
    const existing = await runtimeListCicdCredentialsByUser(req.user.id);
    if (existing.length >= 20) {
      res.status(409).json({
        message: "사용자당 Credential은 최대 20개까지 등록할 수 있습니다."
      });
      return;
    }
    if (existing.some(item => item.slug === input.slug)) {
      res.status(409).json({
        message: "같은 이름의 Credential이 이미 있습니다."
      });
      return;
    }
    const platformStatus = await runtimeGetPlatformStatus();
    if (platformStatus.cicdExecutionMode !== "jenkins" || !isJenkinsConfigured(platformStatus)) {
      res.status(409).json({
        message: "Jenkins 실행 엔진이 준비되지 않았습니다."
      });
      return;
    }
    await createJenkinsCredential(platformStatus, {
      id: input.jenkinsCredentialId,
      type: input.credentialType,
      username: input.username,
      secret: input.secret,
      passphrase: input.passphrase,
      description: `[Terminal Lab user:${req.user.id}] ${input.description || input.name}`
    });
    let credential;
    try {
      credential = await runtimeCreateCicdCredential({
        ...input,
        userId: req.user.id
      });
    } catch (error) {
      await deleteJenkinsCredential(platformStatus, input.jenkinsCredentialId).catch(() => null);
      throw error;
    }
    await recordAdminAudit(req, {
      action: "cicd_credential_create",
      targetType: "cicd_credential",
      targetId: String(credential.id),
      summary: `${credential.name} Credential 등록`,
      metadata: {
        credentialType: credential.credentialType,
        jenkinsCredentialId: credential.jenkinsCredentialId
      }
    });
    res.status(201).json({
      credential: presentCicdCredential(credential)
    });
  } catch (error) {
    res.status(error.status || 400).json({
      message: error.message || "Credential 등록에 실패했습니다."
    });
  }
});
