async function listExamAccessibleCourses(user, {
  allowAdminConsole = false
} = {}) {
  if (!user) return [];
  const canBypassAccess = allowAdminConsole ? userCanAccessAdminConsole(user) : user.role === "admin";
  const courses = canBypassAccess ? await runtimeListCourses() : await runtimeListVisibleCoursesByUser(user.id);
  if (canBypassAccess) return courses;
  const accessChecks = await Promise.all(courses.map(async course => course.hasAccess === true || (await canAccessCourse(user, course))));
  return courses.filter((_course, index) => accessChecks[index]);
}
async function findExamAccessibleCourse(user, courseId, options = {}) {
  const courses = await listExamAccessibleCourses(user, options);
  return courses.find(course => Number(course.id) === Number(courseId)) || null;
}
function normalizeExamAccessPolicy(raw = {}) {
  const source = raw && typeof raw === "object" ? raw : {};
  const mode = ["course_access", "entitlement", "required_courses"].includes(String(source.mode || "").trim()) ? String(source.mode).trim() : "course_access";
  const requiredCourseIds = Array.from(new Set((Array.isArray(source.requiredCourseIds) ? source.requiredCourseIds : []).map(value => Number(value)).filter(value => Number.isInteger(value) && value > 0)));
  return {
    mode,
    requiredCourseIds,
    requiredCourseMatch: source.requiredCourseMatch === "any" ? "any" : "all",
    allowFree: source.allowFree !== false,
    allowPromotion: source.allowPromotion !== false,
    entitlementDays: Math.max(0, Math.min(3650, Number(source.entitlementDays || 0) || 0)),
    refundBlocksNewAttempts: source.refundBlocksNewAttempts !== false,
    guidance: String(source.guidance || "").trim().slice(0, 500)
  };
}
async function resolvePurchasedExamEntitlementExpiry(courseId) {
  const [writtenExam, labExam] = await Promise.all([loadWrittenExam(courseId), loadLabExam(courseId)]);
  const days = Math.max(0, ...[writtenExam, labExam].filter(Boolean).map(exam => normalizeExamAccessPolicy(exam.accessPolicy).entitlementDays));
  return days > 0 ? new Date(Date.now() + days * 86400000).toISOString() : null;
}
function isExamEntitlementActive(entitlement, nowMs = Date.now()) {
  if (String(entitlement?.status || "").toLowerCase() !== "active") return false;
  const expiresAt = String(entitlement?.expiresAt || "").trim();
  if (!expiresAt) return true;
  const expiresMs = Date.parse(expiresAt);
  return Number.isFinite(expiresMs) && expiresMs > nowMs;
}
function isEntitlementSourceAllowed(entitlement, policy) {
  const source = String(entitlement?.source || "").toLowerCase();
  if (source === "free" && !policy.allowFree) return false;
  if (["promotion", "coupon"].includes(source) && !policy.allowPromotion) return false;
  return true;
}
function classifyPaidPaymentEntitlementSource(payment) {
  if (Number(payment?.amount || 0) <= 0) {
    return payment?.metadata?.couponId || payment?.metadata?.paidByCoupon ? "promotion" : "free";
  }
  return Number(payment?.metadata?.promotionDiscountAmount || 0) > 0 ? "promotion" : "payment";
}
async function buildExamEligibilityContext(userId) {
  const [entitlements, payments, courses] = await Promise.all([runtimeListExamEntitlementsByUser(userId), runtimeListPaymentsByUser(userId), runtimeListCourses()]);
  return {
    entitlements,
    payments,
    courses
  };
}
async function evaluateExamEligibility(user, exam, {
  allowAdminConsole = false,
  activeSession = null,
  eligibilityContext = null
} = {}) {
  const policy = normalizeExamAccessPolicy(exam?.accessPolicy);
  if (!user || !exam) return {
    eligible: false,
    reason: "exam_not_found",
    message: "시험 정보를 찾을 수 없습니다.",
    policy
  };
  if (allowAdminConsole && userCanAccessAdminConsole(user) || user.role === "admin") {
    return {
      eligible: true,
      reason: "admin",
      message: "관리자 권한으로 응시할 수 있습니다.",
      policy
    };
  }
  if (activeSession) {
    return {
      eligible: true,
      reason: "active_session",
      message: "이미 시작한 시험 세션을 계속할 수 있습니다.",
      policy
    };
  }
  const examCourseId = Number(exam.courseId || 0);
  const examCourse = eligibilityContext?.courses?.find(course => Number(course.id) === examCourseId) || (await runtimeFindCourseById(examCourseId));
  if (!examCourse || !examCourse.isPublished) {
    return {
      eligible: false,
      reason: "course_unavailable",
      message: "현재 응시할 수 없는 시험입니다.",
      policy
    };
  }
  if (policy.mode === "course_access") {
    const eligible = await canAccessCourse(user, examCourse);
    return {
      eligible,
      reason: eligible ? "course_access" : "course_access_required",
      message: eligible ? "과정 접근 권한이 확인되었습니다." : "이 시험이 연결된 과정의 이용 권한이 필요합니다.",
      policy
    };
  }
  const {
    entitlements,
    payments,
    courses
  } = eligibilityContext || (await buildExamEligibilityContext(user.id));
  const activeEntitlements = entitlements.filter(item => isExamEntitlementActive(item) && isEntitlementSourceAllowed(item, policy));
  const paidPayments = payments.filter(payment => String(payment.status || "").toLowerCase() === "paid");
  const hasAcquisition = courseId => {
    const entitlement = activeEntitlements.find(item => Number(item.examCourseId) === Number(courseId));
    if (entitlement) return true;
    return paidPayments.some(payment => {
      if (Number(payment.courseId) !== Number(courseId)) return false;
      return isEntitlementSourceAllowed({
        source: classifyPaidPaymentEntitlementSource(payment)
      }, policy);
    });
  };
  if (policy.mode === "entitlement") {
    const eligible = hasAcquisition(examCourseId);
    const claimable = isCourseFreePromotionAccessActive(examCourse) || Math.max(0, Number(examCourse.price || 0)) <= 0;
    return {
      eligible,
      reason: eligible ? "exam_entitlement" : "exam_entitlement_required",
      message: eligible ? "시험 응시권이 확인되었습니다." : policy.guidance || "시험 응시권을 먼저 구입하거나 발급받아 주세요.",
      policy,
      action: eligible ? "" : "claim_or_purchase_exam",
      claimable,
      purchaseCourseId: examCourseId
    };
  }
  const requiredCourseIds = policy.requiredCourseIds;
  if (!requiredCourseIds.length) {
    return {
      eligible: false,
      reason: "required_courses_not_configured",
      message: "필수 과정이 설정되지 않았습니다. 관리자에게 문의해 주세요.",
      policy
    };
  }
  const matchedIds = requiredCourseIds.filter(hasAcquisition);
  const eligible = policy.requiredCourseMatch === "any" ? matchedIds.length > 0 : matchedIds.length === requiredCourseIds.length;
  const titleById = new Map(courses.map(course => [Number(course.id), course.title]));
  const missingCourseIds = requiredCourseIds.filter(id => !matchedIds.includes(id));
  const courseById = new Map(courses.map(course => [Number(course.id), course]));
  const missingCourses = missingCourseIds.map(id => {
    const requiredCourse = courseById.get(id);
    return {
      id,
      title: requiredCourse?.title || `과정 #${id}`,
      claimable: Boolean(requiredCourse && (isCourseFreePromotionAccessActive(requiredCourse) || Math.max(0, Number(requiredCourse.price || 0)) <= 0))
    };
  });
  return {
    eligible,
    reason: eligible ? "required_courses" : "required_courses_missing",
    message: eligible ? "필수 과정 구매 조건을 충족했습니다." : policy.guidance || `${missingCourses.map(course => course.title).join(", ")} 구매가 필요합니다.`,
    policy,
    requiredCourses: requiredCourseIds.map(id => ({
      id,
      title: titleById.get(id) || `과정 #${id}`
    })),
    missingCourses,
    action: eligible ? "" : "purchase_required_courses"
  };
}
function stripWrittenExamAnswers(exam) {
  return {
    ...exam,
    questions: (Array.isArray(exam?.questions) ? exam.questions : []).map(({
      answerText: _answerText,
      ...question
    }) => question)
  };
}
function stripLabExamAdminFields(exam, {
  includeScenario = true
} = {}) {
  const {
    scriptContent: _scriptContent,
    preflightScript: _preflightScript,
    gradingGuide: _gradingGuide,
    operationPolicy: _operationPolicy,
    ...safeExam
  } = exam || {};
  return {
    ...safeExam,
    scenarioContent: includeScenario ? safeExam.scenarioContent : "",
    questions: includeScenario ? safeExam.questions : [],
    description: includeScenario ? safeExam.description : "응시 조건을 충족하면 시험 안내를 확인할 수 있습니다."
  };
}
function isBlockingCourseLabStatus(status) {
  return ["pending", "approved", "provisioning", "running", "paused", "terminating"].includes(String(status || "").trim().toLowerCase());
}
function normalizeCourseAccessRequestType(value) {
  const normalized = String(value || "").trim().toLowerCase();
  return ["revoke", "interest", "extend"].includes(normalized) ? normalized : "access";
}
async function hasBlockingCourseLab(userId, courseId) {
  const labs = await runtimeListLabRequestsByUser(userId);
  return labs.some(lab => Number(lab.courseId) === Number(courseId) && isBlockingCourseLabStatus(lab.status));
}
const labExamPreparationTaskIds = new Set();
const pendingLabExamPreparationTasks = new Map();
function queueLabExamSessionPreparation(args, {
  retryIfBusy = false
} = {}) {
  const sessionId = String(args?.sessionId || "").trim();
  if (!sessionId) return false;
  if (labExamPreparationTaskIds.has(sessionId)) {
    if (retryIfBusy) pendingLabExamPreparationTasks.set(sessionId, args);
    return false;
  }
  labExamPreparationTaskIds.add(sessionId);
  setImmediate(() => {
    prepareLabExamSessionInBackground(args).catch(error => {
      console.error("[lab-exam] unable to queue background preparation", {
        sessionId,
        message: error?.message
      });
    }).finally(() => {
      labExamPreparationTaskIds.delete(sessionId);
      const pendingArgs = pendingLabExamPreparationTasks.get(sessionId);
      if (pendingArgs) {
        pendingLabExamPreparationTasks.delete(sessionId);
        queueLabExamSessionPreparation(pendingArgs, {
          retryIfBusy: true
        });
      }
    });
  });
  return true;
}
async function finalizePreparedLabExamSession({
  session,
  exam,
  examCourse,
  lab
}) {
  markLabBootReadinessPending(lab.id);
  const preflight = await runLabExamPreflightAgainstLab({
    exam,
    lab,
    course: examCourse
  });
  const currentSession = await runtimeFindLabExamSessionById(session.id);
  if (!currentSession || String(currentSession.status || "").toLowerCase() !== "preparing" || Number(currentSession.labRequestId || 0) !== Number(lab.id || 0)) return currentSession;
  if (!preflight.passed) {
    const updated = await runtimeUpdateLabExamSession(currentSession.id, {
      status: "preparing",
      errorMessage: `시험 환경 사전 점검이 아직 완료되지 않았습니다: ${(preflight.messages || []).join(" / ") || "환경 요구사항을 확인해 주세요."}`,
      metadata: {
        ...(currentSession.metadata || {}),
        preflight,
        lastPreflightAt: new Date().toISOString()
      }
    });
    broadcastPortalEvent("lab-exams-updated", {
      reason: "exam-preflight-pending",
      sessionId: currentSession.id,
      labRequestId: lab.id
    });
    return updated;
  }
  const updated = await runtimeUpdateLabExamSession(currentSession.id, {
    status: "ready",
    errorMessage: "",
    metadata: {
      ...(currentSession.metadata || {}),
      preflight,
      readyAt: new Date().toISOString()
    }
  });
  broadcastPortalEvent("lab-exams-updated", {
    reason: "exam-session-ready",
    sessionId: currentSession.id,
    labRequestId: lab.id
  });
  return updated;
}
async function prepareLabExamSessionInBackground({
  sessionId,
  exam,
  examCourse,
  user,
  isAdminPreview
}) {
  let lab = null;
  try {
    let session = await runtimeFindLabExamSessionById(sessionId);
    if (!session || String(session.status || "").toLowerCase() !== "preparing") return;
    const leaseUntil = new Date(Date.now() + LAB_EXAM_PREPARATION_LEASE_MS).toISOString();
    const claimed = await runtimeClaimLabExamSessionPreparation(session.id, leaseUntil);
    if (!claimed) return;
    if (session.labRequestId) {
      lab = await runtimeFindLabRequestById(session.labRequestId);
    } else {
      const created = await createCourseLabRequestForUser(examCourse, user, {
        purpose: "exam",
        examSessionId: session.id,
        approvalMode: "instant",
        initialStatus: "approved",
        expiresAt: session.expiresAt
      });
      lab = created.lab;
      const linkedSession = await runtimeUpdateLabExamSession(session.id, {
        labRequestId: lab.id
      });
      if (!linkedSession || String(linkedSession.status || "").toLowerCase() !== "preparing") {
        if (lab) await terminateLab(lab).catch(() => null);
        return;
      }
      broadcastPortalEvent("lab-exams-updated", {
        reason: "exam-lab-created",
        sessionId: session.id,
        labRequestId: lab.id
      });
    }
    if (!lab || Number(lab.userId) !== Number(user.id) || String(lab.examSessionId || "") !== session.id) {
      throw new Error("시험 전용 랩 연결 정보를 확인하지 못했습니다.");
    }
    session = await runtimeFindLabExamSessionById(sessionId);
    if (!session || String(session.status || "").toLowerCase() !== "preparing" || Number(session.labRequestId || 0) !== Number(lab.id || 0)) return;
    const labStatus = String(lab.status || "").toLowerCase();
    const provisioned = ["running", "provisioning"].includes(labStatus) ? lab : await provisionLab(lab.id, examCourse, user);
    if (String(provisioned?.status || "").toLowerCase() === "failed") {
      await runtimeUpdateLabExamSession(session.id, {
        status: "failed",
        errorMessage: provisioned?.errorMessage || "시험 전용 랩 생성 중 오류가 발생했습니다.",
        endedAt: new Date().toISOString(),
        endReason: "lab_failed"
      });
      broadcastPortalEvent("lab-exams-updated", {
        reason: "exam-lab-failed",
        sessionId: session.id,
        labRequestId: lab.id
      });
      return;
    }
    if (String(provisioned?.status || "").toLowerCase() !== "running") {
      broadcastPortalEvent("lab-exams-updated", {
        reason: "exam-lab-provisioning",
        sessionId: session.id,
        labRequestId: lab.id
      });
      return;
    }
    session = await runtimeFindLabExamSessionById(sessionId);
    if (!session || String(session.status || "").toLowerCase() !== "preparing") return;
    await finalizePreparedLabExamSession({
      session,
      exam,
      examCourse,
      lab: provisioned
    });
  } catch (error) {
    const failed = await runtimeUpdateLabExamSession(sessionId, {
      status: "failed",
      errorMessage: error.message || "시험 시작 중 오류가 발생했습니다.",
      endedAt: new Date().toISOString(),
      endReason: "start_failed"
    }).catch(() => null);
    if (lab) terminateLab(lab).catch(() => null);
    console.error("[lab-exam] background preparation failed", {
      sessionId,
      labRequestId: lab?.id || null,
      message: error?.message
    });
    broadcastPortalEvent("lab-exams-updated", {
      reason: "exam-session-start-failed",
      sessionId,
      labRequestId: lab?.id || null,
      errorMessage: failed?.errorMessage || error?.message
    });
  }
}
async function recoverPreparingLabExamSessions(trigger = "scheduled") {
  const sessions = await runtimeListLabExamSessions();
  const now = Date.now();
  let queued = 0;
  for (const session of sessions) {
    if (String(session?.status || "").toLowerCase() !== "preparing") continue;
    const expiresAt = Date.parse(session?.expiresAt || "");
    if (Number.isFinite(expiresAt) && expiresAt <= now) continue;
    const [course, user] = await Promise.all([runtimeFindCourseById(session.courseId), runtimeFindUserById(session.userId)]);
    if (!course || !user) {
      console.warn("[lab-exam] skipped preparation recovery due to missing course or user", {
        trigger,
        sessionId: session.id,
        courseId: session.courseId,
        userId: session.userId
      });
      continue;
    }
    const exam = await loadLabExam(course.id);
    if (!exam) {
      console.warn("[lab-exam] skipped preparation recovery due to missing exam config", {
        trigger,
        sessionId: session.id,
        courseId: session.courseId
      });
      continue;
    }
    if (queueLabExamSessionPreparation({
      sessionId: session.id,
      exam,
      examCourse: course,
      user,
      isAdminPreview: Boolean(session.metadata?.adminPreview)
    })) queued += 1;
  }
  if (queued > 0) {
    console.info("[lab-exam] queued preparing session recovery", {
      trigger,
      queued
    });
  }
}
app.patch("/api/auth/profile", requireAuth, async (req, res) => {
  const name = String(req.body?.name || "").trim();
  const email = String(req.body?.email || "").trim();
  const currentPassword = String(req.body?.currentPassword || "");
  const newPassword = String(req.body?.newPassword || "");
  if (!name) {
    res.status(400).json({
      message: "이름을 입력해 주세요."
    });
    return;
  }
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    res.status(400).json({
      message: "유효한 이메일 주소를 입력해 주세요."
    });
    return;
  }
  let user = await runtimeUpdateUserProfile(req.user.id, {
    name,
    email
  });
  if (newPassword) {
    if (newPassword.length < 8) {
      res.status(400).json({
        message: "새 비밀번호는 8자 이상이어야 합니다."
      });
      return;
    }
    const currentUser = await runtimeFindUserByUsername(req.user.username);
    const isValid = await bcrypt.compare(currentPassword, currentUser.passwordHash);
    if (!isValid) {
      res.status(400).json({
        message: "현재 비밀번호가 올바르지 않습니다."
      });
      return;
    }
    const passwordHash = await bcrypt.hash(newPassword, 10);
    await runtimeUpdateUserPassword(req.user.id, passwordHash);
    user = await runtimeFindUserById(req.user.id);
  }
  res.json({
    message: "내 정보를 수정했습니다.",
    user
  });
});
