async function grantPackageContents({
  userId,
  packageCourse,
  sourcePaymentId = null,
  source = "admin",
  grantedBy = null
} = {}) {
  if (String(packageCourse?.courseType || "") !== "package") return [];
  const items = await runtimeGrantCoursePackageItems({
    userId,
    packageCourseId: packageCourse.id,
    sourcePaymentId
  });
  for (const item of items.filter(entry => entry.courseType === "exam")) {
    const expiresAt = await resolvePurchasedExamEntitlementExpiry(item.id);
    await runtimeGrantExamEntitlement({
      userId,
      examCourseId: item.id,
      source,
      sourcePaymentId,
      requiredCourseId: packageCourse.id,
      expiresAt,
      grantedBy,
      metadata: {
        grantedVia: "course_package",
        packageCourseId: packageCourse.id
      }
    });
  }
  return items;
}
async function grantCourseAccessImmediately(user, course, grantedVia = "self_enrollment") {
  const packageMarker = String(course.courseType || "") === "package" ? `package:${course.id}:grant` : grantedVia;
  await runtimeGrantUserCourseAccess(user.id, course.id, packageMarker);
  const examEntitlementExpiresAt = await resolvePurchasedExamEntitlementExpiry(course.id);
  const entitlementSource = grantedVia === "free_self_enrollment" ? "free" : grantedVia === "payment" ? "payment" : grantedVia === "redeem_code" ? "promotion" : "admin";
  await runtimeGrantExamEntitlement({
    userId: user.id,
    examCourseId: course.id,
    source: entitlementSource,
    expiresAt: examEntitlementExpiresAt,
    metadata: {
      grantedVia
    }
  });
  await grantPackageContents({
    userId: user.id,
    packageCourse: course,
    source: entitlementSource
  });
  if (user.email) {
    const courseAssignedMail = buildCourseAssignedMail({
      name: user.name,
      courseTitle: course.title
    });
    sendMailNotification({
      type: "course_assigned",
      to: user.email,
      subject: courseAssignedMail.subject,
      text: courseAssignedMail.text,
      templateKey: courseAssignedMail.templateKey,
      templateVariables: courseAssignedMail.templateVariables,
      metadata: {
        userId: user.id,
        courseId: course.id,
        grantedVia
      }
    }).catch(error => {
      console.warn("[mail] self enrollment mail failed", {
        userId: user.id,
        courseId: course.id,
        message: error.message
      });
    });
  }
  await createUserNotification({
    userId: user.id,
    type: "course_access_granted",
    title: "수강신청이 완료되었습니다",
    body: `${course.title} 과정을 바로 이용할 수 있습니다.`,
    linkSection: course.courseType === "online" ? "onlineCourses" : course.courseType === "exam" ? "labExams" : "courses",
    metadata: {
      courseId: course.id,
      grantedVia
    }
  });
}
function calculateDiscountAmount(originalAmount, coupon) {
  const amount = Math.max(0, Number(originalAmount || 0));
  if (!coupon || amount <= 0) return 0;
  const discountType = String(coupon.discountType || "").trim().toLowerCase();
  const discountValue = Math.max(0, Number(coupon.discountValue || 0) || 0);
  if (discountType === "free") return amount;
  if (discountType === "fixed") return Math.min(amount, discountValue);
  return Math.min(amount, Math.floor(amount * (Math.min(100, discountValue) / 100)));
}
async function generateAdminCouponCode(prefix = "ADMIN") {
  for (let index = 0; index < 5; index += 1) {
    const code = `${prefix}-${randomBytes(3).toString("hex").toUpperCase()}-${randomBytes(2).toString("hex").toUpperCase()}`;
    const existing = await runtimeFindDiscountCouponByCode(code);
    if (!existing) return code;
  }
  throw new Error("쿠폰 코드를 생성하지 못했습니다. 잠시 후 다시 시도해 주세요.");
}
const SIGNUP_WELCOME_COUPON = {
  prefix: "WELCOME",
  discountType: "percent",
  discountValue: 15,
  expiresInDays: 7,
  maxUses: 1,
  campaignName: "회원가입 웰컴",
  reason: "회원가입 완료 혜택"
};
function hasCompletedPaidPurchase(payments = []) {
  return payments.some(payment => ["paid", "refunded"].includes(String(payment.status || "").toLowerCase()));
}
function formatCurrency(value) {
  const amount = Math.max(0, Number(value || 0) || 0);
  return `${amount.toLocaleString("ko-KR")}원`;
}
function normalizePromoDateTimeInput(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return "";
  return date.toISOString();
}
function renderCouponBenefitLabel(discountType, discountValue) {
  if (discountType === "free") return "전액 무료";
  if (discountType === "fixed") return `${discountValue.toLocaleString("ko-KR")}원 할인`;
  return `${discountValue}% 할인`;
}
const COURSE_QUOTE_VAT_RATE = 0.1;
const COURSE_QUOTE_VALID_DAYS = 14;
const COURSE_QUOTE_FALLBACK_PER_LEARNER_DAY_KRW = 450000;
function parseCourseDurationDays(duration) {
  const text = String(duration || "").trim().toLowerCase();
  if (!text) return 1;
  const dayMatch = text.match(/(\d+(?:\.\d+)?)\s*(?:일|days?|d)/i);
  if (dayMatch) return Math.max(1, Math.ceil(Number(dayMatch[1]) || 1));
  const hourMatch = text.match(/(\d+(?:\.\d+)?)\s*(?:시간|hours?|hrs?|h)/i);
  if (hourMatch) return Math.max(1, Math.ceil((Number(hourMatch[1]) || 8) / 8));
  const numberMatch = text.match(/(\d+(?:\.\d+)?)/);
  if (!numberMatch) return 1;
  const numeric = Number(numberMatch[1]) || 1;
  return numeric > 8 ? Math.max(1, Math.ceil(numeric / 8)) : Math.max(1, Math.ceil(numeric));
}
function resolveCourseQuotePackageDiscountRate(courseCount) {
  if (courseCount >= 4) return 0.2;
  if (courseCount >= 3) return 0.15;
  if (courseCount >= 2) return 0.1;
  return 0;
}
function estimateCourseQuoteUnitPrice(course) {
  const registeredPrice = Math.max(0, Number(course?.price || 0) || 0);
  if (registeredPrice > 0) {
    return {
      unitPrice: registeredPrice,
      estimated: false,
      pricingNote: "등록 과정 금액"
    };
  }
  const days = parseCourseDurationDays(course?.duration);
  const unitPrice = Math.max(0, Math.round(days * COURSE_QUOTE_FALLBACK_PER_LEARNER_DAY_KRW));
  return {
    unitPrice,
    estimated: true,
    pricingNote: `금액 미등록 과정: 한국 기술 ILT 기준 1인 1일 ${formatCurrency(COURSE_QUOTE_FALLBACK_PER_LEARNER_DAY_KRW)} 기준 ${days}일 산정`
  };
}
function normalizeCourseQuoteQuantity(value, fallback = 1) {
  return Math.max(1, Math.min(999, Math.round(Number(value || fallback) || fallback)));
}
function normalizeCourseQuoteMoney(value) {
  return Math.max(0, Math.round(Number(value || 0) || 0));
}
function normalizeCourseQuoteDiscountRate(value, fallback = 0) {
  if (value == null || String(value).trim() === "") return fallback;
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  const normalized = numeric > 1 ? numeric / 100 : numeric;
  return Math.max(0, Math.min(1, normalized));
}
async function generateCourseQuoteNo() {
  const dayKey = new Date().toISOString().slice(0, 10).replace(/-/g, "");
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const quoteNo = `TLQ-${dayKey}-${randomUUID().replace(/-/g, "").slice(0, 6).toUpperCase()}`;
    if (!(await runtimeFindCourseQuoteByQuoteNo(quoteNo))) return quoteNo;
  }
  throw createHttpError(500, "견적서 번호를 생성하지 못했습니다. 잠시 후 다시 시도해 주세요.");
}
async function buildCourseQuoteInput({
  body = {},
  user,
  platformStatus = null
}) {
  const rawItems = Array.isArray(body.items) ? body.items : [];
  const itemMap = new Map();
  for (const rawItem of rawItems) {
    const courseId = Number(rawItem?.courseId || 0);
    if (!Number.isInteger(courseId) || courseId <= 0) continue;
    const quantity = Math.max(1, Math.min(999, Math.round(Number(rawItem?.quantity || body.participantCount || 1) || 1)));
    itemMap.set(courseId, (itemMap.get(courseId) || 0) + quantity);
  }
  const selectedItems = Array.from(itemMap.entries()).map(([courseId, quantity]) => ({
    courseId,
    quantity
  }));
  if (!selectedItems.length) {
    throw createHttpError(400, "견적서에 포함할 과정을 1개 이상 선택해 주세요.");
  }
  if (selectedItems.length > 20) {
    throw createHttpError(400, "한 번에 견적 처리할 수 있는 과정은 최대 20개입니다.");
  }
  const courses = await Promise.all(selectedItems.map(item => runtimeFindCourseById(item.courseId)));
  if (courses.some(course => !course)) {
    throw createHttpError(404, "선택한 과정 중 찾을 수 없는 과정이 있습니다.");
  }
  const quoteItems = selectedItems.map((item, index) => {
    const course = courses[index];
    if (!course?.isPublished || String(course.courseStatus || "published").toLowerCase() === "archived") {
      throw createHttpError(400, "현재 공개된 과정만 견적서에 포함할 수 있습니다.");
    }
    const pricing = estimateCourseQuoteUnitPrice(course);
    return {
      courseId: course.id,
      courseTitle: course.title,
      courseSlug: course.slug,
      courseCategory: course.category,
      courseType: course.courseType,
      programType: course.programType,
      duration: course.duration,
      quantity: item.quantity,
      unitPrice: pricing.unitPrice,
      lineSubtotal: pricing.unitPrice * item.quantity,
      pricingNote: pricing.pricingNote,
      metadata: {
        estimated: pricing.estimated,
        registeredPrice: Math.max(0, Number(course.price || 0) || 0),
        durationDays: parseCourseDurationDays(course.duration),
        labEnabled: Boolean(course.labEnabled)
      },
      sortOrder: index
    };
  });
  const subtotalAmount = quoteItems.reduce((sum, item) => sum + item.lineSubtotal, 0);
  const discountRate = resolveCourseQuotePackageDiscountRate(quoteItems.length);
  const discountAmount = Math.round(subtotalAmount * discountRate);
  const taxableAmount = Math.max(0, subtotalAmount - discountAmount);
  const vatAmount = Math.round(taxableAmount * COURSE_QUOTE_VAT_RATE);
  const totalAmount = taxableAmount + vatAmount;
  const issuedAt = new Date().toISOString();
  const validUntil = new Date(Date.now() + COURSE_QUOTE_VALID_DAYS * 24 * 60 * 60 * 1000).toISOString();
  const effectivePlatformStatus = platformStatus || (await runtimeGetPlatformStatus());
  const recipientName = String(body.recipientName || user?.name || user?.username || "").trim();
  const recipientEmail = String(body.recipientEmail || user?.email || "").trim();
  if (!recipientName) throw createHttpError(400, "수신자 이름을 입력해 주세요.");
  if (!recipientEmail) throw createHttpError(400, "수신자 이메일을 입력해 주세요.");
  return {
    quoteNo: await generateCourseQuoteNo(),
    userId: user.id,
    status: "issued",
    recipientCompanyName: String(body.recipientCompanyName || "").trim(),
    recipientName,
    recipientEmail,
    recipientPhone: String(body.recipientPhone || "").trim(),
    subtotalAmount,
    discountRate,
    discountAmount,
    vatRate: COURSE_QUOTE_VAT_RATE,
    vatAmount,
    totalAmount,
    currency: "KRW",
    pricingBasis: {
      source: "registered_courses",
      packageDiscountRule: "2개 과정 10%, 3개 과정 15%, 4개 이상 20% 패키지 할인",
      audienceDiscountRule: "기업/학교/인원 구분별 추가 할인 없음",
      fallbackRule: `가격 미등록 과정은 한국 DevOps/클라우드 ILT 기준 1인 1일 ${COURSE_QUOTE_FALLBACK_PER_LEARNER_DAY_KRW.toLocaleString("ko-KR")}원으로 산정`,
      vatRule: "부가세 10% 별도 산정 후 합산",
      benchmark: {
        globalInstructorDayKrwRange: [2200000, 7300000],
        koreaPerLearnerDayKrwRange: [400000, 600000],
        koreaB2bInstructorDayKrwRange: [3500000, 6000000],
        referenceDate: "2026-05-10"
      }
    },
    businessSnapshot: {
      issuerName: effectivePlatformStatus.footerAdminName || "KIKI OS TERMINAL-LAB",
      issuerEmail: effectivePlatformStatus.footerEmail || "",
      businessInfo: effectivePlatformStatus.footerBusinessInfo || "",
      siteVersion: effectivePlatformStatus.siteVersionNumber || ""
    },
    note: String(body.note || "").trim(),
    issuedAt,
    validUntil,
    items: quoteItems
  };
}
async function buildAdminCourseQuoteInput({
  body = {},
  adminUser,
  platformStatus = null
}) {
  const targetUserId = Number(body.userId || adminUser?.id || 0);
  const targetUser = targetUserId > 0 ? await runtimeFindUserById(targetUserId) : null;
  if (!targetUser) {
    throw createHttpError(404, "견적서에 연결할 사용자를 찾을 수 없습니다.");
  }
  const rawItems = Array.isArray(body.items) ? body.items : [];
  if (!rawItems.length) {
    throw createHttpError(400, "견적서에 포함할 항목을 1개 이상 입력해 주세요.");
  }
  if (rawItems.length > 20) {
    throw createHttpError(400, "한 번에 견적 처리할 수 있는 항목은 최대 20개입니다.");
  }
  const quoteItems = [];
  for (let index = 0; index < rawItems.length; index += 1) {
    const rawItem = rawItems[index] || {};
    const quantity = normalizeCourseQuoteQuantity(rawItem.quantity || body.participantCount || 1);
    const courseId = Number(rawItem.courseId || 0);
    if (Number.isInteger(courseId) && courseId > 0) {
      const course = await runtimeFindCourseById(courseId);
      if (!course) {
        throw createHttpError(404, "선택한 등록 과정을 찾을 수 없습니다.");
      }
      const hasUnitPriceOverride = rawItem.unitPrice != null && String(rawItem.unitPrice).trim() !== "";
      const pricing = hasUnitPriceOverride ? {
        unitPrice: normalizeCourseQuoteMoney(rawItem.unitPrice),
        estimated: false,
        pricingNote: "관리자 지정 단가"
      } : estimateCourseQuoteUnitPrice(course);
      quoteItems.push({
        courseId: course.id,
        courseTitle: course.title,
        courseSlug: course.slug,
        courseCategory: course.category,
        courseType: course.courseType,
        programType: course.programType,
        duration: course.duration,
        quantity,
        unitPrice: pricing.unitPrice,
        lineSubtotal: pricing.unitPrice * quantity,
        pricingNote: String(rawItem.pricingNote || pricing.pricingNote || "").trim(),
        metadata: {
          estimated: pricing.estimated,
          registeredPrice: Math.max(0, Number(course.price || 0) || 0),
          durationDays: parseCourseDurationDays(course.duration),
          labEnabled: Boolean(course.labEnabled),
          source: "registered_course",
          adminCreated: true,
          unitPriceOverridden: hasUnitPriceOverride
        },
        sortOrder: quoteItems.length
      });
      continue;
    }
    const courseTitle = String(rawItem.courseTitle || rawItem.title || "").trim();
    if (!courseTitle) {
      throw createHttpError(400, "주문자 과정명을 입력해 주세요.");
    }
    const unitPrice = normalizeCourseQuoteMoney(rawItem.unitPrice);
    quoteItems.push({
      courseId: null,
      courseTitle,
      courseSlug: "",
      courseCategory: String(rawItem.courseCategory || rawItem.category || "").trim(),
      courseType: String(rawItem.courseType || "custom").trim() || "custom",
      programType: String(rawItem.programType || "").trim(),
      duration: String(rawItem.duration || "").trim(),
      quantity,
      unitPrice,
      lineSubtotal: unitPrice * quantity,
      pricingNote: String(rawItem.pricingNote || "관리자 직접 입력 과정").trim(),
      metadata: {
        source: "custom_course",
        adminCreated: true
      },
      sortOrder: quoteItems.length
    });
  }
  if (!quoteItems.length) {
    throw createHttpError(400, "견적서에 포함할 항목을 1개 이상 입력해 주세요.");
  }
  const subtotalAmount = quoteItems.reduce((sum, item) => sum + item.lineSubtotal, 0);
  const defaultDiscountRate = resolveCourseQuotePackageDiscountRate(quoteItems.length);
  const discountRate = normalizeCourseQuoteDiscountRate(body.discountRate ?? body.discountRatePercent, defaultDiscountRate);
  const discountAmount = Math.round(subtotalAmount * discountRate);
  const taxableAmount = Math.max(0, subtotalAmount - discountAmount);
  const vatAmount = Math.round(taxableAmount * COURSE_QUOTE_VAT_RATE);
  const totalAmount = taxableAmount + vatAmount;
  const issuedAt = new Date().toISOString();
  const validUntil = new Date(Date.now() + COURSE_QUOTE_VALID_DAYS * 24 * 60 * 60 * 1000).toISOString();
  const effectivePlatformStatus = platformStatus || (await runtimeGetPlatformStatus());
  const recipientName = String(body.recipientName || targetUser.name || targetUser.username || "").trim();
  const recipientEmail = String(body.recipientEmail || targetUser.email || "").trim();
  const reissueSourceQuoteId = Number(body.reissueSourceQuoteId || 0);
  const reissueSourceQuoteNo = String(body.reissueSourceQuoteNo || "").trim();
  if (!recipientName) throw createHttpError(400, "수신자 이름을 입력해 주세요.");
  if (!recipientEmail) throw createHttpError(400, "수신자 이메일을 입력해 주세요.");
  return {
    quoteNo: await generateCourseQuoteNo(),
    userId: targetUser.id,
    status: "issued",
    recipientCompanyName: String(body.recipientCompanyName || "").trim(),
    recipientName,
    recipientEmail,
    recipientPhone: String(body.recipientPhone || "").trim(),
    subtotalAmount,
    discountRate,
    discountAmount,
    vatRate: COURSE_QUOTE_VAT_RATE,
    vatAmount,
    totalAmount,
    currency: "KRW",
    pricingBasis: {
      source: "admin_created",
      packageDiscountRule: "관리자 견적은 자동 패키지 할인 또는 관리자 입력 할인율을 적용",
      audienceDiscountRule: "기업/학교/인원 구분별 추가 할인 없음",
      fallbackRule: `가격 미등록 등록 과정은 한국 DevOps/클라우드 ILT 기준 1인 1일 ${COURSE_QUOTE_FALLBACK_PER_LEARNER_DAY_KRW.toLocaleString("ko-KR")}원으로 산정`,
      vatRule: "부가세 10% 별도 산정 후 합산",
      customCourseRule: "주문자 과정은 관리자가 입력한 과정명, 기간, 수량, 단가 기준으로 산정",
      reissueSource: reissueSourceQuoteId > 0 || reissueSourceQuoteNo ? {
        quoteId: reissueSourceQuoteId > 0 ? reissueSourceQuoteId : null,
        quoteNo: reissueSourceQuoteNo
      } : undefined,
      benchmark: {
        globalInstructorDayKrwRange: [2200000, 7300000],
        koreaPerLearnerDayKrwRange: [400000, 600000],
        koreaB2bInstructorDayKrwRange: [3500000, 6000000],
        referenceDate: "2026-05-10"
      }
    },
    businessSnapshot: {
      issuerName: effectivePlatformStatus.footerAdminName || "KIKI OS TERMINAL-LAB",
      issuerEmail: effectivePlatformStatus.footerEmail || "",
      businessInfo: effectivePlatformStatus.footerBusinessInfo || "",
      siteVersion: effectivePlatformStatus.siteVersionNumber || ""
    },
    note: String(body.note || "").trim(),
    issuedAt,
    validUntil,
    reviewedBy: adminUser?.id || null,
    items: quoteItems
  };
}
function getCourseQuoteStatusLabel(status) {
  switch (String(status || "issued").toLowerCase()) {
    case "sent":
      return "최종 PDF 발송";
    case "accepted":
      return "확정";
    case "cancelled":
      return "취소";
    case "expired":
      return "만료";
    default:
      return "발행";
  }
}
function normalizeCourseQuoteAccessMode(value) {
  const normalized = String(value || "enabled").trim().toLowerCase();
  return ["enabled", "admin_only", "disabled"].includes(normalized) ? normalized : "enabled";
}
function normalizePortalUiMode(value, fallback = "legacy") {
  const normalized = String(value || "").trim().toLowerCase();
  if (["legacy", "switchable", "v2"].includes(normalized)) return normalized;
  return fallback;
}
function normalizeSupportAvailabilityMode(value, fallback = "available") {
  const normalized = String(value || "").trim().toLowerCase();
  if (["available", "away"].includes(normalized)) return normalized;
  return fallback;
}
function canAccessCourseQuotePortal(platformStatus, user) {
  const mode = normalizeCourseQuoteAccessMode(platformStatus?.courseQuoteAccessMode);
  if (mode === "enabled") return true;
  if (mode === "admin_only") return isAdminUserRole(user?.role);
  return false;
}
function assertCourseQuotePortalAccess(platformStatus, user) {
  if (canAccessCourseQuotePortal(platformStatus, user)) return;
  const mode = normalizeCourseQuoteAccessMode(platformStatus?.courseQuoteAccessMode);
  throw createHttpError(403, mode === "admin_only" ? "견적서 기능은 현재 관리자만 사용할 수 있습니다." : "견적서 발행 기능이 관리자 설정에서 비활성화되어 있습니다.");
}
async function issueSignupWelcomeCoupon(user) {
  if (!user?.id) return null;
  const existingCoupons = await runtimeListDiscountCouponsByUser(user.id);
  const duplicated = existingCoupons.find(coupon => String(coupon.source || "").trim() === "signup_welcome");
  if (duplicated) return duplicated;
  const coupon = await runtimeCreateDiscountCoupon({
    code: await generateAdminCouponCode(SIGNUP_WELCOME_COUPON.prefix),
    userId: user.id,
    courseId: null,
    source: "signup_welcome",
    discountType: SIGNUP_WELCOME_COUPON.discountType,
    discountValue: SIGNUP_WELCOME_COUPON.discountValue,
    maxUses: SIGNUP_WELCOME_COUPON.maxUses,
    status: "active",
    expiresAt: new Date(Date.now() + SIGNUP_WELCOME_COUPON.expiresInDays * 24 * 60 * 60 * 1000).toISOString(),
    metadata: {
      campaignName: SIGNUP_WELCOME_COUPON.campaignName,
      reason: SIGNUP_WELCOME_COUPON.reason,
      note: "첫 결제 전용 자동 발급 쿠폰",
      firstPurchaseOnly: true,
      autoIssued: true,
      audience: "new_signup"
    }
  });
  await createUserNotification({
    userId: user.id,
    type: "coupon_issued",
    title: "회원가입 웰컴 쿠폰이 지급되었습니다.",
    body: `${renderCouponBenefitLabel(SIGNUP_WELCOME_COUPON.discountType, SIGNUP_WELCOME_COUPON.discountValue)} 쿠폰이 발급되었습니다. 첫 결제에만 사용할 수 있으며 ${SIGNUP_WELCOME_COUPON.expiresInDays}일 안에 사용해 주세요.`,
    linkSection: "courses",
    metadata: {
      couponId: coupon.id,
      couponCode: coupon.code,
      campaignName: SIGNUP_WELCOME_COUPON.campaignName,
      reason: SIGNUP_WELCOME_COUPON.reason,
      source: "signup_welcome",
      firstPurchaseOnly: true
    }
  });
  if (user.email) {
    const signupWelcomeCouponMail = buildSignupWelcomeCouponMail({
      name: user.name,
      username: user.username,
      couponCode: coupon.code,
      benefitLabel: renderCouponBenefitLabel(SIGNUP_WELCOME_COUPON.discountType, SIGNUP_WELCOME_COUPON.discountValue),
      expiresAt: coupon.expiresAt || "-"
    });
    sendMailNotification({
      type: "coupon_issued",
      to: user.email,
      subject: signupWelcomeCouponMail.subject,
      text: signupWelcomeCouponMail.text,
      templateKey: signupWelcomeCouponMail.templateKey,
      templateVariables: signupWelcomeCouponMail.templateVariables,
      metadata: {
        userId: user.id,
        couponId: coupon.id,
        couponCode: coupon.code,
        campaignName: SIGNUP_WELCOME_COUPON.campaignName,
        source: "signup_welcome",
        firstPurchaseOnly: true
      }
    }).catch(error => {
      console.warn("[mail] signup welcome coupon mail failed", {
        userId: user.id,
        couponId: coupon.id,
        message: error.message
      });
    });
  }
  return coupon;
}
async function resolveApplicableCoupon({
  userId,
  courseId,
  couponCode = ""
}) {
  const normalizedCode = String(couponCode || "").trim().toUpperCase();
  if (!normalizedCode) return null;
  const coupon = await runtimeFindDiscountCouponByCode(normalizedCode);
  if (!coupon) throw new Error("쿠폰 코드를 찾을 수 없습니다.");
  if (Number(coupon.userId || 0) !== Number(userId || 0)) throw new Error("본인 계정의 쿠폰만 사용할 수 있습니다.");
  if (coupon.courseId != null && Number(coupon.courseId) !== Number(courseId)) throw new Error("이 과정에는 사용할 수 없는 쿠폰입니다.");
  if (String(coupon.status || "").toLowerCase() !== "active") throw new Error("이미 사용했거나 비활성화된 쿠폰입니다.");
  if (coupon.expiresAt) {
    const expiresAt = new Date(coupon.expiresAt);
    if (Number.isFinite(expiresAt.getTime()) && expiresAt.getTime() < Date.now()) throw new Error("쿠폰 사용 기간이 만료되었습니다.");
  }
  if (Number(coupon.usedCount || 0) >= Number(coupon.maxUses || 1)) throw new Error("이미 모두 사용한 쿠폰입니다.");
  if (coupon.metadata?.firstPurchaseOnly) {
    const payments = await runtimeListPaymentsByUser(userId);
    if (hasCompletedPaidPurchase(payments)) throw new Error("첫 결제 전용 쿠폰은 아직 결제 이력이 없는 계정에서만 사용할 수 있습니다.");
  }
  return coupon;
}
app.get("/api/coupons", requireAuth, async (req, res) => {
  res.json({
    coupons: await runtimeListDiscountCouponsByUser(req.user.id)
  });
});
app.post("/api/admin/coupons", requireAdmin, async (req, res) => {
  const userId = Number(req.body?.userId || 0);
  const courseId = req.body?.courseId == null || req.body?.courseId === "" ? null : Number(req.body.courseId);
  const discountType = String(req.body?.discountType || "percent").trim().toLowerCase();
  const discountValue = Math.max(0, Number(req.body?.discountValue || 0) || 0);
  const expiresInDays = Math.max(1, Number(req.body?.expiresInDays || 7) || 7);
  const maxUses = Math.max(1, Number(req.body?.maxUses || 1) || 1);
  const campaignName = String(req.body?.campaignName || "").trim();
  const reason = String(req.body?.reason || "").trim();
  const note = String(req.body?.note || "").trim();
  const user = await runtimeFindUserById(userId);
  if (!user) {
    res.status(404).json({
      message: "회원을 찾을 수 없습니다."
    });
    return;
  }
  if (courseId != null) {
    const course = await runtimeFindCourseById(courseId);
    if (!course) {
      res.status(404).json({
        message: "과정을 찾을 수 없습니다."
      });
      return;
    }
  }
  if (!["percent", "fixed", "free"].includes(discountType)) {
    res.status(400).json({
      message: "지원하지 않는 할인 방식입니다."
    });
    return;
  }
  if (discountType !== "free" && discountValue <= 0) {
    res.status(400).json({
      message: "할인 값을 입력해 주세요."
    });
    return;
  }
  const coupon = await runtimeCreateDiscountCoupon({
    code: await generateAdminCouponCode("ADMIN"),
    userId,
    courseId,
    source: String(req.body?.source || "admin_manual").trim() || "admin_manual",
    discountType,
    discountValue: discountType === "free" ? 100 : discountValue,
    maxUses,
    status: "active",
    expiresAt: new Date(Date.now() + expiresInDays * 24 * 60 * 60 * 1000).toISOString(),
    metadata: {
      issuedByAdminId: req.user.id,
      issuedByAdminUsername: req.user.username || "",
      campaignName,
      reason,
      note
    }
  });
  await createUserNotification({
    userId: user.id,
    type: "coupon_issued",
    title: "할인 쿠폰이 지급되었습니다.",
    body: `${courseId != null ? "지정 과정" : "과정"}에 사용할 ${renderCouponBenefitLabel(discountType, discountValue)} 쿠폰이 발급되었습니다.${reason ? ` 사유: ${reason}` : ""}`,
    linkSection: "courses",
    metadata: {
      couponId: coupon.id,
      couponCode: coupon.code,
      courseId,
      campaignName,
      reason,
      note,
      source: "admin_coupon_issue"
    }
  });
  if (user.email) {
    sendMailNotification({
      type: "coupon_issued",
      to: user.email,
      subject: "[KIKI OS TERMINAL-LAB] 할인 쿠폰이 발급되었습니다",
      text: [`${user.name || user.username}님, 사용할 수 있는 쿠폰이 발급되었습니다.`, "", `쿠폰 코드: ${coupon.code}`, `혜택: ${renderCouponBenefitLabel(discountType, discountValue)}`, `대상 과정: ${coupon.courseTitle || "전체 과정"}`, `만료일: ${coupon.expiresAt || "-"}`, reason ? `발급 사유: ${reason}` : "", note ? `메모: ${note}` : ""].filter(Boolean).join("\n"),
      metadata: {
        userId: user.id,
        couponId: coupon.id,
        couponCode: coupon.code,
        sentBy: req.user.username || "",
        campaignName,
        reason,
        note
      }
    }).catch(error => {
      console.warn("[mail] coupon issued mail failed", {
        userId: user.id,
        couponId: coupon.id,
        message: error.message
      });
    });
  }
  res.status(201).json({
    message: "관리자 쿠폰을 발급했습니다.",
    coupon
  });
});
app.patch("/api/admin/coupons/:id", requireAdmin, async (req, res) => {
  const couponId = Number(req.params.id);
  const current = (await runtimeFindDiscountCouponByCode(String(req.body?.code || "").trim())) || null;
  const nextStatus = String(req.body?.status || "").trim().toLowerCase();
  const allowedStatuses = new Set(["active", "inactive"]);
  if (!allowedStatuses.has(nextStatus)) {
    res.status(400).json({
      message: "변경할 쿠폰 상태가 올바르지 않습니다."
    });
    return;
  }
  const existingList = await runtimeListDiscountCoupons();
  const target = existingList.find(item => Number(item.id) === couponId) || null;
  if (!target) {
    res.status(404).json({
      message: "쿠폰을 찾을 수 없습니다."
    });
    return;
  }
  if (String(target.status || "").toLowerCase() === "used") {
    res.status(400).json({
      message: "이미 사용 완료된 쿠폰은 상태를 변경할 수 없습니다."
    });
    return;
  }
  const coupon = await runtimeUpdateDiscountCoupon(couponId, {
    status: nextStatus
  });
  res.json({
    message: nextStatus === "active" ? "쿠폰을 다시 활성화했습니다." : "쿠폰을 비활성화했습니다.",
    coupon,
    current
  });
});
async function recoverProvisioningLabs(labs) {
  const targets = labs.filter(lab => String(lab?.status || "").trim().toLowerCase() === "provisioning");
  if (!targets.length) return labs;
  const platformStatus = await runtimeGetPlatformStatus();
  const recoveredById = new Map();
  for (const lab of targets) {
    const course = await runtimeFindCourseById(lab.courseId).catch(() => null);
    if (!course) continue;
    const recovered = await recoverStaleProvisioningLab(lab, course, platformStatus).catch(error => {
      console.warn("[lab-recovery] failed during lab list refresh", {
        labId: lab.id,
        courseId: lab.courseId,
        message: error?.message
      });
      return null;
    });
    if (recovered && recovered !== lab) {
      recoveredById.set(Number(lab.id), recovered);
    }
  }
  return recoveredById.size ? labs.map(lab => recoveredById.get(Number(lab.id)) || lab) : labs;
}
const LAB_MAC_RECONCILIATION_RETRY_MS = 5 * 60 * 1000;
const labMacReconciliationRetryAt = new Map();
async function reconcileMissingLabMacAddresses(labs) {
  const now = Date.now();
  const targets = labs.filter(lab => needsLabMacReconciliation(lab) && Number(labMacReconciliationRetryAt.get(Number(lab.id)) || 0) <= now);
  if (!targets.length) return labs;
  const platformStatus = await runtimeGetPlatformStatus();
  const serviceProjectName = getServiceProjectName(platformStatus);
  const updatedById = new Map();
  for (const lab of targets) {
    const labId = Number(lab.id);
    const projectName = String(lab.projectName || "").trim() || serviceProjectName;
    labMacReconciliationRetryAt.set(labId, now + LAB_MAC_RECONCILIATION_RETRY_MS);
    try {
      const stack = await resolveHeatStack({
        stackName: lab.stackName,
        projectName
      });
      const merged = mergeResolvedVmNodeMacAddresses(lab.vmNodes, stack?.vmNodes);
      if (!merged.changed) continue;
      const updated = await runtimeUpdateLabRequest(labId, {
        vmNodes: merged.nodes
      });
      updatedById.set(labId, updated);
      labMacReconciliationRetryAt.delete(labId);
    } catch (error) {
      console.warn("[lab-mac] failed to reconcile missing VM MAC addresses", {
        labId,
        stackName: lab.stackName,
        message: error?.message || String(error)
      });
    }
  }
  return updatedById.size ? labs.map(lab => updatedById.get(Number(lab.id)) || lab) : labs;
}
async function listUserLabsWithProvisioningRecovery(userId) {
  const labs = await recoverProvisioningLabs(await runtimeListLabRequestsByUser(userId));
  return reconcileMissingLabMacAddresses(labs);
}
