async function recoverStaleProvisioningCustomLabRequest(request, platformStatus) {
  if (String(request?.status || "").trim().toLowerCase() !== "provisioning") {
    return request;
  }
  const stackName = String(request?.stackName || "").trim();
  const projectName = getPocProjectName(platformStatus);
  if (!stackName || !projectName) {
    return request;
  }
  try {
    const stack = await resolveHeatStack({
      stackName,
      projectName
    });
    const heatStatus = String(stack?.status || "").trim().toUpperCase();
    if (stack && heatStatus.endsWith("_COMPLETE") && heatStatus !== "DELETE_COMPLETE") {
      const ipSummary = computeLabIpSummary({
        vmNodes: Array.isArray(stack.vmNodes) && stack.vmNodes.length ? stack.vmNodes : request.vmNodes || [],
        instanceIps: Array.isArray(stack.instanceIps) && stack.instanceIps.length ? stack.instanceIps : request.instanceIps || [],
        instanceIp: stack.instanceIp || request.instanceIp || ""
      });
      return runtimeUpdateCustomLabRequest(request.id, {
        status: "running",
        stackName: stack.stackName || stackName,
        stackId: stack.stackId || request.stackId || "",
        instanceIp: ipSummary.instanceIp,
        instanceIps: ipSummary.instanceIps,
        vmNodes: Array.isArray(stack.vmNodes) && stack.vmNodes.length ? stack.vmNodes : request.vmNodes || [],
        advancedConfig: {
          ...(request.advancedConfig || {}),
          createdResources: collectPocCreatedResources(stack.raw?.outputs || []),
          generatedHeatTemplate: true,
          provisionedAt: request.advancedConfig?.provisionedAt || new Date().toISOString()
        },
        errorMessage: "",
        startedAt: request.startedAt || new Date().toISOString()
      });
    }
    if (stack && heatStatus.endsWith("_FAILED")) {
      return runtimeUpdateCustomLabRequest(request.id, {
        status: "failed",
        errorMessage: stack.statusReason || `Heat stack 상태가 ${heatStatus} 입니다.`
      });
    }
    if (!stack || heatStatus === "DELETE_COMPLETE") {
      if (isLabProvisioningMissingStackGraceActive(request)) {
        return request;
      }
      return runtimeUpdateCustomLabRequest(request.id, {
        status: "failed",
        stackId: "",
        stackName: "",
        instanceIp: "",
        instanceIps: [],
        vmNodes: [],
        errorMessage: "이전 HeatStack이 OpenStack에서 확인되지 않아 생성 실패로 정리했습니다. 관리자 재시도를 확인해 주세요."
      });
    }
  } catch (error) {
    console.warn("[custom-lab-recovery] failed to resolve provisioning heat stack", {
      requestId: request.id,
      stackName,
      projectName,
      message: error?.message
    });
  }
  return request;
}
async function recoverProvisioningCustomLabRequests(requests, platformStatus = null) {
  const targets = (Array.isArray(requests) ? requests : []).filter(request => String(request?.status || "").trim().toLowerCase() === "provisioning");
  if (!targets.length) return requests;
  const settings = platformStatus || (await runtimeGetPlatformStatus());
  const recoveredById = new Map();
  for (const request of targets) {
    const recovered = await recoverStaleProvisioningCustomLabRequest(request, settings);
    if (recovered && String(recovered.status || "").trim().toLowerCase() !== "provisioning") {
      recoveredById.set(Number(request.id), recovered);
    }
  }
  return recoveredById.size ? requests.map(request => recoveredById.get(Number(request.id)) || request) : requests;
}
