app.post("/api/custom-lab-requests/prepaid", requireAuth, async (req, res) => {
  const title = String(req.body?.title || "").trim();
  const settings = await runtimeGetPlatformStatus();
  if (!settings.pocEnabled && String(req.user?.role || "").toLowerCase() !== "admin") {
    res.status(403).json({
      message: "서비스 준비중 입니다."
    });
    return;
  }
  const allowedImages = Array.isArray(settings.pocAllowedImages) && settings.pocAllowedImages.length ? settings.pocAllowedImages : ["lab-rocky-9-2026", "ubuntu-24.04"];
  const allowedFlavors = Array.isArray(settings.pocAllowedFlavors) && settings.pocAllowedFlavors.length ? settings.pocAllowedFlavors : settings.selfServiceVmAllowedFlavors || ["m1.tiny", "m1.small", "m1.medium"];
  const flavor = String(req.body?.flavor || req.body?.advancedConfig?.standard?.flavor || allowedFlavors[0] || "").trim();
  const imageName = String(req.body?.imageName || req.body?.advancedConfig?.standard?.imageName || allowedImages[0] || "").trim();
  const usageDays = Math.max(1, Number.parseInt(req.body?.usageDays, 10) || 1);
  const instanceCount = Number(req.body?.instanceCount || 1);
  const cloudInitTemplateName = normalizeTemplateFileName(req.body?.cloudInitTemplateName || "");
  const rawAdvancedConfig = req.body?.advancedConfig || {};
  const advancedConfig = normalizePocAdvancedConfig(rawAdvancedConfig);
  const requestedTerminalLogin = resolveRequestedPocTerminalLogin(req.body || {});
  const selectedSpec = getPocFlavorSpec(flavor, settings);
  const quote = applyPocFreeAccessToQuote(calculatePocPrepaidQuote({
    flavor,
    instanceCount,
    usageDays
  }, settings), settings, req.user);
  if (!title) {
    res.status(400).json({
      message: "구성 이름을 입력해 주세요."
    });
    return;
  }
  if (!allowedImages.includes(imageName)) {
    res.status(400).json({
      message: "관리자가 허용한 이미지 중 하나를 선택해 주세요."
    });
    return;
  }
  if (!allowedFlavors.includes(flavor)) {
    res.status(400).json({
      message: "관리자가 허용한 Flavor 중 하나를 선택해 주세요."
    });
    return;
  }
  if (!Number.isInteger(instanceCount) || instanceCount < 1 || instanceCount > POC_MAX_INSTANCE_COUNT) {
    res.status(400).json({
      message: `인스턴스 개수는 1대 이상 ${POC_MAX_INSTANCE_COUNT}대 이하의 정수여야 합니다.`
    });
    return;
  }
  if (quote.dailyPrice <= 0 && !quote.freeAccess) {
    res.status(400).json({
      message: "선택한 Flavor의 1일 단가가 설정되어 있지 않습니다."
    });
    return;
  }
  if (advancedConfig.loadBalancer.enabled && !advancedConfig.network.enabled) {
    res.status(400).json({
      message: "로드밸런서를 사용하려면 전용 네트워크도 함께 활성화해 주세요."
    });
    return;
  }
  if (advancedConfig.cloudInit.mode === "custom" && !advancedConfig.cloudInit.content.trim()) {
    res.status(400).json({
      message: "직접 입력 cloud-init 내용을 입력하거나 파일을 업로드해 주세요."
    });
    return;
  }
  if (String(rawAdvancedConfig?.cloudInit?.content || "").length > POC_CUSTOM_CLOUD_INIT_MAX_BYTES) {
    res.status(400).json({
      message: "cloud-init 내용이 너무 큽니다. 템플릿 크기를 줄여 주세요."
    });
    return;
  }
  const standardConfig = {
    flavor,
    dailyPrice: quote.dailyPrice,
    usageDays: quote.usageDays,
    subtotal: quote.subtotal,
    discountAmount: quote.discountAmount,
    discounts: quote.discounts,
    amount: quote.amount,
    freeAccess: Boolean(quote.freeAccess)
  };
  const request = await runtimeCreateCustomLabRequest({
    userId: req.user.id,
    title,
    instanceCount: quote.instanceCount,
    vcpu: selectedSpec.vcpu,
    ramGb: selectedSpec.ramGb,
    diskGb: selectedSpec.diskGb,
    imageName,
    usagePeriod: `${quote.usageDays}일`,
    desiredBudget: quote.amount,
    note: String(req.body?.note || "").trim(),
    advancedConfig: {
      ...advancedConfig,
      standard: standardConfig
    },
    cloudInitTemplateName,
    terminalSshUser: requestedTerminalLogin?.username || "",
    terminalSshPassword: requestedTerminalLogin?.password || ""
  });
  const quoted = await runtimeUpdateCustomLabRequest(request.id, {
    status: "quoted",
    quotedPrice: String(quote.amount),
    paymentStatus: quote.freeAccess ? "waived" : "",
    paymentProvider: quote.freeAccess ? "free" : "",
    paymentPaidAt: quote.freeAccess ? new Date().toISOString() : null,
    desiredBudget: quote.amount,
    reviewNote: `자동 견적: ${flavor} x ${quote.instanceCount}대 x ${quote.usageDays}일`,
    advancedConfig: {
      ...(request.advancedConfig || {}),
      standard: standardConfig
    }
  });
  if (quote.freeAccess) {
    try {
      await runtimeUpdateCustomLabRequest(request.id, {
        status: "confirmed"
      });
      const provisioned = await provisionCustomLabRequest(request.id, {
        actorUser: req.user,
        quotedPrice: String(quote.amount),
        reviewNote: "무료 PoC 권한으로 결제 없이 자동 프로비저닝을 시작했습니다."
      });
      res.status(201).json({
        message: "무료 PoC 구성을 생성하기 시작했습니다.",
        request: provisioned
      });
      return;
    } catch (error) {
      res.status(500).json({
        message: error.message || "PoC 자원 생성 중 오류가 발생했습니다.",
        request: await runtimeFindCustomLabRequestById(request.id)
      });
      return;
    }
  }
  res.status(201).json({
    message: "PoC 랩 견적을 생성했습니다. 결제 후 자동으로 자원 생성이 시작됩니다.",
    request: quoted
  });
});
