app.post("/api/custom-lab-requests/:id/keypair", requireAuth, async (req, res) => {
  const requestId = Number(req.params.id);
  const requestUserId = Number(req.user?.id || 0);
  const request = await runtimeFindCustomLabRequestById(requestId);
  if (!request || Number(request.userId) !== requestUserId) {
    res.status(404).json({
      message: "사용자 PoC랩 신청을 찾을 수 없습니다."
    });
    return;
  }
  const status = String(request.status || "").trim().toLowerCase();
  if (!["requested", "quoted", "confirmed"].includes(status) || request.stackId || request.stackName) {
    res.status(400).json({
      message: "자원 생성 전 PoC 요청에서만 SSH 키를 생성할 수 있습니다."
    });
    return;
  }
  if (request.advancedConfig?.keypair?.name) {
    res.status(409).json({
      message: "이미 이 PoC 요청에 SSH 키가 생성되어 있습니다. private key는 다시 받을 수 없습니다."
    });
    return;
  }
  const platformStatus = await runtimeGetPlatformStatus();
  const keyName = buildPocKeypairName(request);
  const created = await createOpenstackKeypair({
    keyName,
    projectName: getPocProjectName(platformStatus)
  });
  if (!created.privateKey) {
    await deleteOpenstackKeypair({
      keyName: created.name || keyName,
      projectName: getPocProjectName(platformStatus)
    }).catch(() => {});
    res.status(502).json({
      message: "OpenStack에서 private key를 반환하지 않았습니다. keypair 생성 방식을 확인해 주세요."
    });
    return;
  }
  const now = new Date().toISOString();
  const advancedConfig = normalizePocAdvancedConfig({
    ...(request.advancedConfig || {}),
    keypair: {
      mode: "openstack",
      name: created.name || keyName,
      fingerprint: created.fingerprint || "",
      createdAt: now,
      downloadedAt: now
    }
  });
  let updated;
  try {
    updated = await runtimeUpdateCustomLabRequest(requestId, {
      advancedConfig
    });
  } catch (error) {
    await deleteOpenstackKeypair({
      keyName: created.name || keyName,
      projectName: getPocProjectName(platformStatus)
    }).catch(() => {});
    throw error;
  }
  res.json({
    message: "SSH keypair가 생성되었습니다. private key는 지금 한 번만 다운로드됩니다.",
    request: updated,
    keypair: {
      name: created.name || keyName,
      fingerprint: created.fingerprint || "",
      fileName: `${created.name || keyName}.pem`,
      privateKey: created.privateKey
    }
  });
});
app.post("/api/custom-lab-requests/:id/confirm", requireAuth, async (req, res) => {
  const requestId = Number(req.params.id);
  const requestUserId = Number(req.user?.id || 0);
  const request = await runtimeFindCustomLabRequestById(requestId);
  if (!request || Number(request.userId) !== requestUserId) {
    res.status(404).json({
      message: "사용자 PoC랩 신청을 찾을 수 없습니다."
    });
    return;
  }
  if (request.status !== "quoted") {
    res.status(400).json({
      message: "견적이 등록된 요청만 진행 확정할 수 있습니다."
    });
    return;
  }
  const quotedAmount = parseQuotedPrice(request.quotedPrice);
  if (quotedAmount > 0 && String(request.paymentStatus || "").toLowerCase() !== "paid") {
    res.status(400).json({
      message: "결제가 필요한 PoC 구성입니다. 결제를 완료해 주세요."
    });
    return;
  }
  if (quotedAmount <= 0) {
    await runtimeUpdateCustomLabRequest(requestId, {
      status: "confirmed",
      paymentStatus: "waived",
      paymentProvider: "free",
      paymentPaidAt: request.paymentPaidAt || new Date().toISOString(),
      paymentFailureReason: ""
    });
    try {
      const provisioned = await provisionCustomLabRequest(requestId, {
        actorUser: req.user,
        quotedPrice: request.quotedPrice,
        reviewNote: "무료 PoC 권한으로 결제 없이 자동 프로비저닝을 시작했습니다."
      });
      res.json({
        message: "무료 PoC 구성을 생성하기 시작했습니다.",
        request: provisioned
      });
      return;
    } catch (error) {
      res.status(500).json({
        message: error.message || "PoC 자원 생성 중 오류가 발생했습니다.",
        request: await runtimeFindCustomLabRequestById(requestId)
      });
      return;
    }
  }
  const updated = await runtimeUpdateCustomLabRequest(requestId, {
    status: "confirmed"
  });
  res.json({
    message: "사용자 PoC랩 진행을 확정했습니다.",
    request: updated
  });
});
app.post("/api/custom-lab-requests/:id/payment/prepare", requireAuth, async (req, res) => {
  const requestId = Number(req.params.id);
  const requestUserId = Number(req.user?.id || 0);
  const request = await runtimeFindCustomLabRequestById(requestId);
  if (!request || Number(request.userId) !== requestUserId) {
    res.status(404).json({
      message: "사용자 PoC랩 신청을 찾을 수 없습니다."
    });
    return;
  }
  if (request.status !== "quoted") {
    res.status(400).json({
      message: "견적이 등록된 요청만 결제를 진행할 수 있습니다."
    });
    return;
  }
  const amount = parseQuotedPrice(request.quotedPrice);
  if (amount <= 0) {
    const updated = await runtimeUpdateCustomLabRequest(requestId, {
      paymentStatus: "waived",
      paymentProvider: "free",
      paymentPaidAt: request.paymentPaidAt || new Date().toISOString(),
      paymentFailureReason: "",
      status: "confirmed"
    });
    res.json({
      message: "무료 PoC 구성은 결제 없이 생성할 수 있습니다.",
      request: updated,
      payment: {
        provider: "free",
        orderId: "",
        amount: 0,
        currency: "KRW",
        orderName: `[PoC] ${request.title}`
      }
    });
    return;
  }
  const settings = await runtimeGetPlatformStatus();
  if (!settings.paymentGatewayEnabled) {
    res.status(400).json({
      message: "현재 결제 기능이 비활성화되어 있습니다."
    });
    return;
  }
  const existingReady = ["ready", "pending"].includes(String(request.paymentStatus || "").toLowerCase()) && request.paymentOrderId;
  const orderId = existingReady ? request.paymentOrderId : buildPocPaymentOrderId(request);
  const updated = await runtimeUpdateCustomLabRequest(requestId, {
    paymentStatus: "ready",
    paymentProvider: settings.paymentGatewayProvider || "manual",
    paymentOrderId: orderId,
    paymentRequestedAt: new Date().toISOString(),
    paymentFailedAt: null,
    paymentFailureReason: ""
  });
  res.json({
    message: "PoC 결제를 준비했습니다.",
    request: updated,
    payment: {
      provider: settings.paymentGatewayProvider || "manual",
      merchantId: settings.paymentGatewayMerchantId || "",
      apiBaseUrl: settings.paymentGatewayApiBaseUrl || "",
      publicKey: settings.paymentGatewayPublicKey || "",
      orderId,
      amount,
      currency: "KRW",
      orderName: `[PoC] ${request.title}`
    }
  });
});
app.post("/api/custom-lab-requests/:id/payment/confirm", requireAuth, async (req, res) => {
  const requestId = Number(req.params.id);
  const requestUserId = Number(req.user?.id || 0);
  const request = await runtimeFindCustomLabRequestById(requestId);
  const paymentKey = String(req.body?.paymentKey || "").trim();
  const orderId = String(req.body?.orderId || "").trim();
  const amount = Number(req.body?.amount || 0);
  if (!request || Number(request.userId) !== requestUserId) {
    res.status(404).json({
      message: "사용자 PoC랩 신청을 찾을 수 없습니다."
    });
    return;
  }
  if (request.status !== "quoted") {
    res.status(400).json({
      message: "견적이 등록된 요청만 결제를 확정할 수 있습니다."
    });
    return;
  }
  if (!orderId || !paymentKey || !Number.isFinite(amount) || amount <= 0) {
    res.status(400).json({
      message: "orderId, paymentKey, amount가 필요합니다."
    });
    return;
  }
  const expectedAmount = parseQuotedPrice(request.quotedPrice);
  if (expectedAmount <= 0 || amount !== expectedAmount) {
    res.status(400).json({
      message: "견적 금액과 결제 금액이 일치하지 않습니다."
    });
    return;
  }
  const expectedOrderId = String(request.paymentOrderId || "").trim();
  if (expectedOrderId && orderId !== expectedOrderId) {
    res.status(400).json({
      message: "결제 주문번호가 일치하지 않습니다."
    });
    return;
  }
  const provider = normalizePaymentGatewayProvider(request.paymentProvider || (await runtimeGetPlatformStatus()).paymentGatewayProvider || "");
  if (provider !== "tosspayments") {
    res.status(400).json({
      message: "현재 PoC 결제 제공사는 사용자 결제 확인 API를 지원하지 않습니다."
    });
    return;
  }
  const resolvedOrderId = expectedOrderId || orderId;
  const providerPayload = await confirmTossPayment({
    amount: expectedAmount,
    orderId: resolvedOrderId,
    id: request.id
  }, {
    paymentKey,
    amount: expectedAmount,
    orderId: resolvedOrderId
  });
  const updated = await runtimeUpdateCustomLabRequest(requestId, {
    paymentStatus: "paid",
    paymentProvider: provider || request.paymentProvider || "",
    paymentOrderId: resolvedOrderId,
    paymentKey,
    paymentPaidAt: new Date().toISOString(),
    paymentFailureReason: "",
    status: "confirmed"
  });
  let provisioned = updated;
  try {
    provisioned = await provisionCustomLabRequest(requestId, {
      actorUser: req.user,
      quotedPrice: request.quotedPrice,
      reviewNote: "선결제 완료 후 자동 프로비저닝을 시작했습니다."
    });
  } catch (error) {
    res.status(500).json({
      message: `${error.message || "PoC 자원 생성 중 오류가 발생했습니다."} 결제는 완료되었으므로 환불 또는 재시도를 확인해 주세요.`,
      request: await runtimeFindCustomLabRequestById(requestId)
    });
    return;
  }
  if (req.user.email) {
    const customLabPaymentPaidMail = buildCustomLabPaymentPaidMail({
      name: req.user.name,
      requestTitle: request.title || `PoC #${request.id}`,
      orderId: resolvedOrderId,
      formattedAmount: formatCurrency(expectedAmount)
    });
    sendMailNotification({
      type: "custom_lab_payment_paid",
      to: req.user.email,
      subject: customLabPaymentPaidMail.subject,
      text: customLabPaymentPaidMail.text,
      templateKey: customLabPaymentPaidMail.templateKey,
      templateVariables: customLabPaymentPaidMail.templateVariables,
      metadata: {
        customLabRequestId: request.id,
        orderId: resolvedOrderId,
        paymentKey,
        amount: expectedAmount
      }
    }).catch(error => {
      console.warn("[mail] custom lab payment success mail failed", {
        requestId: request.id,
        message: error.message
      });
    });
  }
  res.json({
    message: "PoC 결제가 완료되어 진행이 확정되었습니다.",
    request: provisioned,
    providerPayload
  });
});
