    customLabRequestId: request.id,
    host: targetHost.address,
    hostType: targetHost.type || "fixed",
    nodeId: targetHost.nodeId || "",
    nodeName: targetHost.nodeName || "",
    username: resolvedUsername,
    password: resolvedPassword,
    port: terminalPort,
    jumpHost: "",
    jumpUser: "",
