app.get("/api/admin/cloud-console/flavor-capacity", requireCloudConsoleAdmin, async (req, res) => {
  const platformStatus = await runtimeGetPlatformStatus();
  applyOpenstackCloudSettings(platformStatus);
  const projectName = String(req.query?.projectName || getServiceProjectName(platformStatus)).trim();
  const allowedFlavors = platformStatus.selfServiceVmAllowedFlavors?.length ? platformStatus.selfServiceVmAllowedFlavors : SELF_SERVICE_VM_ALLOWED_FLAVORS;
  try {
    const quota = await probeOpenstackQuota({
      projectName
    });
    const liveFlavorDetails = await listFlavorDetails({
      flavorNames: allowedFlavors,
      projectName
    }).catch(() => []);
    const liveFlavorMap = new Map(liveFlavorDetails.map(item => [item.name, item]));
    const aiProfiles = normalizeAiVmFlavorCatalog(platformStatus.aiVmFlavorCatalog, allowedFlavors);
    const metrics = quota?.metrics || {};
    const remaining = {
      instances: getQuotaMetricRemaining(metrics.instances),
      cores: getQuotaMetricRemaining(metrics.cores),
      ram: getQuotaMetricRemaining(metrics.ram)
    };
    const flavors = [];
    for (const flavorName of allowedFlavors) {
      const fallback = getSelfServiceVmFallbackFlavorSpec(flavorName);
      const live = liveFlavorMap.get(flavorName) || null;
      const spec = {
        vcpus: Number(live?.vcpus || live?.vcpu || 0) || fallback.vcpus,
        ram: Number(live?.ramMb || live?.ram || 0) || fallback.ram,
        disk: Number(live?.diskGb || live?.disk || 0) || fallback.disk
      };
      const limits = [{
        key: "instances",
        label: "인스턴스",
        count: remaining.instances
      }, {
        key: "cores",
        label: "vCPU",
        count: remaining.cores == null ? null : Math.floor(remaining.cores / Math.max(1, spec.vcpus))
      }, {
        key: "ram",
        label: "RAM",
        count: remaining.ram == null ? null : Math.floor(remaining.ram / Math.max(1, spec.ram))
      }].filter(item => item.count != null);
      const maxCreatable = limits.length ? Math.max(0, Math.min(...limits.map(item => item.count))) : null;
      const bottlenecks = maxCreatable == null ? [] : limits.filter(item => item.count === maxCreatable).map(item => item.label);
      const aiProfile = aiProfiles.find(item => item.flavorName === flavorName) || null;
      const requiredSpecsMatch = aiProfile ? Object.entries(aiProfile.expectedExtraSpecs || {}).every(([key, value]) => String(live?.extraSpecs?.[key] ?? "") === String(value)) : null;
      flavors.push({
        name: flavorName,
        id: live?.id || "",
        vcpus: spec.vcpus,
        ramMb: spec.ram,
        diskGb: spec.disk,
        ephemeralGb: live?.ephemeralGb || 0,
        extraSpecs: live?.extraSpecs || {},
        source: live ? "openstack" : "fallback",
        maxCreatable,
        bottlenecks,
        aiProfile,
        requiredSpecsMatch
      });
    }
    res.json({
      projectName: quota?.projectName || projectName,
      projectId: quota?.projectId || "",
      remaining,
      flavors,
      calculatedAt: new Date().toISOString()
    });
  } catch (error) {
    res.status(error.statusCode || 502).json({
      message: sanitizeOpenstackErrorMessage(error),
      detail: req.user.role === "admin" ? String(error.message || "") : ""
    });
  }
});
app.get("/api/admin/cloud-console/resources", requireCloudConsoleAdmin, async (_req, res) => {
  const platformStatus = await runtimeGetPlatformStatus();
  applyOpenstackCloudSettings(platformStatus);
  const requests = await runtimeListSelfServiceProjectRequests();
  const approved = requests.filter(item => item.status === "approved" && String(item.projectName || item.requestedProjectName || "").trim());
  const projectNames = [...new Set(approved.map(item => String(item.projectName || item.requestedProjectName || "").trim()))];
  const projects = [];
  for (const projectName of projectNames) {
    const request = approved.find(item => isSameSelfServiceProjectName(item.projectName || item.requestedProjectName, projectName));
    try {
      const snapshot = await getOpenstackProjectSnapshot({
        projectName
      });
      projects.push({
        projectName,
        userId: request?.userId || null,
        userName: request?.userName || request?.username || "",
        ok: true,
        refreshedAt: snapshot.refreshedAt,
        instances: snapshot.instances || [],
        volumes: snapshot.volumes || [],
        networks: snapshot.networks || [],
        subnets: snapshot.subnets || [],
        loadBalancers: snapshot.loadBalancers || [],
        loadBalancerListeners: snapshot.loadBalancerListeners || [],
        loadBalancerPools: snapshot.loadBalancerPools || [],
        loadBalancerMembers: snapshot.loadBalancerMembers || [],
        loadBalancerHealthMonitors: snapshot.loadBalancerHealthMonitors || [],
        dnsZones: snapshot.dnsZones || [],
        shares: snapshot.shares || [],
        reservations: snapshot.reservations || [],
        alarms: snapshot.alarms || [],
        services: {
          manila: Boolean(snapshot.shareAvailable),
          blazar: Boolean(snapshot.reservationAvailable),
          aodh: Boolean(snapshot.alarmAvailable),
          octavia: Boolean(snapshot.loadBalancerAvailable)
        },
        warnings: snapshot.warnings || []
      });
    } catch (error) {
      projects.push({
        projectName,
        userId: request?.userId || null,
        userName: request?.userName || request?.username || "",
        ok: false,
        instances: [],
        volumes: [],
        networks: [],
        subnets: [],
        loadBalancers: [],
        loadBalancerListeners: [],
        loadBalancerPools: [],
        loadBalancerMembers: [],
        loadBalancerHealthMonitors: [],
        dnsZones: [],
        shares: [],
        reservations: [],
        alarms: [],
        services: {},
        warnings: [sanitizeOpenstackErrorMessage(error)]
      });
    }
  }
  res.json({
    projects,
    refreshedAt: new Date().toISOString()
  });
});
async function resolveApprovedAdminCloudProject(inputProjectName) {
  const requestedProjectName = String(inputProjectName || "").trim();
  if (!requestedProjectName) {
    const error = new Error("관리할 OpenStack 프로젝트를 선택해 주세요.");
    error.statusCode = 400;
    throw error;
  }
  const requests = await runtimeListSelfServiceProjectRequests();
  const matched = requests.find(item => item.status === "approved" && isSameSelfServiceProjectName(item.projectName || item.requestedProjectName, requestedProjectName));
  if (!matched) {
    const error = new Error("승인된 클라우드 콘솔 프로젝트만 관리할 수 있습니다.");
    error.statusCode = 403;
    throw error;
  }
  return String(matched.projectName || matched.requestedProjectName || "").trim();
}
async function runAdminLoadBalancerMutation(req, res, action) {
  try {
    const platformStatus = await runtimeGetPlatformStatus();
    applyOpenstackCloudSettings(platformStatus);
    const projectName = await resolveApprovedAdminCloudProject(req.body?.projectName || req.query?.projectName);
    const result = await executeCloudConsoleWithQuotaRepair({
      projectName,
      platformStatus,
      ownerLabel: req.user?.name || req.user?.username || "cloud-admin",
      action: () => action(projectName)
    });
    res.json({
      ok: true,
      projectName,
      result
    });
  } catch (error) {
    res.status(error.statusCode || error.status || 502).json({
      code: "ADMIN_LOAD_BALANCER_ACTION_FAILED",
      message: sanitizeOpenstackErrorMessage(error),
      detail: String(error?.message || "")
    });
  }
}
