app.post("/api/self-service-vms/:id/power-action", requireAuth, async (req, res) => {
  const vmId = Number(req.params.id);
  const requestUserId = Number(req.user?.id || 0);
  const vm = await runtimeFindSelfServiceVmById(vmId);
  if (!vm || req.user.role !== "admin" && Number(vm.userId) !== requestUserId) {
    res.status(404).json({
      message: "사용자화 가상머신을 찾을 수 없습니다."
    });
    return;
  }
  if (req.user.role !== "admin" && !req.user.selfServiceVmEnabled) {
    res.status(403).json({
      message: "사용자화 가상머신 구성은 관리자가 허용한 사용자만 사용할 수 있습니다. 관리자에게 권한 요청을 보내 주세요."
    });
    return;
  }
  const status = String(vm.status || "").trim().toLowerCase();
  if (["terminated", "deleted", "failed", "rejected", "cancelled", "canceled"].includes(status)) {
    res.status(400).json({
      message: `현재 상태(${vm.status || "-"})에서는 전원 작업을 실행할 수 없습니다.`
    });
    return;
  }
  try {
    const platformStatus = await runtimeGetPlatformStatus();
    const result = await runVmPowerAction({
      resource: vm,
      platformStatus,
      action: req.body?.action,
      fallbackProjectName: String(vm.projectName || "").trim() || getServiceProjectName(platformStatus)
    });
    const patch = result.action === "stop" ? {
      status: "stopped",
      vmNodes: Array.isArray(vm.vmNodes) ? vm.vmNodes.map(node => ({
        ...node,
        status: "stopped"
      })) : []
    } : {
      status: "running",
      vmNodes: Array.isArray(vm.vmNodes) ? vm.vmNodes.map(node => ({
        ...node,
        status: "running"
      })) : []
    };
    const updated = await runtimeUpdateSelfServiceVm(vm.id, patch);
    await syncPublishedLabRoutes();
    if (req.user.role === "admin") {
      await recordAdminAudit(req, {
        action: `self_service_vm.power.${result.action}`,
        targetType: "self_service_vm",
        targetId: vm.id,
        summary: `${result.label}: ${vm.username || vm.userName || vm.stackName || vm.id}`,
        metadata: {
          userId: vm.userId,
          statusBefore: vm.status,
          statusAfter: updated.status,
          serverIds: result.serverIds,
          projectName: result.projectName
        }
      });
    }
    res.json({
      message: `사용자화 가상머신 ${result.label}을 실행했습니다.`,
      vm: updated,
      result
    });
  } catch (error) {
    res.status(500).json({
      message: error.message || "사용자화 가상머신 전원 작업을 실행하지 못했습니다."
    });
  }
});
