app.get("/api/trove/datastores", requireAuth, async (req, res) => {
  const platformStatus = await runtimeGetPlatformStatus();
  if (!platformStatus.troveEnabled && req.user.role !== "admin") {
    res.json({
      datastores: [],
      available: false,
      serviceEnabled: false,
      message: "서비스 준비중 입니다"
    });
    return;
  }
  if (!platformStatus.troveApiUrl) {
    res.json({
      datastores: (platformStatus.troveAllowedDatastores || []).map(name => ({
        id: name,
        name
      })),
      available: false,
      message: "Trove API URL이 아직 설정되지 않았습니다."
    });
    return;
  }
  try {
    const projectName = await resolveTroveProjectForUser(req.user, platformStatus, req.query?.projectName);
    const datastores = await listTroveDatastores({
      apiUrl: platformStatus.troveApiUrl,
      projectName
    });
    const allowed = new Set((platformStatus.troveAllowedDatastores || []).map(name => String(name).trim().toLowerCase()));
    const visibleDatastores = allowed.size ? datastores.filter(item => allowed.has(String(item.name || item.id || "").trim().toLowerCase())) : datastores;
    res.json({
      datastores: visibleDatastores
    });
  } catch (error) {
    res.json({
      datastores: (platformStatus.troveAllowedDatastores || []).map(name => ({
        id: name,
        name
      })),
      available: false,
      message: error.message || "Trove datastore 목록을 가져오지 못했습니다."
    });
  }
});
function publicTroveInstance(record) {
  if (!record) return record;
  const {
    credentialSecretRef,
    ...safe
  } = record;
  return {
    ...safe,
    hasCredential: Boolean(credentialSecretRef)
  };
}
app.get("/api/trove/instances", requireAuth, async (req, res) => {
  const platformStatus = await runtimeGetPlatformStatus();
  if (!platformStatus.troveEnabled && req.user.role !== "admin") {
    res.json({
      instances: [],
      serviceEnabled: false
    });
    return;
  }
  const instances = req.user.role === "admin" ? await runtimeListTroveInstances() : await runtimeListTroveInstancesByUser(req.user.id);
  res.json({
    instances: instances.map(publicTroveInstance)
  });
});
app.post("/api/trove/instances", requireAuth, async (req, res) => {
  const platformStatus = await runtimeGetPlatformStatus();
  if (!platformStatus.troveEnabled && req.user.role !== "admin") {
    res.status(503).json({
      message: "서비스 준비중 입니다"
    });
    return;
  }
  if (!platformStatus.troveApiUrl) {
    res.status(503).json({
      message: "관리자가 아직 Trove API URL을 설정하지 않았습니다."
    });
    return;
  }
  const allowedDatastores = platformStatus.troveAllowedDatastores || [];
  const allowedFlavors = platformStatus.troveAllowedFlavors || [];
  const allowedSizesGb = platformStatus.troveAllowedSizesGb || [];
  const name = String(req.body?.name || "").trim();
  const datastoreType = String(req.body?.datastoreType || "").trim();
  const datastoreVersion = String(req.body?.datastoreVersion || "").trim();
  const flavor = String(req.body?.flavor || "").trim();
  const sizeGb = Math.max(1, Number(req.body?.sizeGb || 1) || 1);
  const databaseName = String(req.body?.databaseName || name).trim().replace(/[^a-zA-Z0-9_$]/g, "_").slice(0, 64);
  const databaseUsername = `dbu_${Number(req.user.id).toString(36)}_${randomBytes(3).toString("hex")}`;
  const databasePassword = randomBytes(24).toString("base64url");
  const databasePort = datastoreType.toLowerCase() === "postgresql" ? 5432 : 3306;
  let projectName = "";
  if (!name || !datastoreType || !flavor) {
    res.status(400).json({
      message: "DB 이름, datastore, flavor를 입력해 주세요."
    });
    return;
  }
  if (name.length > 64) {
    res.status(400).json({
      message: "DB 이름은 64자 이하로 입력해 주세요."
    });
    return;
  }
  if (allowedDatastores.length && !allowedDatastores.includes(datastoreType)) {
    res.status(400).json({
      message: "허용되지 않은 datastore입니다."
    });
    return;
  }
  if (allowedFlavors.length && !allowedFlavors.includes(flavor)) {
    res.status(400).json({
      message: "허용되지 않은 flavor입니다."
    });
    return;
  }
  if (allowedSizesGb.length && !allowedSizesGb.includes(sizeGb)) {
    res.status(400).json({
      message: "허용되지 않은 볼륨 크기입니다."
    });
    return;
  }
  try {
    projectName = await resolveTroveProjectForUser(req.user, platformStatus, req.body?.projectName);
  } catch (error) {
    res.status(error.statusCode || 400).json({
      code: error.code || "CLOUD_PROJECT_REQUIRED",
      message: error.message
    });
    return;
  }
  let flavorRef = "";
  try {
    const resolvedFlavor = await resolveFlavorByName({
      flavorName: flavor,
      projectName
    });
    flavorRef = String(resolvedFlavor?.id || "").trim();
    if (!flavorRef) {
      res.status(422).json({
        message: `선택한 Flavor(${flavor})를 OpenStack 프로젝트에서 찾을 수 없습니다. 관리자에게 허용 Flavor 설정을 확인해 주세요.`
      });
      return;
    }
  } catch (error) {
    const statusCode = Number(error?.statusCode || error?.status || 0);
    res.status(statusCode >= 400 && statusCode < 500 ? statusCode : 502).json({
      message: "데이터베이스용 Flavor 정보를 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.",
      detail: req.user.role === "admin" ? String(error?.message || "") : ""
    });
    return;
  }
  const record = await runtimeCreateTroveInstance({
    userId: req.user.id,
    projectName,
    name,
    datastoreType,
    datastoreVersion,
    flavor,
    sizeGb,
    databaseName,
    databaseUsername,
    databasePort,
    status: "provisioning",
    statusReason: "Trove 인스턴스 생성을 시작합니다.",
    startedAt: new Date().toISOString()
  });
  let credentialSecretRef = "";
  try {
    credentialSecretRef = await createDatabaseCredentialSecret({
      projectName,
      instanceName: name,
      payload: {
        username: databaseUsername,
        password: databasePassword,
        database: databaseName,
        port: databasePort
      }
    });
    const remote = await createTroveRemoteInstance({
      apiUrl: platformStatus.troveApiUrl,
      projectName,
      name,
      datastoreType,
      datastoreVersion,
      flavor: flavorRef,
      sizeGb,
      databaseName,
      databaseUsername,
      databasePassword,
      nics: process.env.TROVE_NETWORK_ID ? [{
        "net-id": process.env.TROVE_NETWORK_ID
      }] : []
    });
    const updated = await runtimeUpdateTroveInstance(record.id, {
      status: remote.status || "building",
      instanceUuid: remote.instanceUuid,
      hostname: remote.hostname || "",
      datastoreType: remote.datastoreType || datastoreType,
      datastoreVersion: remote.datastoreVersion || datastoreVersion,
      databaseName,
      databaseUsername,
      credentialSecretRef,
      databasePort,
      statusReason: "Trove 인스턴스 생성이 진행 중입니다.",
      errorMessage: "",
      startedAt: new Date().toISOString()
    });
    res.status(201).json({
      message: "Trove DB 인스턴스 생성을 요청했습니다.",
      instance: publicTroveInstance(updated)
    });
  } catch (error) {
    if (credentialSecretRef) {
      await deleteDatabaseCredentialSecret({
        projectName,
        credentialSecretRef
      }).catch(() => {});
    }
    // 원격 생성 요청 자체가 실패한 레코드는 사용자 자원 목록에 남기지 않는다.
    await runtimeDeleteTroveInstance(record.id).catch(() => {});
    const upstreamStatus = Number(error?.statusCode || error?.status || 0);
    const responseStatus = upstreamStatus >= 400 && upstreamStatus < 500 ? upstreamStatus : 502;
    const missingResource = /Resource\s+.+\s+cannot be found/i.test(String(error?.message || ""));
    res.status(responseStatus).json({
      message: missingResource ? "OpenStack에서 데이터베이스 생성에 필요한 자원을 찾지 못했습니다. 관리자에게 Flavor와 datastore 설정을 확인해 주세요." : sanitizeOpenstackErrorMessage(error) || "Trove DB 인스턴스를 생성하지 못했습니다.",
      detail: req.user.role === "admin" ? String(error?.message || "") : ""
    });
  }
});
