const ALLOWED_QNA_POST_TYPES = new Set(["question", "error", "tip", "resource", "project", "study", "free", "notice"]);
const ALLOWED_QNA_STATUSES = new Set(["open", "in_progress", "solved", "closed"]);
app.post("/api/qna", requireAuth, async (req, res) => {
  const courseId = req.body?.courseId == null || req.body?.courseId === "" ? null : Number(req.body?.courseId);
  const labRequestId = req.body?.labRequestId == null || req.body?.labRequestId === "" ? null : Number(req.body?.labRequestId);
  const requestedPostType = String(req.body?.postType || "question").trim().toLowerCase();
  const postType = ALLOWED_QNA_POST_TYPES.has(requestedPostType) ? requestedPostType : "question";
  const title = String(req.body?.title || "").trim();
  const body = String(req.body?.body || "").trim();
  let lab = null;
  if (!title || !body) {
    res.status(400).json({
      message: "제목과 내용을 입력해 주세요."
    });
    return;
  }
  if (courseId != null && !Number.isFinite(courseId)) {
    res.status(400).json({
      message: "과정 정보가 올바르지 않습니다."
    });
    return;
  }
  if (courseId != null && Number.isFinite(courseId)) {
    const course = await runtimeFindCourseById(courseId);
    if (!course) {
      res.status(404).json({
        message: "과정 정보를 찾을 수 없습니다."
      });
      return;
    }
    if (!(await canAccessCourse(req.user, course))) {
      res.status(403).json({
        message: "이 과정에 접근할 권한이 없습니다."
      });
      return;
    }
  }
  if (labRequestId != null) {
    if (!Number.isFinite(labRequestId)) {
      res.status(400).json({
        message: "랩 정보가 올바르지 않습니다."
      });
      return;
    }
    lab = await runtimeFindLabRequestById(labRequestId);
    if (!lab) {
      res.status(404).json({
        message: "연결할 랩 정보를 찾을 수 없습니다."
      });
      return;
    }
    if (req.user?.role !== "admin" && Number(lab.userId || 0) !== Number(req.user.id || 0)) {
      res.status(403).json({
        message: "본인 랩만 게시글에 연결할 수 있습니다."
      });
      return;
    }
    if (courseId != null && Number(lab.courseId || 0) !== Number(courseId)) {
      res.status(400).json({
        message: "선택한 과정과 랩 정보가 일치하지 않습니다."
      });
      return;
    }
  }
  const resolvedCourseId = courseId != null ? courseId : lab?.courseId ? Number(lab.courseId) : null;
  const post = await runtimeCreateQnaPost({
    userId: req.user.id,
    courseId: resolvedCourseId,
    labRequestId,
    postType,
    title,
    body,
    labContext: lab ? {
      status: lab.status || "",
      stackName: lab.stackName || "",
      instanceIp: lab.instanceIp || "",
      courseTitle: lab.courseTitle || ""
    } : {}
  });
  const recipients = await listAllowedMessageRecipientsForUser(req.user);
  const supportRecipients = resolveSupportRecipients(await runtimeListUsers());
  const notificationRecipients = [...new Map(recipients.flatMap(item => item.id === "group:support" ? supportRecipients : [item]).filter(item => Number(item.id) !== Number(req.user.id)).map(item => [Number(item.id), item])).values()];
  await Promise.all(notificationRecipients.map(item => createUserNotification({
    userId: item.id,
    type: "qna",
    title: `새 커뮤니티 글: ${title}`,
    body: `${req.user.name || req.user.username}님이 새 글을 등록했습니다.`,
    linkSection: "qna",
    metadata: {
      postId: post.id,
      authorId: req.user.id,
      postType
    }
  })));
  res.status(201).json({
    message: "커뮤니티 글이 등록되었습니다.",
    post
  });
});
