function buildNoVncWebSocketUrl(consoleUrl) {
  const parsed = new URL(consoleUrl);
  const wsProtocol = parsed.protocol === "https:" ? "wss:" : "ws:";
  const pathParam = parsed.searchParams.get("path");
  let wsPath = "";
  if (pathParam) {
    wsPath = pathParam.startsWith("/") || pathParam.startsWith("?") ? pathParam : `/${pathParam}`;
    if (wsPath.startsWith("?")) wsPath = `/${wsPath}`;
  } else {
    const token = parsed.searchParams.get("token");
    wsPath = `/websockify${token ? `?token=${encodeURIComponent(token)}` : parsed.search || ""}`;
  }
  return `${wsProtocol}//${parsed.host}${wsPath}`;
}
function waitForRfbMessage(ws, timeoutMs = 8000) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error("noVNC 콘솔 응답 시간이 초과되었습니다."));
    }, timeoutMs);
    function cleanup() {
      clearTimeout(timer);
      ws.off("message", handleMessage);
      ws.off("error", handleError);
      ws.off("close", handleClose);
    }
    function handleMessage(data) {
      cleanup();
      resolve(Buffer.isBuffer(data) ? data : Buffer.from(data));
    }
    function handleError(error) {
      cleanup();
      reject(error);
    }
    function handleClose() {
      cleanup();
      reject(new Error("noVNC 콘솔 연결이 닫혔습니다."));
    }
    ws.once("message", handleMessage);
    ws.once("error", handleError);
    ws.once("close", handleClose);
  });
}
function sendVncClientCutText(ws, text) {
  const payload = Buffer.from(String(text || ""), "utf8");
  const header = Buffer.alloc(8);
  header[0] = 6;
  header.writeUInt32BE(payload.length, 4);
  ws.send(Buffer.concat([header, payload]));
}
function getVncKeysym(character) {
  if (character === "\n") return 0xff0d;
  if (character === "\t") return 0xff09;
  if (character === "\b") return 0xff08;
  const codePoint = character.codePointAt(0);
  if (!Number.isFinite(codePoint)) return 0;
  if (codePoint >= 0x20 && codePoint <= 0x7e) return codePoint;
  return 0;
}
function sendVncKeyEvent(ws, keysym, isDown) {
  const message = Buffer.alloc(8);
  message[0] = 4;
  message[1] = isDown ? 1 : 0;
  message.writeUInt32BE(keysym >>> 0, 4);
  ws.send(message);
}
async function sendVncTypedText(ws, text) {
  for (const character of String(text || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n")) {
    const keysym = getVncKeysym(character);
    if (!keysym) continue;
    sendVncKeyEvent(ws, keysym, true);
    sendVncKeyEvent(ws, keysym, false);
    await new Promise(resolve => setTimeout(resolve, 5));
  }
}
async function sendNoVncInput({
  consoleUrl,
  text,
  mode = "clipboard"
}) {
  const wsUrl = buildNoVncWebSocketUrl(consoleUrl);
  const ws = await new Promise((resolve, reject) => {
    const socket = new WebSocket(wsUrl, ["binary"]);
    const timer = setTimeout(() => {
      socket.close();
      reject(new Error("noVNC 콘솔에 연결하지 못했습니다."));
    }, 8000);
    socket.once("open", () => {
      clearTimeout(timer);
      resolve(socket);
    });
    socket.once("error", error => {
      clearTimeout(timer);
      reject(error);
    });
  });
  try {
    const serverVersion = await waitForRfbMessage(ws);
    if (!serverVersion.toString("ascii", 0, 3).startsWith("RFB")) {
      throw new Error("VNC 프로토콜 응답을 확인하지 못했습니다.");
    }
    ws.send(Buffer.from("RFB 003.008\n", "ascii"));
    const securityTypes = await waitForRfbMessage(ws);
    const securityTypeCount = securityTypes[0] || 0;
    const supportedTypes = Array.from(securityTypes.slice(1, 1 + securityTypeCount));
    if (!supportedTypes.includes(1)) {
      throw new Error("현재 noVNC 콘솔은 무인 클립보드 전송을 지원하지 않는 인증 방식입니다.");
    }
    ws.send(Buffer.from([1]));
    const securityResult = await waitForRfbMessage(ws);
    if (securityResult.length < 4 || securityResult.readUInt32BE(0) !== 0) {
      throw new Error("noVNC 콘솔 인증이 실패했습니다.");
    }
    ws.send(Buffer.from([1]));
    const serverInit = await waitForRfbMessage(ws);
    if (serverInit.length < 24) {
      throw new Error("noVNC 콘솔 초기화 정보를 확인하지 못했습니다.");
    }
    if (mode === "type") {
      await sendVncTypedText(ws, text);
    } else {
      sendVncClientCutText(ws, text);
    }
    await new Promise(resolve => setTimeout(resolve, 150));
  } finally {
    ws.close();
  }
}
