app.post("/api/admin/users", requireAdmin, async (req, res) => {
  const name = String(req.body?.name || "").trim();
  const email = String(req.body?.email || "").trim();
  const username = String(req.body?.username || "").trim();
  const password = String(req.body?.password || "");
  const requestedRole = String(req.body?.role || "student").trim().toLowerCase();
  const requestedStatus = String(req.body?.status || "approved").trim().toLowerCase();
  const role = requestedRole === "administrator" ? "admin" : requestedRole;
  const status = requestedStatus;
  if (!name || !username || !password) {
    res.status(400).json({
      message: "이름, 아이디, 비밀번호를 입력해 주세요."
    });
    return;
  }
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    res.status(400).json({
      message: "유효한 이메일 주소를 입력해 주세요."
    });
    return;
  }
  if (password.length < 8) {
    res.status(400).json({
      message: "비밀번호는 8자 이상이어야 합니다."
    });
    return;
  }
  if (!["student", "admin"].includes(role)) {
    res.status(400).json({
      message: "허용되지 않는 권한입니다."
    });
    return;
  }
  if (!["pending", "approved"].includes(status)) {
    res.status(400).json({
      message: "허용되지 않는 승인 상태입니다."
    });
    return;
  }
  const existing = await runtimeFindUserByUsername(username);
  if (existing) {
    res.status(409).json({
      message: "이미 사용 중인 아이디입니다."
    });
    return;
  }
  const passwordHash = await bcrypt.hash(password, 10);
  const user = await runtimeCreateUser({
    name,
    email,
    username,
    passwordHash,
    role,
    status,
    userSource: "admin_manual"
  });
  if (status === "approved" && user?.email) {
    const adminCreatedUserMail = buildAdminCreatedUserMail({
      name: user.name,
      username: user.username
    });
    sendMailNotification({
      type: "admin_created_user",
      to: user.email,
      subject: adminCreatedUserMail.subject,
      text: adminCreatedUserMail.text,
      templateKey: adminCreatedUserMail.templateKey,
      templateVariables: adminCreatedUserMail.templateVariables,
      metadata: {
        userId: user.id,
        username: user.username,
        createdBy: req.user.username
      }
    }).catch(error => {
      console.warn("[mail] admin created user mail failed", {
        userId: user.id,
        message: error.message
      });
    });
  }
  await recordAdminAudit(req, {
    action: "user.create",
    targetType: "user",
    targetId: user.id,
    summary: `사용자 생성: ${user.username}`,
    metadata: {
      role: user.role,
      status: user.status,
      userSource: user.userSource
    }
  });
  res.status(201).json({
    message: "사용자를 생성했습니다.",
    user
  });
});
app.post("/api/admin/users/batch-create", requireAdmin, async (req, res) => {
  const usernamePrefix = String(req.body?.usernamePrefix || "").trim();
  const namePrefix = String(req.body?.namePrefix || usernamePrefix || "user").trim();
  const startNumber = Math.max(1, Number(req.body?.startNumber || 1));
  const endNumber = Math.max(startNumber, Number(req.body?.endNumber || startNumber));
  const password = String(req.body?.password || "");
  const requestedRole = String(req.body?.role || "student").trim().toLowerCase();
  const requestedStatus = String(req.body?.status || "approved").trim().toLowerCase();
  const role = requestedRole === "administrator" ? "admin" : requestedRole;
  const status = requestedStatus;
  if (!usernamePrefix || !password) {
    res.status(400).json({
      message: "아이디 접두어와 초기 비밀번호를 입력해 주세요."
    });
    return;
  }
  if (password.length < 8) {
    res.status(400).json({
      message: "비밀번호는 8자 이상이어야 합니다."
    });
    return;
  }
  if (!["student", "admin"].includes(role)) {
    res.status(400).json({
      message: "허용되지 않는 권한입니다."
    });
    return;
  }
  if (!["pending", "approved"].includes(status)) {
    res.status(400).json({
      message: "허용되지 않는 승인 상태입니다."
    });
    return;
  }
  if (endNumber - startNumber + 1 > 200) {
    res.status(400).json({
      message: "한 번에 최대 200명까지 생성할 수 있습니다."
    });
    return;
  }
  const passwordHash = await bcrypt.hash(password, 10);
  const created = [];
  const skipped = [];
  for (let number = startNumber; number <= endNumber; number += 1) {
    const username = `${usernamePrefix}${number}`;
    const existing = await runtimeFindUserByUsername(username);
    if (existing) {
      skipped.push(username);
      continue;
    }
    const user = await runtimeCreateUser({
      name: `${namePrefix}${number}`,
      email: "",
      username,
      passwordHash,
      role,
      status,
      userSource: "admin_temporary"
    });
    created.push(user);
  }
  res.status(201).json({
    message: created.length ? `임시 사용자를 ${created.length}명 생성했습니다.${skipped.length ? ` ${skipped.length}명은 기존 계정이라 건너뛰었습니다.` : ""}` : "생성된 사용자가 없습니다. 기존 계정 여부를 확인해 주세요.",
    users: created,
    skipped
  });
});
