  const labAutoCircuitBreakerEnabled = Object.prototype.hasOwnProperty.call(req.body || {}, "labAutoCircuitBreakerEnabled") ? req.body.labAutoCircuitBreakerEnabled !== false : currentPlatformStatus.labAutoCircuitBreakerEnabled !== false;
