app.post("/api/admin/llm/test", requireAdmin, async (req, res) => {
  const settings = await runtimeGetPlatformStatus();
  const draftSettings = buildDraftLlmTestSettings(settings, req.body?.settings);
  const llmConnection = resolveLlmConnectionSettings(draftSettings);
  if (!llmConnection.apiUrl) {
    res.status(400).json({
      message: "LLM 연결 정보를 먼저 저장해 주세요."
    });
    return;
  }
  const question = String(req.body?.question || "연결 테스트").trim();
  try {
    const payload = await requestLlmChat({
      provider: llmConnection.provider,
      apiUrl: llmConnection.apiUrl,
      model: llmConnection.model,
      apiKey: llmConnection.apiKey,
      systemPrompt: buildEffectiveLlmSystemPrompt(draftSettings, llmConnection.provider, draftSettings.llmSystemPrompt || ""),
      question: buildEffectiveLlmQuestion(draftSettings, llmConnection.provider, question),
      maxTokens: draftSettings.llmAdminTestMaxTokens || LLM_ADMIN_TEST_MAX_TOKENS,
      extraBody: buildLlmExtraBody(draftSettings, llmConnection.provider),
      context: {
        source: "admin-test",
        user: {
          id: req.user.id,
          name: req.user.name,
          username: req.user.username,
          role: req.user.role
        }
      }
    });
    const answerParts = extractLlmParts(payload);
    res.json({
      message: "LLM API 연결 테스트에 성공했습니다.",
      answer: answerParts.content,
      thinking: answerParts.thinking,
      provider: llmConnection.provider,
      model: llmConnection.model,
      apiUrl: llmConnection.apiUrl,
      raw: payload
    });
  } catch (error) {
    const detail = [error?.message ? `원인: ${error.message}` : "", error?.status ? `HTTP 상태: ${error.status}` : "", llmConnection?.apiUrl ? `엔드포인트: ${llmConnection.apiUrl}` : ""].filter(Boolean).join("\n");
    console.error("[llm] admin test failed", {
      message: error.message,
      status: error?.status,
      apiUrl: llmConnection?.apiUrl,
      payload: error?.payload || null
    });
    res.status(502).json({
      message: "LLM API 연결 테스트에 실패했습니다.",
      detail,
      provider: llmConnection.provider,
      apiUrl: llmConnection.apiUrl,
      raw: error?.payload || null
    });
  }
});
