app.post("/api/admin/mail/send", requireAdmin, async (req, res) => {
  const recipientMode = String(req.body?.recipientMode || "manual").trim() || "manual";
  const mailPurpose = String(req.body?.mailPurpose || req.body?.purpose || "operational").trim().toLowerCase();
  const isMarketingMail = mailPurpose === "marketing";
  const {
    recipients,
    matchedUsernames,
    tokens,
    skippedRecipients
  } = await resolveAdminMailRecipients({
    to: req.body?.to,
    recipientMode,
    marketingOnly: isMarketingMail
  });
  const subject = String(req.body?.subject || "").trim();
  const text = String(req.body?.text || "").trim();
  if (isMarketingMail && (!recipients.length || !subject || !text)) {
    res.status(400).json({
      message: "마케팅 메일 수신 동의자가 없거나 제목/내용이 비어 있습니다."
    });
    return;
  }
  if (!recipients.length || !subject || !text) {
    res.status(400).json({
      message: "받는 사람, 제목, 내용을 모두 입력해 주세요."
    });
    return;
  }
  try {
    await sendMailNotification({
      type: isMarketingMail ? "marketing_broadcast" : "admin_broadcast",
      to: recipients,
      subject,
      text,
      metadata: {
        sentBy: req.user?.username || "admin",
        recipientCount: recipients.length,
        recipientMode,
        mailPurpose: isMarketingMail ? "marketing" : "operational",
        recipientTokens: tokens,
        matchedUsernames,
        skippedRecipients,
        at: new Date().toISOString()
      }
    });
    if (isMarketingMail) {
      res.json({
        message: `${recipients.length}명에게 마케팅 메일을 발송했습니다.${skippedRecipients ? ` 미동의 또는 미등록 ${skippedRecipients}건은 제외했습니다.` : ""}`,
        recipientCount: recipients.length,
        recipientMode,
        mailPurpose: "marketing",
        skippedRecipients,
        tokens,
        logs: await runtimeListMailLogs(200)
      });
      return;
    }
    res.json({
      message: `${recipients.length}명에게 관리자 메일링을 발송했습니다.`,
      recipientCount: recipients.length,
      recipientMode,
      mailPurpose: isMarketingMail ? "marketing" : "operational",
      skippedRecipients,
      tokens,
      logs: await runtimeListMailLogs(200)
    });
  } catch (error) {
    console.error("[mail] admin broadcast failed", {
      message: error?.message
    });
    res.status(502).json({
      message: error?.message || "메일 발송에 실패했습니다.",
      recipientCount: recipients.length,
      recipientMode,
      tokens,
      logs: await runtimeListMailLogs(200).catch(() => [])
    });
  }
});
