app.post("/api/admin/mail-campaigns", requireAdmin, async (req, res) => {
  try {
    const subject = String(req.body?.subject || "").trim();
    const text = String(req.body?.text || req.body?.bodyText || "").trim();
    const name = String(req.body?.name || subject || "메일 캠페인").trim().slice(0, 200);
    if (!subject || !text) throw createHttpError(400, "메일 제목과 내용을 입력해 주세요.");
    const resolved = await resolveMailCampaignRequestRecipients(req.body || {});
    if (!resolved.recipients.length) throw createHttpError(400, "발송할 유효 수신자가 없습니다.");
    const replyDeadlineDays = Math.max(0, Math.min(90, Number(req.body?.replyDeadlineDays || 0) || 0));
    const replyDeadlineAt = replyDeadlineDays ? new Date(Date.now() + replyDeadlineDays * 24 * 60 * 60 * 1000).toISOString() : null;
    const campaign = await runtimeCreateMailCampaign({
      name,
      purpose: resolved.purpose,
      subject,
      bodyText: text,
      recipientModes: resolved.recipientModes,
      sourceFileName: String(req.body?.sourceFileName || "").trim().slice(0, 255),
      sourceHash: resolved.sourceHash,
      replyDeadlineAt,
      createdBy: req.user?.id || null,
      createdByUsername: req.user?.username || "admin",
      recipients: resolved.recipients
    });
    await recordAdminAudit(req, {
      action: "mail.campaign.create",
      targetType: "mail_campaign",
      targetId: campaign.id,
      summary: `메일 캠페인 생성: ${name}`,
      metadata: {
        purpose: resolved.purpose,
        recipientCount: resolved.recipients.length,
        csvRecipientCount: resolved.csvRecipientCount,
        memberRecipientCount: resolved.memberRecipientCount,
        duplicateCount: resolved.duplicateCount
      }
    });
    res.status(202).json({
      message: `${resolved.recipients.length}명 대상 메일 캠페인을 발송 대기열에 등록했습니다.`,
      campaign
    });
  } catch (error) {
    res.status(error?.status || error?.statusCode || 400).json({
      message: error?.message || "메일 캠페인을 만들지 못했습니다."
    });
  }
});
