app.get("/api/admin/backups/export", requireAdmin, async (req, res) => {
  try {
    const bundle = await buildBackupBundle(req.user);
    const fileName = `terminal-lab-backup-${new Date().toISOString().replace(/[:.]/g, "-")}.json.gz`;
    const payload = Buffer.from(JSON.stringify(bundle, null, 2), "utf8");
    const compressed = await gzipBuffer(payload);
    res.setHeader("Content-Type", "application/gzip");
    res.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
    res.setHeader("Content-Length", String(compressed.length));
    res.send(compressed);
  } catch (error) {
    res.status(error?.status || 500).json({
      message: error?.message || "백업 파일을 생성하지 못했습니다."
    });
  }
});
app.post("/api/admin/backups/restore", requireAdmin, async (req, res) => {
  let upload;
  try {
    upload = await parseBackupImportUpload(req);
  } catch (error) {
    res.status(error?.status || 400).json({
      message: error?.message || "백업 파일 업로드를 처리하지 못했습니다."
    });
    return;
  }
  try {
    const rawBuffer = Buffer.from(await upload.file.arrayBuffer());
    const maxCompressedBytes = bytesFromMb(BACKUP_IMPORT_MAX_MB);
    const maxPayloadBytes = bytesFromMb(BACKUP_IMPORT_UNCOMPRESSED_MAX_MB);
    if (rawBuffer.length > maxCompressedBytes) {
      res.status(413).json({
        message: `백업 파일이 너무 큽니다. ${BACKUP_IMPORT_MAX_MB}MB 이하 파일로 다시 시도해 주세요.`
      });
      return;
    }
    const maybeCompressed = upload.fileName.toLowerCase().endsWith(".gz");
    const payload = maybeCompressed ? await gunzipBufferLimited(rawBuffer, maxPayloadBytes, `압축 해제된 백업 파일이 너무 큽니다. ${BACKUP_IMPORT_UNCOMPRESSED_MAX_MB}MB 이하로 준비해 주세요.`) : rawBuffer;
    if (payload.length > maxPayloadBytes) {
      res.status(413).json({
        message: `백업 파일 내용이 너무 큽니다. ${BACKUP_IMPORT_UNCOMPRESSED_MAX_MB}MB 이하로 준비해 주세요.`
      });
      return;
    }
    const bundle = JSON.parse(payload.toString("utf8"));
    await restoreBackupBundle(bundle);
    res.json({
      message: "백업 데이터를 복원했습니다. 세션과 화면 상태를 새로고침합니다.",
      restoredAt: new Date().toISOString()
    });
  } catch (error) {
    res.status(400).json({
      message: error?.message || "백업 파일을 복원하지 못했습니다."
    });
  }
});
app.post("/api/admin/notices", requireAdmin, async (req, res) => {
  const title = String(req.body?.title || "").trim();
  const body = String(req.body?.body || "").trim();
  const isPinned = Boolean(req.body?.isPinned);
  if (!title || !body) {
    res.status(400).json({
      message: "Title and body are required."
    });
    return;
  }
  const notice = await runtimeCreateNotice({
    title,
    body,
    isPinned,
    createdBy: req.user.id
  });
  await recordAdminAudit(req, {
    action: "notice.create",
    targetType: "notice",
    targetId: notice.id,
    summary: `공지 등록: ${notice.title}`,
    metadata: {
      isPinned: notice.isPinned
    }
  });
  res.status(201).json({
    message: "Notice created.",
    notice
  });
});
