app.put("/api/admin/heat-templates/:name", requireAdmin, async (req, res) => {
  const name = normalizeTemplateFileName(req.params.name);
  const content = String(req.body?.content || "");
  if (!name) {
    res.status(400).json({
      message: "템플릿 파일명을 확인해 주세요."
    });
    return;
  }
  if (!content.trim()) {
    res.status(400).json({
      message: "템플릿 내용을 입력해 주세요."
    });
    return;
  }
  if (heatTemplateUsesYamlMergeKeys(content)) {
    res.status(400).json({
      message: "Heat 템플릿에는 YAML 병합 키(<<:)를 사용할 수 없습니다. OpenStack Heat가 리소스 속성으로 오인하므로 명시적인 속성으로 풀어서 저장해 주세요."
    });
    return;
  }
  await fs.mkdir(HEAT_TEMPLATES_DIR, {
    recursive: true
  });
  const templatePath = path.join(HEAT_TEMPLATES_DIR, name);
  const replaced = await fs.access(templatePath).then(() => true).catch(() => false);
  await fs.writeFile(templatePath, content, "utf8");
  res.json({
    message: replaced ? "기존 Heat 템플릿을 덮어썼습니다." : "Heat 템플릿을 새로 저장했습니다.",
    replaced,
    template: {
      name,
      content
    }
  });
});
app.delete("/api/admin/heat-templates/:name", requireAdmin, async (req, res) => {
  const name = normalizeTemplateFileName(req.params.name);
  if (!name) {
    res.status(400).json({
      message: "삭제할 템플릿 파일명이 올바르지 않습니다."
    });
    return;
  }
  const courses = await runtimeListCourses();
  const usedBy = courses.filter(course => String(course.heatTemplateName || "").trim() === name);
  if (usedBy.length) {
    res.status(400).json({
      message: `현재 사용 중인 템플릿은 삭제할 수 없습니다. (${usedBy.map(course => course.title).join(", ")})`
    });
    return;
  }
  const filePath = path.join(HEAT_TEMPLATES_DIR, name);
  try {
    await fs.unlink(filePath);
  } catch (error) {
    if (error?.code === "ENOENT") {
      res.status(404).json({
        message: "템플릿 파일을 찾을 수 없습니다."
      });
      return;
    }
    throw error;
  }
  res.json({
    message: "Heat 템플릿을 삭제했습니다."
  });
});
