app.post("/api/admin/application-yamls", requireAdmin, express.json({
  limit: ADMIN_UPLOAD_JSON_LIMIT
}), async (req, res) => {
  const name = normalizeTemplateFileName(req.body?.fileName);
  const contentBase64 = String(req.body?.contentBase64 || "");
  const directContent = typeof req.body?.content === "string" ? req.body.content : "";
  const category = normalizeApplicationYamlCategory(req.body?.category);
  const description = String(req.body?.description || "").trim();
  if (!name) {
    res.status(400).json({
      message: "업로드할 파일명을 확인해 주세요."
    });
    return;
  }
  if (!contentBase64 && !String(directContent || "").trim()) {
    res.status(400).json({
      message: "업로드할 YAML 내용이 없습니다."
    });
    return;
  }
  const content = contentBase64 ? Buffer.from(contentBase64, "base64").toString("utf8") : String(directContent || "");
  if (!content.trim()) {
    res.status(400).json({
      message: "YAML 내용이 비어 있습니다."
    });
    return;
  }
  const validationError = getApplicationYamlValidationError(name, content);
  if (validationError) {
    res.status(400).json({
      message: validationError
    });
    return;
  }
  const item = await saveApplicationYaml(name, content, {
    category,
    description
  });
  res.status(201).json({
    message: "Application YAML을 업로드했습니다.",
    item
  });
});
