async function validatePackageItemReferences(courseInput, packageCourseId = null) {
  if (courseInput.courseType !== "package") return "";
  const itemIds = courseInput.packageItems || [];
  if (packageCourseId && itemIds.includes(Number(packageCourseId))) return "패키지 자신을 포함 항목으로 선택할 수 없습니다.";
  const courses = await runtimeListCourses();
  const courseById = new Map(courses.map(course => [Number(course.id), course]));
  const invalid = itemIds.find(id => !courseById.has(Number(id)) || courseById.get(Number(id)).courseType === "package");
  return invalid ? "패키지에는 삭제되지 않은 일반·온라인·시험 과정만 포함할 수 있습니다." : "";
}
app.post("/api/admin/custom-lab-requests/:id/approve-domain", requireAdmin, async (req, res) => {
  try {
    const platformStatus = await runtimeGetPlatformStatus();
    if (platformStatus.publicDomainRoutesEnabled === false) {
      res.status(403).json({
        message: "공개 도메인 기능이 비활성화되어 승인할 수 없습니다."
      });
      return;
    }
    const requestId = Number(req.params.id);
    const request = await runtimeFindCustomLabRequestById(requestId);
    if (!request) {
      res.status(404).json({
        message: "PoC 랩 요청을 찾을 수 없습니다."
      });
      return;
    }
    const rawDomainType = String(req.body?.domainType || "").trim().toLowerCase();
    const requestedSubdomain = rawDomainType === "custom" ? sanitizeCustomDomainFqdn(req.body?.fqdn || req.body?.customDomain || req.body?.subdomain) : sanitizePublicSubdomain(req.body?.subdomain);
    const pendingDomains = Array.isArray(request.requestedPublicDomains) ? request.requestedPublicDomains : [];
    if (!pendingDomains.length) {
      res.status(400).json({
        message: "승인 대기 중인 PoC 공개 도메인 요청이 없습니다."
      });
      return;
    }
    const domainsToApprove = requestedSubdomain ? pendingDomains.filter(entry => entry.subdomain === requestedSubdomain) : pendingDomains;
    if (!domainsToApprove.length) {
      res.status(404).json({
        message: "선택한 승인 대기 도메인을 찾을 수 없습니다."
      });
      return;
    }
    const excludeResource = {
      resourceType: "custom-lab",
      id: request.id
    };
    for (const entry of domainsToApprove) {
      if (!isAllowedPublicRoutePort(entry.port, platformStatus, ALLOWED_PUBLIC_ROUTE_PORTS)) {
        res.status(400).json({
          message: getPublicRoutePortBlockedMessage(entry.port, platformStatus)
        });
        return;
      }
      const availability = String(entry.domainType || "").toLowerCase() === "custom" ? await checkCustomDomainAvailability(entry.fqdn, excludeResource) : await checkDomainAvailability(entry.subdomain, excludeResource);
      if (!availability.available) {
        res.status(409).json({
          message: availability.message
        });
        return;
      }
      if (String(entry.domainType || "").toLowerCase() === "custom" && !availability.verified) {
        res.status(409).json({
          message: "사용자 도메인 TXT 소유권 확인이 완료되지 않았습니다.",
          availability
        });
        return;
      }
    }
    const reviewNote = String(req.body?.reviewNote || "").trim();
    const reviewedBy = req.user?.name ? `${req.user.name} (${req.user.username})` : req.user?.username || "admin";
    const reviewedAt = new Date().toISOString();
    const remainingRequestedDomains = requestedSubdomain ? pendingDomains.filter(entry => entry.subdomain !== requestedSubdomain) : [];
    const nextPublicDomains = [...(request.publicDomains || []), ...domainsToApprove];
    const approved = await runtimeUpdateCustomLabRequest(request.id, {
      publicDomains: nextPublicDomains,
      requestedPublicDomains: remainingRequestedDomains,
      publicEnabled: nextPublicDomains.length > 0,
      publicRequestPending: remainingRequestedDomains.length > 0,
      publicReviewedBy: reviewedBy,
      publicReviewedAt: reviewedAt,
      publicReviewNote: reviewNote
    });
    await createUserNotification({
      userId: request.userId,
      type: "domain_approved",
      title: "PoC 도메인 요청이 승인되었습니다",
      body: `${domainsToApprove.map(entry => entry.url).filter(Boolean).join(", ") || "요청한 PoC 도메인"}을 사용할 수 있습니다.`,
      linkSection: "customLabs",
      metadata: {
        customLabRequestId: request.id,
        domains: domainsToApprove
      }
    });
    await syncPublishedLabRoutes();
    res.json({
      message: "PoC 공개 도메인 요청을 승인했습니다.",
      request: approved,
      lab: approved
    });
  } catch (error) {
    console.error("[domain] custom approve failed", {
      message: error?.message
    });
    res.status(500).json({
      message: error?.message || "PoC 공개 도메인 요청 처리 중 오류가 발생했습니다."
    });
  }
});
