function normalizeVmPowerAction(value = "") {
  const action = String(value || "").trim().toLowerCase().replace(/_/g, "-");
  if (["soft-reboot", "reboot", "normal-reboot"].includes(action)) return "soft-reboot";
  if (["hard-reboot", "force-reboot", "forced-reboot"].includes(action)) return "hard-reboot";
  if (["stop", "power-off", "shutdown", "poweroff"].includes(action)) return "stop";
  return "";
}
function getVmPowerActionLabel(action = "") {
  if (action === "soft-reboot") return "일반 리부팅";
  if (action === "hard-reboot") return "강제 리부팅";
  if (action === "stop") return "전원 끄기";
  return "전원 작업";
}
function collectResourceServerRefs(resource = {}) {
  const refs = [];
  const add = (value = "") => {
    const id = String(value || "").trim();
    if (id && !refs.includes(id)) refs.push(id);
  };
  add(resource.instanceUuid);
  add(resource.serverId);
  if (Array.isArray(resource.serverIds)) resource.serverIds.forEach(add);
  if (Array.isArray(resource.vmNodes)) {
    resource.vmNodes.forEach(node => {
      add(node?.serverId);
      add(node?.instanceUuid);
      add(node?.instanceId);
    });
  }
  return refs;
}
async function resolveVmPowerTargetServers(resource, platformStatus, fallbackProjectName = "") {
  const projectName = String(resource?.projectName || fallbackProjectName || getServiceProjectName(platformStatus)).trim();
  const directRefs = collectResourceServerRefs(resource);
  if (directRefs.length) return {
    projectName,
    serverIds: directRefs,
    resolved: false
  };
  const nodes = deriveTerminalNodes(resource);
  const fixedIp = String(nodes.find(node => node.fixedIp)?.fixedIp || (Array.isArray(resource?.instanceIps) ? resource.instanceIps.find(item => String(item?.type || "").toLowerCase() === "fixed")?.address : "") || resource?.instanceIp || "").trim();
  const stackName = String(resource?.stackName || "").trim();
  if (!stackName && !fixedIp) return {
    projectName,
    serverIds: [],
    resolved: false
  };
  const resolved = await resolveOpenstackServer({
    serverName: stackName,
    fixedIp,
    projectName
  });
  return {
    projectName,
    serverIds: resolved?.id ? [resolved.id] : [],
    resolved: Boolean(resolved?.id)
  };
}
async function runVmPowerAction({
  resource,
  platformStatus,
  action,
  fallbackProjectName = ""
} = {}) {
  const normalizedAction = normalizeVmPowerAction(action);
  if (!normalizedAction) throw new Error("지원하지 않는 전원 작업입니다.");
  const target = await resolveVmPowerTargetServers(resource, platformStatus, fallbackProjectName);
  if (!target.serverIds.length) throw new Error("전원 작업을 실행할 OpenStack 서버 ID를 찾지 못했습니다.");
  const results = [];
  for (const serverId of target.serverIds) {
    if (normalizedAction === "stop") {
      results.push(await stopOpenstackServer({
        serverId,
        projectName: target.projectName
      }));
    } else {
      results.push(await rebootOpenstackServer({
        serverId,
        projectName: target.projectName,
        hard: normalizedAction === "hard-reboot"
      }));
    }
  }
  invalidateOpenstackStatusCaches();
  return {
    action: normalizedAction,
    label: getVmPowerActionLabel(normalizedAction),
    projectName: target.projectName,
    serverIds: target.serverIds,
    results
  };
}
