let shutdownStarted = false;
async function shutdownApplication(signal) {
  if (shutdownStarted) return;
  shutdownStarted = true;
  console.log(`[shutdown] ${signal} received; closing active connections`);
  for (const socket of wss.clients) {
    try {
      socket.terminate();
    } catch {}
  }

  try {
    wss.close();
  } catch {}
  try {

  } catch {}
  for (const [sessionId, terminalSession] of terminalSessions.entries()) {
    try {
      terminalSession.ptyProcess?.kill("SIGTERM");
    } catch {}
    try {
      terminalSession.sshProcess?.kill("SIGTERM");
    } catch {}
    terminalSessions.delete(sessionId);
  }
  const closeHttpServer = new Promise(resolve => {
    server.close(() => resolve());
    server.closeIdleConnections?.();
  });
  const closeResources = Promise.allSettled([closeHttpServer, runtimeCloseDatabasePool()]);
  const shutdownDeadline = new Promise(resolve => setTimeout(resolve, 7000));
  await Promise.race([closeResources, shutdownDeadline]);
  process.exit(0);
}
process.once("SIGTERM", () => {
  void shutdownApplication("SIGTERM");
});
process.once("SIGINT", () => {
  void shutdownApplication("SIGINT");
});
