async function requireAuth(req, res, next) {
  const recoveryUser = getDevRecoverySessionUser(req);
  if (recoveryUser) {
    req.user = recoveryUser;
    next();
    return;
  }
  if (!DATABASE_AVAILABLE) {
    res.status(503).json({
      message: "데이터베이스 연결이 불가능해 인증이 필요한 기능을 사용할 수 없습니다.",
      recoveryMode: true
    });
    return;
  }
  if (!req.session.userId) {
    res.status(401).json({
      code: "AUTH_REQUIRED",
      message: "로그인이 필요합니다."
    });
    return;
  }
  try {
    const user = await runtimeFindUserById(req.session.userId);
    if (!user) {
      req.session.destroy(() => {});
      res.status(401).json({
        code: "AUTH_SESSION_EXPIRED",
        message: "세션이 만료되었습니다."
      });
      return;
    }
    if (user.status !== "approved") {
      req.session.destroy(() => {});
      res.status(403).json({
        message: "관리자 승인 대기 중입니다."
      });
      return;
    }
    const sharingCheck = await evaluateAccountSharingProtection(req, user);
    if (!sharingCheck.allowed) {
      res.status(423).json({
        message: sharingCheck.message,
        accountSharingRestricted: true,
        restrictedUntil: sharingCheck.restrictedUntil
      });
      return;
    }
    if (sharingCheck.warning) {
      res.setHeader("X-Account-Sharing-Warning", "true");
    }
    const termsExemptPaths = new Set(["/api/auth/session", "/api/auth/logout", "/api/terms/current", "/api/terms/agree", "/api/user/marketing-consent"]);
    if (!termsExemptPaths.has(req.path)) {
      const missingTerms = await getMissingRequiredTerms(user);
      if (missingTerms.length) {
        res.status(428).json({
          message: "활성화된 약관에 동의해야 서비스를 이용할 수 있습니다.",
          termsConsentRequired: true,
          missingTerms: missingTerms.map(term => ({
            id: term.id,
            termsKey: term.termsKey,
            title: term.title,
            version: term.version,
            contentHash: term.contentHash
          }))
        });
        return;
      }
    }
    req.user = user;
    await maybeLogSessionActivity(req, user);
    next();
  } catch (error) {
    res.status(500).json({
      message: error.message
    });
  }
}
async function requireAdmin(req, res, next) {
  let authenticated = false;
  await requireAuth(req, res, () => { authenticated = true; });
  if (!authenticated) return;
  try {
    if (!userCanAccessAdminConsole(req.user)) {
      res.status(403).json({
        message: "관리자 권한이 필요합니다."
      });
      return;
    }
    const route = String(req.route?.path || req.path);
    if (!hasAdminPermission(req.user, requiredAdminPermission(req.method, route))) {
      res.status(403).json({ message: "이 작업에 필요한 관리자 권한이 없습니다." });
      return;
    }
    if (!['GET', 'HEAD'].includes(req.method) && route.startsWith('/api/admin/users')) {
      // Preflight all targets before a bulk operation can partially change accounts.
      const ids = req.params?.id ? [req.params.id] : Array.isArray(req.body?.userIds) ? req.body.userIds : [];
      const targets = await Promise.all(ids.map(id => runtimeFindUserById(Number(id))));
      if (!canManageAccount(req.user, null, req.body) || targets.some(target => !canManageAccount(req.user, target, req.body))) {
        res.status(403).json({ message: "관리자 계정과 권한은 전체 관리자만 변경할 수 있습니다." });
        return;
      }
    }
    next();
  } catch (error) { next(error); }
}
function requireCloudConsoleAdmin(req, res, next) {
  Promise.resolve(requireAuth(req, res, () => {
    if (!userHasAdminPermission(req.user, "admin:cloud")) {
      res.status(403).json({
        message: "클라우드 콘솔 관리 권한이 필요합니다."
      });
      return;
    }
    next();
  })).catch(error => res.status(500).json({
    message: error.message
  }));
}
function isAdminUserRole(role) {
  const normalized = String(role || "").trim().toLowerCase();
  return ["admin", "administrator", "관리자"].includes(normalized);
}
const ADMIN_PERMISSION_KEYS = ADMIN_PERMISSIONS;
function parseJsonFallback(value, fallback) {
  if (value == null || value === "") return fallback;
  if (typeof value !== "string") return value;
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}
function normalizeAdminPermissions(value) {
  const source = Array.isArray(value) ? value : parseJsonFallback(value || "[]", []);
  const seen = new Set();
  const result = [];
  for (const item of Array.isArray(source) ? source : []) {
    const key = String(item || "").trim().toLowerCase();
    if (!ADMIN_PERMISSION_KEYS.has(key) || seen.has(key)) continue;
    seen.add(key);
    result.push(key);
  }
  return result.includes("admin:all") ? ["admin:all"] : result;
}
function userHasAdminPermission(user, permission) {
  if (isAdminUserRole(user?.role)) return true;
  const permissions = normalizeAdminPermissions(user?.adminPermissions ?? user?.admin_permissions ?? user?.adminPermissionsJson);
  return permissions.includes("admin:all") || permissions.includes(String(permission || "").trim().toLowerCase());
}
function userCanAccessAdminConsole(user) {
  return userHasAdminPermission(user, "admin:access");
}
function isFullAdminUser(user) {
  return isFullAdministrator(user);
}
function captureConsoleLogs() {
  for (const level of ["log", "info", "warn", "error"]) {
    const original = console[level].bind(console);
    console[level] = (...args) => {
      const message = args.map(item => formatLogItem(item)).join(" ");
      appLogBuffer.push({
        id: randomUUID(),
        level,
        message,
        createdAt: new Date().toISOString()
      });
      if (appLogBuffer.length > APP_LOG_BUFFER_LIMIT) {
        appLogBuffer.splice(0, appLogBuffer.length - APP_LOG_BUFFER_LIMIT);
      }
      original(...args);
    };
  }
}
function formatLogItem(item) {
  if (typeof item === "string") return item;
  return util.inspect(item, {
    depth: 4,
    breakLength: 120,
    compact: true
  });
}
function getRequestIp(req) {
  const forwarded = String(req.headers["x-forwarded-for"] || "").split(",").map(item => item.trim()).filter(Boolean);
  return forwarded[0] || req.ip || req.socket?.remoteAddress || "";
}
function getRequestUserAgent(req) {
  return String(req.headers["user-agent"] || "").trim();
}
