function normalizeMailRecipients(to) {
  if (Array.isArray(to)) {
    return to.map(item => String(item || "").trim()).filter(Boolean);
  }
  return String(to || "").split(/[\n,;]+/).map(item => item.trim()).filter(Boolean);
}
async function resolveAdminMailRecipients({
  to,
  recipientMode = "manual",
  marketingOnly = false
}) {
  const mode = String(recipientMode || "manual").trim() || "manual";
  const directRecipients = normalizeMailRecipients(to);
  const normalizedTokens = new Set([...(mode !== "manual" ? [mode] : []), ...directRecipients].map(item => String(item || "").trim().toUpperCase()).filter(item => item.startsWith("@")));
  const users = await runtimeListUsers();
  const withEmail = users.filter(user => {
    if (!String(user.email || "").trim()) return false;
    return !marketingOnly || user.marketingEmailConsent;
  });
  const resolvedEmails = new Set();
  const resolvedUsernames = new Set();
  let skippedRecipients = 0;
  const addUser = user => {
    const email = String(user?.email || "").trim();
    if (!email) return;
    resolvedEmails.add(email.toLowerCase());
    resolvedUsernames.add(String(user?.username || "").trim());
  };
  if (normalizedTokens.has("@ALL")) {
    withEmail.forEach(addUser);
  }
  if (normalizedTokens.has("@APPROVED")) {
    withEmail.filter(user => user.status === "approved").forEach(addUser);
  }
  if (normalizedTokens.has("@STUDENTS")) {
    withEmail.filter(user => user.role !== "admin").forEach(addUser);
  }
  if (normalizedTokens.has("@ADMINS")) {
    withEmail.filter(user => user.role === "admin").forEach(addUser);
  }
  if (normalizedTokens.has("@ACTIVE")) {
    const logs = await runtimeListUserAccessLogs(5000);
    const cutoff = Date.now() - ACCESS_ACTIVE_WITHIN_MINUTES * 60 * 1000;
    const latestByUser = new Map();
    for (const log of logs) {
      const userId = Number(log?.userId || 0);
      if (!userId) continue;
      const createdAt = new Date(log.createdAt || 0).getTime();
      if (!Number.isFinite(createdAt) || createdAt < cutoff) continue;
      const existing = latestByUser.get(userId);
      if (!existing || createdAt > existing.createdAt) {
        latestByUser.set(userId, {
          createdAt,
          eventType: String(log.eventType || "").trim()
        });
      }
    }
    withEmail.filter(user => {
      const latest = latestByUser.get(Number(user.id || 0));
      return latest && latest.eventType !== "logout";
    }).forEach(addUser);
  }
  for (const rawItem of directRecipients) {
    const item = String(rawItem || "").trim();
    if (!item || item.startsWith("@")) continue;
    if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(item)) {
      if (marketingOnly) {
        const matchedUser = withEmail.find(user => String(user.email || "").trim().toLowerCase() === item.toLowerCase());
        if (matchedUser) {
          addUser(matchedUser);
        } else {
          skippedRecipients += 1;
        }
        continue;
      }
      resolvedEmails.add(item.toLowerCase());
      continue;
    }
    const matchedUser = withEmail.find(user => String(user.username || "").trim().toLowerCase() === item.toLowerCase());
    if (matchedUser) {
      addUser(matchedUser);
    } else if (marketingOnly) {
      skippedRecipients += 1;
    }
  }
  return {
    recipients: Array.from(resolvedEmails),
    matchedUsernames: Array.from(resolvedUsernames),
    tokens: Array.from(normalizedTokens),
    skippedRecipients
  };
}
async function resolveMailCampaignRequestRecipients(body = {}) {
  const purpose = String(body?.purpose || body?.mailPurpose || "operational").trim().toLowerCase() === "marketing" ? "marketing" : "operational";
  const marketingOnly = purpose === "marketing";
  const csvText = String(body?.csvText || "");
  const csv = csvText.trim() ? parseMailRecipientCsv(csvText) : {
    recipients: [],
    invalidRows: [],
    duplicateCount: 0,
    sourceHash: ""
  };
  if (marketingOnly && csv.recipients.length && body?.externalConsentConfirmed !== true) {
    throw createHttpError(400, "외부 CSV 마케팅 대상의 사전 수신 동의를 확인해 주세요.");
  }
  const requestedModes = Array.from(new Set((Array.isArray(body?.recipientModes) ? body.recipientModes : []).map(item => String(item || "").trim().toUpperCase()).filter(item => ["@ALL", "@APPROVED", "@STUDENTS", "@ADMINS", "@ACTIVE"].includes(item))));
  const users = await runtimeListUsers();
  const usersByEmail = new Map(users.map(user => [String(user.email || "").trim().toLowerCase(), user]));
  const memberRecipients = [];
  for (const mode of requestedModes) {
    const resolved = await resolveAdminMailRecipients({
      recipientMode: mode,
      marketingOnly
    });
    for (const email of resolved.recipients) {
      const user = usersByEmail.get(String(email || "").trim().toLowerCase());
      memberRecipients.push({
        email,
        recipientName: String(user?.name || user?.username || "").trim(),
        companyName: "",
        userId: user?.id || null,
        source: `member:${mode}`,
        metadata: {
          username: user?.username || "",
          memberMode: mode
        }
      });
    }
  }
  const manual = await resolveAdminMailRecipients({
    to: body?.manualRecipients || body?.to || "",
    recipientMode: "manual",
    marketingOnly
  });
  const manualRecipients = manual.recipients.map(email => {
    const user = usersByEmail.get(String(email || "").trim().toLowerCase());
    return {
      email,
      recipientName: String(user?.name || user?.username || "").trim(),
      userId: user?.id || null,
      source: user ? "member:manual" : "manual",
      metadata: {
        username: user?.username || ""
      }
    };
  });
  const csvRecipients = csv.recipients.map(recipient => ({
    ...recipient,
    metadata: {
      sourceRowNumber: recipient.sourceRowNumber,
      externalConsentConfirmed: marketingOnly ? true : undefined
    }
  }));
  const merged = mergeMailCampaignRecipients(csvRecipients, memberRecipients, manualRecipients);
  if (merged.recipients.length > MAIL_CAMPAIGN_MAX_RECIPIENTS) {
    throw createHttpError(400, `캠페인 수신자는 최대 ${MAIL_CAMPAIGN_MAX_RECIPIENTS.toLocaleString("ko-KR")}명까지 처리할 수 있습니다.`);
  }
  return {
    purpose,
    recipients: merged.recipients,
    recipientModes: requestedModes,
    invalidRows: csv.invalidRows,
    csvRecipientCount: csv.recipients.length,
    memberRecipientCount: memberRecipients.length,
    manualRecipientCount: manualRecipients.length,
    duplicateCount: csv.duplicateCount + merged.duplicateCount,
    skippedRecipients: manual.skippedRecipients,
    sourceHash: csv.sourceHash
  };
}
