  const cpuCount = Math.max(1, Number(vcpus || 0) || 1);
  if (items.length < 2) return 0;
  const sorted = [...items].sort((a, b) => String(a?.[0] || "").localeCompare(String(b?.[0] || "")));
  const previous = sorted.at(-2);
