      if (!stackId) {
        const resolved = await resolveHeatStack({
          stackName,
          projectName: target.projectName
        });
        stackId = resolved?.stackId || "";
      }
      if (!stackId) {
        throw new Error("Stack ID를 확인하지 못했습니다.");
      }
