  if (explicitNodes.length <= 1) return true;
  const selectedIp = getLabNodeFixedIp(selectedNode);
  const labIp = String(lab?.instanceIp || lab?.instance_ip || "").trim();
  return Boolean(selectedIp && labIp && selectedIp === labIp);
