  const normalizedNodeId = String(preferredNodeId || "").trim();
  const normalizedHost = String(preferredHost || "").trim();
  const nodes = deriveTerminalNodes(lab);
  const matchedNode = normalizedNodeId ? nodes.find(node => String(node.id || "").trim() === normalizedNodeId) : normalizedHost ? nodes.find(node => [node.fixedIp, node.floatingIp].filter(Boolean).includes(normalizedHost)) : null;
  if (matchedNode?.fixedIp) {
    return {
      type: "fixed",
      address: matchedNode.fixedIp,
      nodeId: matchedNode.id,
      nodeName: matchedNode.name
    };
  }
  if (matchedNode?.floatingIp) {
    return {
      type: "floating",
      address: matchedNode.floatingIp,
      nodeId: matchedNode.id,
      nodeName: matchedNode.name
    };
  }
  const items = Array.isArray(lab.instanceIps) ? lab.instanceIps : [];
  const defaultTarget = items.find(item => item.type === "fixed") ?? items.find(item => item.type === "floating") ?? (lab.instanceIp ? {
    type: "fixed",
    address: lab.instanceIp
  } : null);
  if (!defaultTarget) return null;
  const defaultNode = nodes.find(node => [node.fixedIp, node.floatingIp].filter(Boolean).includes(String(defaultTarget.address || "").trim())) || nodes[0] || null;
