  if (terminalSession.jumpHost) {
    const jumpTarget = terminalSession.jumpUser ? `${terminalSession.jumpUser}@${terminalSession.jumpHost}` : terminalSession.jumpHost;
    args.push("-J", jumpTarget);
  }
  args.push(`${terminalSession.username}@${terminalSession.host}`);
