async function parseLabInstanceUpload(req) {
  const contentType = String(req.headers["content-type"] || "").toLowerCase();
  if (!contentType.includes("multipart/form-data")) {
    throw createHttpError(400, "multipart/form-data 형식의 파일 업로드만 지원합니다.");
  }
  const maxBytes = LAB_FILE_UPLOAD_MAX_MB * 1024 * 1024;
  const contentLength = Number(req.headers["content-length"] || 0);
  if (Number.isFinite(contentLength) && contentLength > maxBytes + 1024 * 1024) {
    throw createHttpError(413, `업로드 파일이 너무 큽니다. ${LAB_FILE_UPLOAD_MAX_MB}MB 이하 파일만 업로드할 수 있습니다.`);
  }
  const request = new Request("http://localhost/internal-lab-upload", {
    method: req.method,
    headers: req.headers,
    body: req,
    duplex: "half"
  });
  const formData = await request.formData();
  const uploadedFile = formData.get("file");
  if (!(uploadedFile instanceof File)) {
    throw createHttpError(400, "업로드할 파일을 선택해 주세요.");
  }
  if (!uploadedFile.name) {
    throw createHttpError(400, "유효한 파일명이 필요합니다.");
  }
  if (uploadedFile.size > maxBytes) {
    throw createHttpError(413, `업로드 파일이 너무 큽니다. ${LAB_FILE_UPLOAD_MAX_MB}MB 이하 파일만 업로드할 수 있습니다.`);
  }
  const safeFileName = romanizeFileName(uploadedFile.name, "upload");
  if (!safeFileName) {
    throw createHttpError(400, "안전한 파일명만 업로드할 수 있습니다.");
  }
  return {
    file: uploadedFile,
    fileName: safeFileName,
    nodeId: String(formData.get("nodeId") || "").trim(),
    targetHost: String(formData.get("targetHost") || "").trim()
  };
}
async function uploadFileToLabInstance(terminalSession, fileName, file) {
  const tempPath = path.join(os.tmpdir(), `terminal-lab-upload-${randomUUID()}-${fileName}`);
  await fs.mkdir(os.tmpdir(), {
    recursive: true
  }).catch(() => {});
  await pipeline(Readable.fromWeb(file.stream()), fsSync.createWriteStream(tempPath));
  try {
    const fileBase64 = await fs.readFile(tempPath, "base64");
    const remoteDir = "~/uploads";
    const remotePath = `${remoteDir}/${fileName}`;
    const uploadScript = ["set -euo pipefail", 'mkdir -p "$HOME/uploads"', `TARGET_FILE="$HOME/uploads/${fileName}"`, "cat <<'__TLB64__' | base64 -d > \"$TARGET_FILE\"", fileBase64, "__TLB64__", "printf '%s\\n' \"$TARGET_FILE\"", "exit"].join("\n");
    await new Promise((resolve, reject) => {
      const ssh = pty.spawn(SSH_COMMAND, [...buildSshArgs(terminalSession), "bash", "-s"], {
        name: "xterm-color",
        cols: 120,
        rows: 32,
        cwd: process.cwd(),
        env: process.env
      });
      let settled = false;
      let passwordSent = false;
      let hostKeyAccepted = false;
      let scriptSent = false;
      let output = "";
      const timeout = setTimeout(() => {
        if (settled) return;
        settled = true;
        ssh.kill("SIGTERM");
        reject(new Error("파일 업로드 시간이 초과되었습니다."));
      }, 120000);
      const safeWrite = value => {
        try {
          ssh.write(value);
          return true;
        } catch {
          return false;
        }
      };
      const sendScript = () => {
        if (scriptSent || settled) return;
        scriptSent = true;
        if (!safeWrite(`${uploadScript}\n`)) {
          settled = true;
          clearTimeout(timeout);
          try {
            ssh.kill();
          } catch {}
          reject(new Error("파일 업로드용 SSH 입력 스트림이 이미 종료되었습니다."));
          return;
        }
      };
      const handleChunk = chunk => {
        const data = String(chunk || "");
        output += data;
        if (!hostKeyAccepted && /(are you sure you want to continue connecting|yes\/no\/\[fingerprint\]\?)/i.test(output) && ["accept-new", "no"].includes(String(SSH_STRICT_HOST_KEY_CHECKING || "").toLowerCase())) {
          safeWrite("yes\n");
          hostKeyAccepted = true;
        }
        if (!passwordSent && terminalSession.password && /password:/i.test(output)) {
          safeWrite(`${terminalSession.password}\n`);
          passwordSent = true;
          sendScript();
        }
      };
      ssh.onData(handleChunk);
      ssh.on("error", error => {
        if (error?.code === "EIO") {
          return;
        }
        clearTimeout(timeout);
        if (settled) return;
        settled = true;
        reject(error);
      });
      ssh.onExit(({
        exitCode
      }) => {
        clearTimeout(timeout);
        if (settled) return;
        settled = true;
        if (exitCode === 0) resolve();else reject(new Error(`파일 업로드에 실패했습니다.${output ? ` (${output.trim()})` : ""}`));
      });
      if (!terminalSession.password) {
        sendScript();
      }
    });
  } finally {
    await fs.unlink(tempPath).catch(() => {});
  }
  return {
    remoteDir: "~/uploads"
  };
}
async function listHeatTemplates() {
  await fs.mkdir(HEAT_TEMPLATES_DIR, {
    recursive: true
  });
  const entries = await fs.readdir(HEAT_TEMPLATES_DIR, {
    withFileTypes: true
  });
  const courses = await runtimeListCourses();
  const templates = [];
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (!entry.name.toLowerCase().endsWith(".yaml") && !entry.name.toLowerCase().endsWith(".yml")) continue;
    const filePath = path.join(HEAT_TEMPLATES_DIR, entry.name);
    const content = await fs.readFile(filePath, "utf8");
    const stats = await fs.stat(filePath);
    const usedBy = courses.filter(course => String(course.heatTemplateName || "").trim() === entry.name).map(course => course.title);
    templates.push({
      name: entry.name,
      content,
      updatedAt: stats.mtime.toISOString(),
      inUseCount: usedBy.length,
      usedByTitles: usedBy
    });
  }
  templates.sort((a, b) => a.name.localeCompare(b.name));
  return templates;
}
async function getHeatTemplateInstanceCountSupport(templateName) {
  const fileName = normalizeTemplateFileName(templateName);
  const candidatePaths = [path.join(HEAT_TEMPLATES_DIR, fileName), path.join(LEGACY_HEAT_TEMPLATES_DIR, fileName)];
  for (const filePath of candidatePaths) {
    if (!(await pathExists(filePath))) continue;
    const content = await fs.readFile(filePath, "utf8");
    const template = YAML.parse(content);
    const parameters = template && typeof template === "object" && template.parameters && typeof template.parameters === "object" ? template.parameters : {};
    return {
      supported: Object.prototype.hasOwnProperty.call(parameters, "instance_count"),
      fileName
    };
  }
  return {
    supported: false,
    fileName
  };
}
async function listApplicationYamls() {
  await fs.mkdir(APPLICATION_YAMLS_DIR, {
    recursive: true
  });
  const [entries, customLabRequests, arenaScenarios] = await Promise.all([fs.readdir(APPLICATION_YAMLS_DIR, {
    withFileTypes: true
  }), runtimeListCustomLabRequests().catch(() => []), runtimeListArenaScenarios().catch(() => [])]);
  const usageByName = new Map();
  const addUsage = (name, label) => {
    const normalizedName = normalizeTemplateFileName(name);
    const normalizedLabel = String(label || "").trim();
    if (!normalizedName || !normalizedLabel) return;
    const current = usageByName.get(normalizedName) || [];
    if (!current.includes(normalizedLabel)) current.push(normalizedLabel);
    usageByName.set(normalizedName, current);
  };
  const activeCustomLabStatuses = new Set(["requested", "quoted", "confirmed", "approved", "provisioning", "running", "failed"]);
  for (const request of Array.isArray(customLabRequests) ? customLabRequests : []) {
    const status = String(request.status || "").trim().toLowerCase();
    if (!activeCustomLabStatuses.has(status)) continue;
    addUsage(request.applicationYamlName, `연구실/랩 신청 #${request.id}${request.title ? ` · ${request.title}` : ""}`);
  }
  for (const scenario of Array.isArray(arenaScenarios) ? arenaScenarios : []) {
    addUsage(scenario.metadata?.applicationYamlName, `아레나 시나리오 · ${scenario.title || scenario.code || scenario.id}`);
  }
  const items = [];
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (!entry.name.toLowerCase().endsWith(".yaml") && !entry.name.toLowerCase().endsWith(".yml")) continue;
    if (entry.name.toLowerCase().endsWith(".meta.json")) continue;
    const filePath = path.join(APPLICATION_YAMLS_DIR, entry.name);
    const content = await fs.readFile(filePath, "utf8");
    const stats = await fs.stat(filePath);
    const meta = await readApplicationYamlMeta(entry.name);
    const usedBy = usageByName.get(entry.name) || [];
    items.push({
      name: entry.name,
      content,
      category: meta.category || "basic",
      description: meta.description || "",
      validationError: getApplicationYamlValidationError(entry.name, content),
      updatedAt: stats.mtime.toISOString(),
      inUseCount: usedBy.length,
      usedByTitles: usedBy
    });
  }
  items.sort((a, b) => a.name.localeCompare(b.name));
  return items;
}
