async function readApplicationYamlMeta(name) {
  try {
    const raw = await fs.readFile(getApplicationYamlMetaPath(name), "utf8");
    const parsed = JSON.parse(raw);
    return {
      category: normalizeApplicationYamlCategory(parsed?.category),
      description: String(parsed?.description || "").trim()
    };
  } catch {
    return {
      category: "basic",
      description: ""
    };
  }
}
function getApplicationYamlMetaPath(name) {
  return path.join(APPLICATION_YAMLS_DIR, `${name}.meta.json`);
}
function normalizeTemplateFileName(name) {
  const trimmed = String(name || "").trim().replace(/[\\/]/g, "");
  if (!trimmed) return "";
  return /\.(yaml|yml)$/i.test(trimmed) ? trimmed : `${trimmed}.yaml`;
}
function normalizeApplicationYamlCategory(value) {
  return String(value || "").trim().toLowerCase() === "exception" ? "exception" : "basic";
}
function getApplicationYamlValidationError(name, content) {
  const normalizedName = String(name || "").trim().toLowerCase();
  if (normalizedName === "clouds.yaml" || normalizedName === "clouds.yml") {
    return "OpenStack 인증 파일(clouds.yaml)은 Application YAML로 등록할 수 없습니다.";
  }
  try {
    const docs = YAML.parseAllDocuments(String(content || ""));
    const parseErrors = docs.flatMap(doc => doc.errors || []);
    if (parseErrors.length) {
      return "유효한 YAML 형식이 아닙니다. 문법을 확인해 주세요.";
    }
  } catch {
    return "유효한 YAML 형식이 아닙니다. 문법을 확인해 주세요.";
  }
  return "";
}



