function normalizeWrittenExamInput(raw) {
  const title = String(raw?.title || "").trim();
  const description = String(raw?.description || "").trim();
  const passScore = Math.max(1, Number(raw?.passScore || 60));
  const inputQuestions = Array.isArray(raw?.questions) ? raw.questions : [];
  const accessPolicy = normalizeExamAccessPolicy(raw?.accessPolicy);
  if (!title) return {
    error: "시험 제목을 입력해 주세요."
  };
  if (!inputQuestions.length) return {
    error: "문항을 1개 이상 등록해 주세요."
  };
  if (accessPolicy.mode === "required_courses" && !accessPolicy.requiredCourseIds.length) return {
    error: "지정 과정 구매 정책에는 필수 과정을 1개 이상 선택해 주세요."
  };
  const questions = [];
  for (let index = 0; index < inputQuestions.length; index += 1) {
    const item = inputQuestions[index] || {};
    const type = String(item.type || "").trim();
    const questionText = String(item.questionText || "").trim();
    const answerText = String(item.answerText || "").trim();
    const points = Math.max(1, Number(item.points || 10));
    if (!["multiple_choice", "short_answer"].includes(type)) {
      return {
        error: `${index + 1}번 문항 유형이 올바르지 않습니다.`
      };
    }
    if (!questionText || !answerText) {
      return {
        error: `${index + 1}번 문항의 질문과 정답을 입력해 주세요.`
      };
    }
    const choices = type === "multiple_choice" ? (Array.isArray(item.choices) ? item.choices : []).map(choice => String(choice || "").trim()).filter(Boolean) : [];
    if (type === "multiple_choice" && choices.length < 2) {
      return {
        error: `${index + 1}번 객관식 문항의 보기 2개 이상을 입력해 주세요.`
      };
    }
    questions.push({
      id: String(item.id || `q${index + 1}`).trim() || `q${index + 1}`,
      type,
      questionText,
      choices,
      answerText,
      points
    });
  }
  return {
    value: {
      title,
      description,
      passScore,
      questions,
      accessPolicy
    }
  };
}
function gradeWrittenExam(exam, answers) {
  const results = exam.questions.map(question => {
    const answer = String(answers?.[question.id] || "").trim();
    const normalizedAnswer = normalizeExamAnswer(answer);
    const normalizedExpected = normalizeExamAnswer(question.answerText);
    const correct = normalizedAnswer === normalizedExpected;
    return {
      questionId: question.id,
      answer,
      correct,
      awardedPoints: correct ? question.points : 0,
      points: question.points
    };
  });
  const score = results.reduce((sum, item) => sum + item.awardedPoints, 0);
  const totalPoints = results.reduce((sum, item) => sum + item.points, 0);
  const passed = score >= Number(exam.passScore || 0);
  return {
    score,
    totalPoints,
    passed,
    results
  };
}
function normalizeExamAnswer(value) {
  return String(value || "").trim().replace(/\s+/g, " ").toLowerCase();
}
