    LAB_COURSE_TITLE: course?.title || exam?.courseTitle || "",
    LAB_ID: String(lab?.id || ""),
    LAB_STATUS: lab?.status || "",
    LAB_USER: username || "",
    LAB_PASSWORD: password || "",
    LAB_PRIMARY_HOST: targetHost?.address || "",
    LAB_PRIMARY_NODE_ID: targetHost?.nodeId || "",
