async function markPaymentPaid(payment, {
  paymentKey = "",
  providerOrderId = "",
  reviewedBy = null,
  metadata = null
} = {}) {
  const couponId = Number(metadata?.couponId || payment?.metadata?.couponId || 0);
  const coupon = couponId > 0 ? await runtimeFindDiscountCouponById(couponId) : null;
  const updated = await runtimeUpdatePayment(payment.id, {
    status: "paid",
    paymentKey: String(paymentKey || "").trim() || payment.paymentKey || "",
    providerOrderId: String(providerOrderId || "").trim() || payment.providerOrderId || "",
    paidAt: new Date().toISOString(),
    reviewedBy: reviewedBy ?? payment.reviewedBy ?? null,
    metadata: metadata ?? payment.metadata ?? {}
  });
  if (couponId > 0) {
    await runtimeConsumeDiscountCoupon(couponId);
  }
  const course = await runtimeFindCourseById(payment.courseId);
  const courseAccessSource = String(course?.courseType || "") === "package" ? `package:${payment.courseId}:${payment.id}` : "payment";
  await runtimeGrantUserCourseAccess(payment.userId, payment.courseId, courseAccessSource);
  const examEntitlementExpiresAt = await resolvePurchasedExamEntitlementExpiry(payment.courseId);
  await runtimeGrantExamEntitlement({
    userId: payment.userId,
    examCourseId: payment.courseId,
    source: classifyPaidPaymentEntitlementSource({
      ...payment,
      metadata: metadata ?? payment.metadata ?? {}
    }),
    sourcePaymentId: payment.id,
    expiresAt: examEntitlementExpiresAt,
    grantedBy: reviewedBy,
    metadata: {
      orderId: payment.orderId,
      amount: payment.amount
    }
  });
  await grantPackageContents({
    userId: payment.userId,
    packageCourse: course,
    sourcePaymentId: payment.id,
    source: classifyPaidPaymentEntitlementSource({
      ...payment,
      metadata: metadata ?? payment.metadata ?? {}
    }),
    grantedBy: reviewedBy
  });
  const user = await runtimeFindUserById(payment.userId);
  if (user?.email) {
    const paymentPaidMail = buildPaymentPaidMail({
      name: user.name,
      courseTitle: course?.title || "",
      formattedAmount: formatCurrency(payment.amount)
    });
    sendMailNotification({
      type: "payment_paid",
      to: user.email,
      subject: paymentPaidMail.subject,
      text: paymentPaidMail.text,
      templateKey: paymentPaidMail.templateKey,
      templateVariables: paymentPaidMail.templateVariables,
      metadata: {
        paymentId: payment.id,
        courseId: payment.courseId,
        userId: payment.userId
      }
    }).catch(error => {
      console.warn("[mail] payment success mail failed", {
        paymentId: payment.id,
        message: error.message
      });
    });
  }
  if (user) {
    await createUserNotification({
      userId: user.id,
      type: "payment_paid",
      title: "결제가 완료되었습니다",
      body: course?.title ? `${course.title} 과정을 바로 이용할 수 있습니다.` : "결제가 완료되어 과정 이용이 가능합니다.",
      linkSection: "courses",
      metadata: {
        paymentId: payment.id,
        courseId: payment.courseId
      }
    });
  }
  if (couponId > 0 && coupon) {
    const supportRecipients = resolveSupportRecipients(await runtimeListUsers());
    await Promise.all(supportRecipients.map(recipient => createUserNotification({
      userId: recipient.id,
      type: "coupon_redeemed",
      title: "쿠폰이 사용되었습니다",
      body: `${user?.name || user?.username || "사용자"}님이 ${coupon.code} 쿠폰을 사용해 ${course?.title || "과정"} 결제를 완료했습니다.`,
      linkSection: "luckyDrawAdmin",
      metadata: {
        couponId: coupon.id,
        couponCode: coupon.code,
        paymentId: payment.id,
        userId: payment.userId,
        courseId: payment.courseId,
        source: "coupon_redeemed"
      }
    })));
  }
  return updated;
}
