    lab: labItems.length,
    selfServiceVm: selfServiceItems.length,
    running: items.filter(item => item.status === "running").length,
    paused: items.filter(item => ["paused", "stopped"].includes(item.status)).length,
    danger: items.filter(item => item.risk.level === "danger").length,
    warn: items.filter(item => item.risk.level === "warn").length,
    metricsSupported: items.filter(item => item.metrics.supported).length,
    metricsWaiting: items.filter(item => item.metrics.supported && !item.metrics.checkedAt).length,
    collectionOk: items.filter(item => item.metrics.collection?.level === "ok").length,
    collectionPartial: items.filter(item => item.metrics.collection?.level === "partial").length,
    collectionStale: items.filter(item => item.metrics.collection?.level === "stale").length,
