async function probeZunStatus(settings) {
  if (!settings.zunEnabled && !settings.zunApiUrl) {
    return {
      ok: false,
      configured: Boolean(settings.zunApiUrl),
      enabled: false,
      message: "Zun 기능이 비활성 상태입니다."
    };
  }
  if (!settings.zunApiUrl) {
    return {
      ok: false,
      configured: false,
      enabled: true,
      message: "Zun API URL이 설정되지 않았습니다."
    };
  }
  try {
    const result = await probeZunApi({
      apiUrl: settings.zunApiUrl,
      projectName: getZunProjectName(settings),
      timeoutMs: OPENSTACK_PROBE_TIMEOUT_MS
    });
    const imageChecks = await Promise.all(getZunAllowedImages(settings).map(imageName => checkContainerRegistryImageAvailability(imageName, settings)));
    const unavailableImages = imageChecks.filter(item => !item.ok).map(item => item.imageName);
    return {
      ok: unavailableImages.length === 0,
      configured: true,
      enabled: true,
      endpoint: settings.zunApiUrl,
      projectName: getZunProjectName(settings),
      latencyMs: result.latencyMs,
      sampleCount: result.sampleCount,
      imageCount: imageChecks.length,
      unavailableImages,
      message: unavailableImages.length ? `내부 Registry에서 ${unavailableImages.length}개 허용 이미지를 확인할 수 없습니다.` : "Zun API와 허용 이미지를 확인했습니다."
    };
  } catch (error) {
    const message = String(error.message || "");
    const serviceKeystoneMatch = message.match(/https?:\/\/keystone\.[^\s/)"']+/i);
    return {
      ok: false,
      configured: true,
      enabled: true,
      endpoint: settings.zunApiUrl,
      message: error.message,
      openstackCaStatus: error.openstackCaStatus || getOpenstackCaStatus()
    };
  }
}
