  result.pocCloudsYamlEffectivePath = result.pocCloudsYamlReadable ? pocCloudsYamlPath : result.serviceCloudsYamlReadable ? serviceCloudsYamlPath : result.cloudsYamlReadable ? OPENSTACK_CLOUDS_YAML_PATH : "";
  result.serviceCloudsYamlFallbackUsed = Boolean(result.serviceCloudsYamlEffectivePath && result.serviceCloudsYamlEffectivePath !== serviceCloudsYamlPath);
  result.pocCloudsYamlFallbackUsed = Boolean(result.pocCloudsYamlEffectivePath && result.pocCloudsYamlEffectivePath !== pocCloudsYamlPath);
