async function probeQuotaStatus(settings = null, {
  maxCacheAgeMs = null,
  projectName: requestedProjectName = ""
} = {}) {
  const trendDays = 5;
  const effectiveSettings = settings || (await runtimeGetPlatformStatus());
  const projectName = String(requestedProjectName || getServiceProjectName(effectiveSettings)).trim();
  if (!areOpenstackStatusProbesEnabled(effectiveSettings)) {
    return {
      ...buildDisabledOpenstackStatus("OpenStack Quota 조회"),
      projectName,
      metrics: null,
      usageTrend: {
        days: trendDays,
        resources: [],
        message: "OpenStack 상태 조회가 일시 중지되어 사용량 추이를 수집하지 않습니다."
      }
    };
  }
  try {
    const cacheKey = projectName || "__default__";
    const cached = quotaStatusCache.get(cacheKey);
    const configuredCacheTtlMs = resolveOpenstackStatusCacheTtlMs(effectiveSettings);
    const requestedMaxCacheAgeMs = Number(maxCacheAgeMs);
    const cacheTtlMs = Number.isFinite(requestedMaxCacheAgeMs) && requestedMaxCacheAgeMs >= 0 ? Math.min(configuredCacheTtlMs, requestedMaxCacheAgeMs) : configuredCacheTtlMs;
    const now = Date.now();
    if (cached?.payload && now - cached.checkedAt < cacheTtlMs) {
      return cached.payload;
    }
    if (cached?.pending) {
      return await cached.pending;
    }
    const pending = (async () => {
      const quota = await probeOpenstackQuota({
        projectName
      });
      const collectedAt = new Date().toISOString();
      const payload = {
        ...quota,
        ok: true,
        collectedAt
      };
      try {
        await runtimeRecordOpenstackResourceUsageSnapshot({
          projectName: payload.projectName || projectName,
          driver: payload.driver || "",
          metrics: payload.metrics || {},
          collectedAt
        });
        payload.usageTrend = await runtimeListOpenstackResourceUsageTrend({
          projectName: payload.projectName || projectName,
          days: trendDays,
          pointsPerResource: QUOTA_STATUS_TREND_POINTS_PER_RESOURCE
        });
      } catch (trendError) {
        payload.usageTrend = {
          days: trendDays,
          resources: [],
          message: trendError.message || "OpenStack 자원 사용량 추이를 저장하지 못했습니다."
        };
      }
      quotaStatusCache.set(cacheKey, {
        checkedAt: Date.now(),
        payload
      });
      return payload;
    })();
    quotaStatusCache.set(cacheKey, {
      checkedAt: cached?.checkedAt || 0,
      payload: cached?.payload || null,
      pending
    });
    try {
      return await pending;
    } catch (error) {
      if (cached?.payload) {
        return {
          ...cached.payload,
          stale: true,
          message: sanitizeOpenstackErrorMessage(error),
          detailMessage: error.message
        };
      }
      throw error;
    } finally {
      const latest = quotaStatusCache.get(cacheKey);
      if (latest?.pending === pending) {
        quotaStatusCache.set(cacheKey, {
          checkedAt: latest.checkedAt || cached?.checkedAt || 0,
          payload: latest.payload || cached?.payload || null
        });
      }
    }
  } catch (error) {
    return {
      ok: false,
      message: sanitizeOpenstackErrorMessage(error),
      detailMessage: error.message,
      metrics: null,
      usageTrend: {
        days: trendDays,
        resources: []
      }
    };
  }
}
let labAutoCircuitBreakerUpdatePromise = null;
function buildCurrentLabCircuitBreakerStatus(settings = {}) {
  return {
    blocked: Boolean(settings.labCircuitBreaker),
    source: String(settings.labCircuitBreakerSource || (settings.labCircuitBreaker ? "manual" : "")).trim(),
    message: String(settings.labCircuitBreakerMessage || "현재 랩 생성이 잠시 제한되어 있습니다.").trim(),
    triggeredAt: String(settings.labCircuitBreakerTriggeredAt || "").trim(),
    metric: String(settings.labCircuitBreakerMetric || "").trim(),
    usagePercent: Math.max(0, Math.min(100, Number(settings.labCircuitBreakerUsagePercent || 0) || 0)),
    autoEnabled: settings.labAutoCircuitBreakerEnabled !== false,
    thresholdPercent: normalizeLabQuotaCircuitBreakerThreshold(settings.labAutoCircuitBreakerThresholdPercent)
  };
}
async function resolveLabCreationCircuitBreaker(settings = null, {
  quota = null,
  projectName = ""
} = {}) {
  const effectiveSettings = settings || (await runtimeGetPlatformStatus());
  const current = buildCurrentLabCircuitBreakerStatus(effectiveSettings);
  if (current.blocked || !current.autoEnabled) return current;
  const quotaStatus = quota || (await probeQuotaStatus(effectiveSettings, {
    maxCacheAgeMs: 30_000,
    projectName
  }));
  const evaluation = evaluateLabQuotaCircuitBreaker(quotaStatus, current.thresholdPercent);
  if (["quota-unavailable", "quota-metrics-unavailable"].includes(evaluation.reason)) {
    return {
      ...current,
      blocked: false,
      source: "quota-unavailable",
      message: "OpenStack Quota를 일시적으로 확인하지 못했습니다. 마지막 정상 상태가 없으므로 자동 차단은 적용하지 않았습니다.",
      warning: true,
      evaluation
    };
  }
  if (!evaluation.tripped) {
    return {
      ...current,
      evaluation
    };
  }
  const message = buildLabQuotaCircuitBreakerMessage(evaluation);
  if (!labAutoCircuitBreakerUpdatePromise) {
    labAutoCircuitBreakerUpdatePromise = (async () => {
      const latestSettings = await runtimeGetPlatformStatus();
      if (latestSettings.labCircuitBreaker) return latestSettings;
      if (latestSettings.labAutoCircuitBreakerEnabled === false) return latestSettings;
      const updated = await runtimeUpdatePlatformStatus({
        ...latestSettings,
        labCircuitBreaker: true,
        labCircuitBreakerMessage: message,
        labCircuitBreakerSource: "quota",
        labCircuitBreakerTriggeredAt: new Date().toISOString(),
        labCircuitBreakerMetric: evaluation.metricKey,
        labCircuitBreakerUsagePercent: evaluation.percent
      });
      invalidatePlatformStatusCache();
      broadcastPortalEvent("platform-status-updated", {
        reason: "quota-circuit-breaker",
        metric: evaluation.metricKey,
        usagePercent: evaluation.percent,
        thresholdPercent: evaluation.thresholdPercent
      });
      console.warn("[quota-circuit-breaker] lab creation blocked", {
        projectName: quotaStatus?.projectName || getServiceProjectName(effectiveSettings),
        metric: evaluation.metricKey,
        usagePercent: evaluation.percent,
        thresholdPercent: evaluation.thresholdPercent
      });
      return updated;
    })().finally(() => {
      labAutoCircuitBreakerUpdatePromise = null;
    });
  }
  const updatedSettings = await labAutoCircuitBreakerUpdatePromise;
  const finalStatus = buildCurrentLabCircuitBreakerStatus(updatedSettings);
  if (!finalStatus.blocked) {
    return {
      ...finalStatus,
      evaluation
    };
  }
  return {
    ...finalStatus,
    blocked: true,
    source: String(updatedSettings?.labCircuitBreakerSource || "quota").trim() || "quota",
    message: String(updatedSettings?.labCircuitBreakerMessage || message).trim() || message,
    evaluation
  };
}
function sanitizeOpenstackErrorMessage(error) {
  const raw = String(error?.message || "").trim();
  const body = String(error?.body || "").trim();
  let detail = "";
  try {
    const parsed = JSON.parse(body);
    detail = String(parsed?.NeutronError?.message || parsed?.error?.message || parsed?.badRequest?.message || parsed?.conflictingRequest?.message || "").trim();
  } catch {}
  const safeDetail = detail.replace(/[\r\n]+/g, " ").slice(0, 300);
  if (isCloudConsoleQuotaExceeded(error)) return "프로젝트 자원 한도를 초과했습니다. 쿼터 자동 보정 후에도 실패했습니다. 관리자에게 프로젝트 쿼터를 확인해 달라고 요청해 주세요.";
  if (/Floating IP는 관리자가 허용한 경우/i.test(raw)) return raw;
  if (Number(error?.statusCode || error?.status || 0) === 403 && !/^OpenStack API request failed/i.test(raw)) return raw.replace(/[\r\n]+/g, " ").slice(0, 300);
  if (Number(error?.statusCode || error?.status || 0) === 403) return "현재 프로젝트에서 해당 OpenStack 작업을 수행할 권한이 없습니다. 관리자에게 서비스 계정과 프로젝트 역할을 확인해 달라고 요청해 주세요.";
  if (Number(error?.statusCode || error?.status || 0) === 409 && safeDetail) return "OpenStack 자원 충돌: " + safeDetail;
  if (Number(error?.statusCode || error?.status || 0) === 400 && safeDetail) return "OpenStack 요청 오류: " + safeDetail;
  const status = Number(error?.statusCode || error?.status || 0);
  if (status >= 400 && status < 500 && raw) return raw.replace(/[\r\n]+/g, " ").slice(0, 300);
  if (!raw) {
    return "현재 OpenStack 자원 상태를 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.";
  }
  if (/401|unauthorized|authentication failed|keystone/i.test(raw)) {
    return "현재 OpenStack 인증 상태를 확인하지 못했습니다. 관리자에게 문의해 주세요.";
  }
  if (/timeout|timed out|ECONNREFUSED|ENOTFOUND|network/i.test(raw)) {
    return "현재 OpenStack 자원 상태 조회가 지연되거나 연결되지 않습니다. 잠시 후 다시 시도해 주세요.";
  }
  return "현재 OpenStack 자원 상태를 확인하지 못했습니다. 관리자에게 문의해 주세요.";
}
async function touchLab(labId) {
  const now = Date.now();
  await runtimeTouchLabRequest(labId, {
    lastAccessedAt: new Date(now).toISOString(),
    expiresAt: new Date(now + LAB_IDLE_TIMEOUT_MS).toISOString()
  });
}
function getLabLastUsedTimeMs(lab) {
  const candidates = [lab?.lastAccessedAt, lab?.startedAt, lab?.approvedAt, lab?.createdAt];
  for (const value of candidates) {
    const time = value ? new Date(value).getTime() : NaN;
    if (Number.isFinite(time) && time > 0) return time;
  }
  return 0;
}
const internalImageCacheWarmupTimer = setTimeout(() => {
  if (DATABASE_AVAILABLE) {
    void scheduleInternalImageCacheRefresh();
  }
}, 30000);
if (typeof internalImageCacheWarmupTimer.unref === "function") internalImageCacheWarmupTimer.unref();
setInterval(async () => {
  if (DATABASE_AVAILABLE) {
    void scheduleInternalImageCacheRefresh();
  }
}, INTERNAL_IMAGE_CACHE_REFRESH_INTERVAL_MS);
setInterval(async () => {
  const now = Date.now();
  let terminalSessionIdleTimeoutMs = TERMINAL_SESSION_IDLE_TIMEOUT_MS;
  if (DATABASE_AVAILABLE) {
    try {
      terminalSessionIdleTimeoutMs = resolveTerminalSessionIdleTimeoutMs(await runtimeGetPlatformStatus());
      await runtimeDeleteExpiredTerminalSessionRegistry(new Date(now).toISOString());
    } catch {
      terminalSessionIdleTimeoutMs = TERMINAL_SESSION_IDLE_TIMEOUT_MS;
    }
  }
  for (const [sessionId, terminalSession] of terminalSessions.entries()) {
    if (await closeExamTerminalSessionIfUnavailable(terminalSession)) continue;
    const lastActivityAt = Number(terminalSession.lastActivityAt || terminalSession.createdAt || 0);
    if (now - lastActivityAt > terminalSessionIdleTimeoutMs) {
      if (typeof terminalSession.closeForIdle === "function") {
        terminalSession.closeForIdle();
      } else {
        forgetTerminalSession(sessionId);
      }
    }
  }
}, 60000);
